-- biosecurity_rule 적재 (status='draft') — knowledge-base/sop/biosecurity_rule_draft.csv, knowledge-base/sop/fmd_clauses.csv, knowledge-base/sop/lsd_clauses.csv, knowledge-base/law/law_clauses.csv
BEGIN;
DELETE FROM biosecurity_rule WHERE status='draft' AND kind='action' AND source_doc='구제역 긴급행동지침(SOP)';
DELETE FROM biosecurity_rule WHERE status='draft' AND kind='action' AND source_doc='럼피스킨 긴급행동지침(SOP)';
DELETE FROM biosecurity_rule WHERE status='draft' AND kind='clause' AND source_doc='가축전염병 예방법';
DELETE FROM biosecurity_rule WHERE status='draft' AND kind='clause' AND source_doc='가축전염병 예방법 시행규칙';
DELETE FROM biosecurity_rule WHERE status='draft' AND kind='clause' AND source_doc='구제역 긴급행동지침(SOP)';
DELETE FROM biosecurity_rule WHERE status='draft' AND kind='clause' AND source_doc='럼피스킨 긴급행동지침(SOP)';
DELETE FROM biosecurity_rule WHERE status='draft' AND kind='form_field' AND source_doc='가축전염병 예방법 시행규칙';
DELETE FROM biosecurity_rule WHERE status='draft' AND kind='photo_guide' AND source_doc='구제역 긴급행동지침(SOP)';
DELETE FROM biosecurity_rule WHERE status='draft' AND kind='photo_guide' AND source_doc='럼피스킨 긴급행동지침(SOP)';
DELETE FROM biosecurity_rule WHERE status='draft' AND kind='question' AND source_doc='구제역 긴급행동지침(SOP)';
DELETE FROM biosecurity_rule WHERE status='draft' AND kind='question' AND source_doc='럼피스킨 긴급행동지침(SOP)';
DELETE FROM biosecurity_rule WHERE status='draft' AND kind='summary' AND source_doc='구제역 긴급행동지침(SOP)';
COMMIT;
SELECT kind, source_doc, count(*) FROM biosecurity_rule WHERE status='draft' GROUP BY 1, 2 ORDER BY 1, 2;
