INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('action', 'FMD', 'after_report', '확산 방지를 위하여 의심축을 격리시키고 모든 사육동물(개, 고양이, 닭 등 포함)을 묶거나 축사 문을 닫아 이동하지 못하도록 한다.', '구제역 긴급행동지침(SOP)', '제4장 4 의심축 발견 축산관련 종사자의 조치 사항 2.2.2 (문서 p.77~78)', '2026-05-06'::date, 'draft', 1, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('action', 'FMD', 'after_report', '농장의 출입구를 1개소로 하고 소독조를 설치하여 방역관계자 이외에는 출입을 금지한다.', '구제역 긴급행동지침(SOP)', '제4장 4 의심축 발견 축산관련 종사자의 조치 사항 2.2.2 (문서 p.77~78)', '2026-05-06'::date, 'draft', 2, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('action', 'FMD', 'after_report', '농장 사육시설, 옥외, 농장 밖으로 원유, 사료, 퇴비 등을 반출하지 못하도록 한다.', '구제역 긴급행동지침(SOP)', '제4장 4 의심축 발견 축산관련 종사자의 조치 사항 2.2.2 (문서 p.77~78)', '2026-05-06'::date, 'draft', 3, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('action', 'LSD', 'after_report', '확산 방지를 위하여 의심축을 격리시키고 모든 사육동물(개, 고양이, 닭 등 포함)을 묶거나 축사 문을 닫아 이동하지 못하도록 한다.', '럼피스킨 긴급행동지침(SOP)', '2. 의심축을 발견한 축산관련 종사자의 조치사항 2.1.2 (문서 p.36)', '2024-07-19'::date, 'draft', 1, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('action', 'LSD', 'after_report', '농장의 출입구를 1개소로 하고 소독조를 설치하여 방역관계자 이외에는 출입을 금지한다.', '럼피스킨 긴급행동지침(SOP)', '2. 의심축을 발견한 축산관련 종사자의 조치사항 2.1.2 (문서 p.36)', '2024-07-19'::date, 'draft', 2, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('action', 'LSD', 'after_report', '농장 사육시설, 옥외, 농장 밖으로 원유, 사료, 퇴비 등을 반출하지 못하도록 한다.', '럼피스킨 긴급행동지침(SOP)', '2. 의심축을 발견한 축산관련 종사자의 조치사항 2.1.2 (문서 p.36)', '2024-07-19'::date, 'draft', 3, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('form_field', NULL, NULL, '신고대상 가축의 소유자등의 성명(축산계열화사업자의 경우에는 회사ㆍ법인명으로 한다) 및 신고대상 가축의 사육장소 또는 발견장소', '가축전염병 예방법 시행규칙', '제13조 제1항 제1호', '2020-05-28'::date, 'draft', 1, NULL, NULL, NULL);
