INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('form_field', NULL, NULL, '질병명(수의사의 진단을 받지 아니한 때에는 신고자가 추정하는 병명 또는 발견당시의 상태)', '가축전염병 예방법 시행규칙', '제13조 제1항 제3호', '2020-05-28'::date, 'draft', 3, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('form_field', NULL, NULL, '죽은 연월일(죽은 연월일이 분명하지 아니한 때에는 발견 연월일)', '가축전염병 예방법 시행규칙', '제13조 제1항 제4호', '2020-05-28'::date, 'draft', 4, NULL, NULL, NULL);
