INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('form_field', NULL, NULL, '그 밖에 가축이 죽거나 병든 원인 등 신고에 관하여 필요한 사항', '가축전염병 예방법 시행규칙', '제13조 제1항 제6호', '2020-05-28'::date, 'draft', 6, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('summary', 'FMD', NULL, '가축소유자(관리인 포함)나 수의사 등 축산관련 종사자 등은 가축에서 입, 혀, 발굽, 젖꼭지 등에 물집(수포)을 형성하거나 고열, 식욕부진, 거품 섞인 침흘림, 궤양, 가피 등 구제역 의심증상이 있는 의심축을 발견하면 즉시 구제역 신고 전용전화(1588-4060, 1588-9060) 또는 다음 각 호의 기관에 신고하여야 한다.', '구제역 긴급행동지침(SOP)', '1. 구제역 의심축 발생 신고 1.1 (장·쪽 확인 필요)', '2026-05-06'::date, 'draft', 1, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1 정 의 구제역(口蹄疫, FMD ; foot and mouth disease)은 소, 돼지, 양, 염소, 사슴 및 야생 반추류 등과 같이 발굽이 둘로 갈라진 우제류(偶蹄類) 동물에서 체온이 급격히 상승하고 거품 섞인 침흘림, 입·혀·발굽 또는 젖꼭지 등에 물집, 가피, 궤양 등이 나타나며, 식욕이 저하되어 심하게 앓거나 죽게 되는 전파력이 매우 강한 전염병이다. 이 질병은 가축전염병 예방법상 제1종 가축전염병이며, 세계동물보건 기구(WOAH)에서 관리대상 질병으로 분류·지정하고 있으며 발생 시 WOAH에 보고해야 하는 질병이다.', '구제역 긴급행동지침(SOP)', '제1장 구제역 개요 1 (PDF p.9)', '2026-05-06'::date, 'draft', 1, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2 병원체 구제역의 병인체는 피코나바이러스과(Picornaviridae) 아프토바이러스속(Aphthovirus)에 속하는 RNA 바이러스이며 7개의 혈청형(A, O, C, Asia 1, SAT 1, SAT 2 및 SAT 3)이 있다. 바이러스의 VP1 단백질에 해당하는 유전자(약 639bps) 부위의 염기서열 유사도가 상호 간에 대략 85% 이상인 경우 하나의 분류를 형성하는데 이러한 분류는 지역성을 나타내는 경우가 대부분이어서 지역형(topotype)으로 불리고 있다. 혈청형은 여러 가지 지역형으로 나뉘고, 지역형 내에도 유전적으로 다양한 계통(Lineage)이 존재한다. 혈청형이 다른 바이러스 간에는 혈청학적으로 중화가 되지 않고 백신에 의한 방어가 되지 않을 만큼 유전적 또는 항원적으로 큰 차이를 보인다. [그림1. 구제역 바이러스 구조] [그림2. 구제역 바이러스 유전체의 구성] 2000년 이후 국내에서 발생한 구제역 바이러스는 혈청형 O와 A가 유입된 바 있다. ｜참고｜ 표. 국내 발생 구제역 바이러스 계통 년도 혈청형/지역형/계통 2000 (1차) O/ME-SA/PanAsia 2002 (2차) O/ME-SA/PanAsia 2010 (3차) 2010 (4차) 2010 ~2011 (5차) A/ASIA/Sea-97 O/SEA/Mya-98 O/SEA/Mya-98 년도 2014 (6차) 2014 ~2015 (7차) 2016 (8차) 2017 (9차) 2018 (10차) 혈청형/지역형/계통 년도 혈청형/지역형/계통 O/SEA/Mya-98 2019 (11차) O/ME-SA/Ind-2001e O/SEA/Mya-98 2023 (12차) O/ME-SA/Ind-2001e O/ME-SA/Ind-2001e A/ASIA/Sea-97 2025 (13차) 2026 (14차) A/ASIA/Sea-97 - O/SEA/Mya-98 O/ME-SA/Ind-2001e O/ME-SA/Ind-2001e -', '구제역 긴급행동지침(SOP)', '제1장 구제역 개요 2 (PDF p.9~10)', '2026-05-06'::date, 'draft', 2, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3 감염경로 구제역은 코, 입 등 호흡기와 상처 입은 피부 등을 통해 감염되며, 일반적으로 소는 비말 중의 바이러스가 상부기도에 침입하여 여기에서 증식한 후 혈류를 통하여 전신에 확산하는 감염양식이 일반적이다. 또한 피부나 점막의 상처를 통하여 감염 될 수 있으나 그 확률은 매우 낮다. 돼지는 바이러스에 오염된 음식물을 먹거나 감염된 동물과 접촉할 경우 감염될 수 있으며, 비말로는 감염되기 어렵다.', '구제역 긴급행동지침(SOP)', '제1장 구제역 개요 3 (PDF p.10)', '2026-05-06'::date, 'draft', 3, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4 전파방법 구제역 바이러스는 매우 급속도로 전파되며, 크게 4가지 경로를 통해서 확산된다. 첫째, 감염동물의 수포액이나 침, 유즙, 정액, 비말 공기 및 분뇨 등에 접촉하여 이루어지는 직접 접촉 전파이다. 특히, 감염 초기에 아직 임상증상이 나타나지 않은 상태에서 바이러스 배출도 상당하므로 감염된 개체와 감염이 의심되는 개체의 이동을 확실히 통제해야 한다. 둘째, 감염지역 내 사람(농장종사자, 수의사, 인공수정사 등 축산 관련 종사자), 차량(사료차, 출하차, 집유차 등) 및 차량기사, 의복, 물, 사료, 장비, 기구 등에 의한 간접 접촉 전파이다. 셋째, 오염된 농장(지역)의 가축과 가축의 분비물 및 배설물 등에 쉽게 접촉할 수 있는 쥐, 조류, 곤충, 개, 고양이 등에 의한 기계적인 매개 전파이다. 넷째, 일정한 요건을 갖출 경우 공기(바람)를 통해서도 전파되는데 육지에서는 60km, 바다를 통해서는 250km 이상 떨어진 곳까지 전파가 가능하다. 또한 구제역 바이러스에 오염된 식육과 식육부산물 등 축산물을 통해서도 전파된다.', '구제역 긴급행동지침(SOP)', '제1장 구제역 개요 4 (PDF p.10~11)', '2026-05-06'::date, 'draft', 4, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5 잠복기간 구제역의 잠복기간은 보통 2일에서 8일 정도로 매우 짧으며 세계동물보건기구 (WOAH)는 최대 잠복기를 14일로 본다. 6 축종별 임상증상 구제역 바이러스에 감염된 소는 체온상승, 식욕부진, 침울, 우유 생산량의 급격한 감소 등이 나타난다. 발병 후 24시간 이내에 잇몸과 혀 등에 수포가 생기고, 거품 섞인 침을 심하게 흘리며 입맛을 다시는 소리(“딱! 딱!”)를 내기도 한다. 수포는 발굽의 지간부(발굽사이)와 제관부(발굽갓띠), 유두 등에서도 관찰되며, 곧 파열되어 피부가 드러나 출혈이 생기고 궤양으로 발전한다. 발굽 갓띠 지간부 제관부 제구부 제종부 제저부 [그림3. 우제류 발굽 구조] (출처: 가축전염병의 이해, 가축위생방역지원본부) 일반적으로 이환율은 높고 폐사율은 낮은 편이나, 어린 송아지의 경우 성우에 비하여 폐사율이 높다. 성우의 경우 폐사율은 5% 미만으로 낮으며 임신한 소에서는 유산이 발생할 수 있다. 감염된 소는 1주일 이상 거의 먹지 못하며, 파행을 보이고, 젖소에서는 유방염, 산유량 급감(약 50%) 등으로 경제적 피해가 발생한다. 감염된 6개월 미만의 송아지는 심근염에 의해 폐사하는 경우가 있으며, 이 경우 심근에 나타나는 특징적인 병변을 호반심(tiger heart)이라고 한다. [그림4. 소의 임상증상 사례] 거품 섞인 침 흘림 콧구멍 주변의 궤양 윗잇몸 주변의 궤양 혀의 궤양 유두의 백색 수포 유두의 수포 파열 후 가피 앞발굽 사이의 수포 뒷발굽 사이의 궤양과 가피 돼지 돼지에서 특징적으로 관찰되는 증상은 파행이며, 발굽의 심한 병변과 고통으로 인해 제대로 서거나 걷지 못하고 절룩거리거나 무릎으로 기어다닌다. 발굽의 수포가 파열되어 피부가 벗겨진 자리에 세균에 의한 2차 감염이 일어나고 이로 인해 발톱이 탈락되기도 한다. 입 주변의 수포 형성은 소의 경우처럼 전형적이지는 않으나, 콧잔등에는 큰 수포가 형성되며 쉽게 터지는 경우가 많으며, 모돈의 경우 유두 및 유방에서 수포를 관찰 할 수 있다. 새끼 돼지의 폐사율은 50% 정도이며 비육돈도 드물게 폐사한다. [그림5. 돼지의 임상증상 사례] 콧등의 수포 콧등의 수포 유방의 수포 유방의 수포 파열 후 가피 발굽 사이의 궤양 발굽의 탈락 혀의 궤양 양·염소 양과 염소의 임상증상은 바이러스 주, 동물의 품종, 환경 상태 등에 따라 매우 다양하며, 일부 바이러스는 임상증상이 약하므로 주의 깊게 관찰해야 한다. 초기 임상증상은 식욕부진, 발열, 심한 파행 및 어린 동물의 갑작스러운 폐사가 나타나며, 어린 양의 경우 다발성 심근염으로 치사율이 비교적 높은 편이다. 젖을 생산하는 양과 염소는 초기에 갑작스러운 유량의 감소가 나타나며, 유두나 질, 지간부(발굽사이) 공간, 제종(발굽 뒤꿈치) 및 제관부(발굽갓띠)에 수포가 발생하며, 수컷은 음경에도 수포가 형성된다. 구강 병변은 괴사된 상피로 인해 작고 표백된 부위가 형성되며, 대부분 치아 받침에 보인다. 표면의 괴사층은 미란(표피박리, erosion)의 형성으로 인해 빠르게 소실되며,', '구제역 긴급행동지침(SOP)', '제1장 구제역 개요 5 (PDF p.11~14)', '2026-05-06'::date, 'draft', 5, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '수포액이 있는 액체는 보통 관찰되지 않으며 일시적으로 형성되어도 표면상피가 얇아 쉽게 파열된다. 미란은 입술 안쪽의 잇몸에서 보이며 종종 혀에서 보인다. 혀의 미란은 표면에 다발성으로 혓바닥에서 0.5~1.0cm 크기로 작게 형성된다. 염소의 병변은 양에서 보다 적으며 덜 심하고, 입 부분은 빠르게 치유된다. 다만, 2차 감염이 있을 경우 파행은 지속되며 무릎이 떨리는 증상이 보이며, 힘없이 벽에 기대있다. 사슴 일반적으로 감염 후 2~20일에 임상증상을 나타내는데, 파행 및 타액 분비와 같은 구제역의 특이 임상증상을 쉽게 볼 수 없다. 품종별로 병원성의 정도가 매우 다양하다. 레드디어(Red deer)와 다마사슴 (Fallow deer)은 증상이 미약하고, 노루 및 문착사슴(Muntjacs)은 종종 심한 증상을 보인다. 꽃사슴은 증상이 심하지 않으나 감염 후 바이러스를 28일 이상 체내에 보유하고 있어 일정 기간 전파가 가능하며, 엘크는 자연 감염될 수 있으나 임상증상을 관찰하기는 어려우며, 같이 사육되는 엘크끼리 또는 소에 전파되기 어렵다. 임상증상이 미약한 경우가 많아 구제역 감염 여부는 임상검사뿐만 아니라 정밀 검사를 실시하여 확인해야 한다.', '구제역 긴급행동지침(SOP)', '제1장 구제역 개요 (PDF p.14~15)', '2026-05-06'::date, 'draft', 6, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '7 진단 진단은 동물 체내의 구제역 바이러스 존재 여부를 확인하는 항원진단법과 감염 결과 형성된 항체를 검출하는 항체진단법이 있다. 항원진단법은 수포액, 수포형성 상피세포, 타액 또는 인후두 부위 채취액 등 검사시료를 세포 배양하여 구제역 바이러스 분리하거나 역전사 중합효소연쇄반응 (RT-PCR)법을 이용한 구제역 바이러스 특이 유전자 검출, 항원검출용 ELISA 검사 등을 이용한 방법이 주로 이용된다. 항체진단법은 동물의 혈액을 채취하여 혈청 내 구제역 바이러스의 항체 형성 여부를 검출하는 혈청중화시험, 항체검사용 ELISA 검사법 및 보체결합반응 등이 주로 이용된다. 현재 국내에서는 RT-PCR 검사, ELISA 검사 및 혈청중화시험 등이 확정진단에 활용되고 있다. 2002년 구제역 발생 현장에서 신속 진단을 위한 간이진단키트를 세계 최초로 적용된 바 있으며, 2018년부터는 혈청형 확인이 가능한 간이진단키트도 배부되어 더욱 신속한 대응이 가능해졌다. 용어 정의 우제류 동물 : 동물 중 발굽이 둘로 갈라져 있는 소, 돼지, 면양, 산양, 사슴, 낙타 등을 말하며 여기에 속한 동물은 모두 구제역에 감수성을 갖고 있다. 세계동물보건기구(WOAH) : 동물 질병 방제에 대한 국제적 협력을 위하여 1924년 28개국의 참여로 The Office International des Epizooties(OIE)를 창설한 이래 2022년 5월에 The World Organisation for Animal Health(WOAH)로 이름을 변경하였다. 구제역 표준연구소 : 세계 동물보건기구(WOAH) 및 국제 식량농업기구(FAO)에서 구제역 진단을 공인한 실험실로 영국 퍼브라이트 연구소(Pirbright Lab.)가 대표적인 구제역세계표준연구소(World Reference Laboratory for FMD, WRLFMD)이다. 환축 : 구제역 의사환축에 대한 정밀검사를 실시하여 구제역에 감염된 것으로 확인된 가축을 말한다. 의심축 : 가축의 소유자, 관리자 또는 축산관련 종사자 등이 구제역으로 의심되어 신고한 가축으로 시도 가축방역기관 가축방역관이 확인하기 전의 가축을 말한다. 의사환축 : 검역본부 또는 시도 가축방역기관 소속의 가축방역관이 임상검사 등을 실시한 결과 구제역에 걸렸다고 믿을만한 상당한 이유가 있다고 판단한 가축을 말한다. 의심축 신고상황 : 가축의 소유자, 관리자 또는 축산관련 종사자 등이 구제역에 감염된 것으로 의심되어 가축방역기관에 유선 등을 통하여 신고된 상황을 말한다. 신고 : 가축소유자 또는 축산관련 종사자 등이 구제역에 감염된 것으로 의심되어 가축방역기관에 유선 등을 통하여 알리는 것을 말한다. 축산농장 : 한·육우, 낙농우, 돼지, 염소, 양 등 우제류를 사육하는 농장을 말한다. 축산관련 종사자 : 임상수의사, 수집상, 중개상, 가축분뇨 기사, 동물약품·사료· 축산기자재 판매자, 농장관리자, 가축운반기사, 사료운반기사, 컨설팅 등 우제류 축산농장 및 관련 작업장 등에 종사하는 모든 사람을 포함한다.', '구제역 긴급행동지침(SOP)', '제1장 구제역 개요 7 (PDF p.15~16)', '2026-05-06'::date, 'draft', 7, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '축산관련 작업장 : 우제류 도축장, 사료공장, 사료하치장, 사료대리점, 분뇨처리장, 공동퇴비장, 가축분뇨공공 처리장, 공동자원화시설, 축산 관련운반업체, 축산관련 용역업체, 축산시설장비 설치·보수업체, 축산 컨설팅업체, 퇴비제조업체, 종축장, 동물약품 및 축산기자재 판매업체 등을 포함한다. 발생농장 : 구제역 의심축, 의사환축 또는 환축이 발생된 가축의 사육시설(축사)이 있는 농장 발생지 : 발생농장이 소재한 마을로서 리 단위보다 작은 동일한 생활권 부락 단위 개념으로 쥐 등 야생동물의 이동거리 등을 감안하여 시장·군수·구청장이 시도 가축방역 기관장과 협의하여 설정한다. 발생지역 : 발생농장이 소재한 시군구 인접지역 : 발생지역과 경계가 닿아 있거나 생활권을 같이하는 시군구 관리지역 : 구제역에 오염되었거나 오염되었다고 의심되는 지역으로 발생농장을 중심으로 하여 반경 500m 이내의 지역을 말한다. 다만, 시장·군수·구청장은 해당 지역의 축산업 형태, 지형적 여건, 생활권, 계절적 요인 또는 역학적 특성 등을 감안하여 관리지역의 범위를 시도지사 소속 지방 가축방역심의회위원, 시도 및 시군구 관계관 및 농림축산검역본부 현지 파견담당관과 협의를 거쳐 이를 확대 하거나 축소할 수 있다. 보호지역 : 구제역의 추가 발생이 우려되는 지역으로서 발생농장을 중심으로 하여 반경 500m부터 3km 이내의 지역을 말한다. 다만, 시장·군수·구청장은 해당 지역의 축산업 형태, 지형적 여건, 생활권, 계절적 요인 또는 역학적 특성 등을 감안하여 보호지역의 범위를 시도지사 소속 지방 가축방역심의회위원, 시도 및 시군구 관계관, 검역본부 현지 파견담당관과 협의를 거쳐 이를 확대하거나 축소할 수 있다. 예찰지역 : 백신 미접종 유형의 구제역 확산이 우려되는 지역으로서 발생농장을 중심으로 반경 3km를 초과하여 10km 이내의 지역을 말한다. 다만, 시장·군수· 구청장은 해당 지역의 축산업 형태, 지형적 여건, 생활권, 계절적 요인 또는 역학적 특성 등을 감안하여 예찰지역의 범위를 시도지사 소속 지방 가축방역심 의회위원, 시도 및 시군구 관계관, 검역본부 현지 파견담당관과 협의를 거쳐 이를 확대하거나 축소할 수 있다. 권역 : 기본적으로 시도 또는 시군구로 구분된 행정구역으로, 필요시 검역본부장이 가축방역을 목적으로 가축의 사육밀도, 사료공급, 종축이동, 도축장 이용형태 등 역학사항을 고려하여 지역을 구획화한 것을 말한다. 구제역이 발생한 권역을 “발생권역”이라 한다. 방역지역 : 관리지역, 보호지역, 예찰지역을 말한다. 시도 구제역 정밀진단기관 : 시도 가축방역기관으로서 일정한 조건을 갖추고 구제역 의심축, 의사환축 및 바이러스 전파 위험 요인에 대한 시료 채취, 임상검사 및 실험실 진단을 실시할 수 있도록 검역본부장이 지정한 기관 의사환축 검사 : 시도 가축방역기관의 가축방역관이 임상검사 등을 실시한 결과 구제역에 걸렸다고 믿을만한 상당한 이유가 있는 가축에 대해 실시하는 구제역 정밀검사를 말한다.', '구제역 긴급행동지침(SOP)', '제1장 구제역 개요 (PDF p.16~18)', '2026-05-06'::date, 'draft', 8, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '병성감정 검사 : 구제역 의심축 신고농장에 대해 시도 가축방역기관 가축방역관이 임상검사 등을 실시한 결과 구제역 의사환축으로 판단이 어렵거나 구제역 이외의 가축질병으로 의심되는 경우 구제역을 포함한 가축전염병 감염여부를 확인하는 정밀검사를 말한다. 예방적살처분 검사 : 구제역의 추가확산 또는 발생을 사전에 예방하기 위하여 발생 농장을 중심으로 구제역이 퍼지는 것이 우려되는 지역 안에 있는 우제류 가축을 살처분할 때 구제역 감염 여부를 확인하는 정밀검사를 말한다. 역학관련 검사 : 구제역 발생농장 또는 구제역 오염시설과 역학적으로 관련이 있는 차량이나, 농장 또는 시설 내 우제류 동물 등에 대하여 구제역 오염여부를 확인 하는 정밀검사를 말한다. 예찰 검사 : 방역지역 내 농장 또는 시설 내 우제류 동물에 대하여 구제역 감염 여부를 확인하는 정밀검사를 말한다. 잠복기 : 특정병원체가 동물에 침입한 후 그 질병의 최초 임상증상이 발현될 때까지 소요되는 기간을 말한다. 살처분 : 구제역에 걸렸거나 걸렸다고 믿을만한 역학조사·정밀검사 결과나 임상 증상이 있는 경우 해당 가축이 있는 농장 또는 해당 가축이 있었던 장소를 중심 으로 구제역이 퍼지는 것이 우려되는 지역 안에 있는 감수성 가축을 안락사 후 매몰하는 것을 말한다. 소독 : 전염병 병원체를 사멸시키기 위해 실시하는 작업을 뜻하며, 소독은 동물, 가축분뇨 또는 동물 유래의 생산물 등에 의해 직접 혹은 간접적으로 오염될 수 있는 동물, 사람, 시설, 수송차량 및 기타 대상물에 대해 실시한다. 거점소독시설 : 시설출입차량이 방역 관련 규정에 따라 이동 시 소독을 실시하고 소독필증을 발급하는 시설로, 시군구 또는 시·도 가축방역기관이 설치·운영하는 시설 및 관련 지침에 따라 별도로 지정받은 민간시설을 말한다. 가축 등에 대한 일시 이동중지(Standstill) : 구제역이 국내에서 발생하였거나 전국적 으로 확산되어 심각한 피해가 발생할 것으로 판단되는 경우, 전국(또는 지역별)의 모든 우제류 축산농장 및 관련 작업장 등에 가축·사람·차량·물품 등의 출입을 일시 중지(48시간 이내 - 필요시 연장)하는 조치를 말한다. SP항체 : 바이러스의 Structural Protein(구조단백질)에 의해 감염 후 약 6~8일경에 동물의 체내에서 생성된다. 백신접종과 자연감염 시 모두 생성되는 항체이다. NSP항체 : 바이러스의 Non-Structural Protein(비구조단백질)에 의해 감염 후 약 10~12일경 동물의 체내에서 생성된다. 자연감염 시에만 생성되는 항체이다. 긴급 백신(Emergency Vaccination) : 구제역이 발생한 경우 긴급하게 발생농장을 중심으로 일정범위내의 우제류 가축 또는 일부 축종에 대해 실시하는 링-백신, 일정 지역내의 우제류 가축에 대하여 실시하는 지역 백신, 인접 지역의 우제류 가축에 대해 광범위하게 실시하는 장벽 백신, 전국 단위 우제류가축에 대해 실시하는 전국 백신을 말한다.', '구제역 긴급행동지침(SOP)', '제1장 구제역 개요 (PDF p.18~19)', '2026-05-06'::date, 'draft', 9, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '정기 백신(Systematic Vaccination) : 백신접종 프로그램에 따라 상시 실시하는 것을 말한다. 백신접종 유형 : 백신접종 유형이라 함은 국내 사용중인 백신에 포함된 백신주의 혈청형과 야외 발생 구제역바이러스와의 혈청형이 일치하는 경우를 의미한다. (단, 혈청형이 동일하더라도 바이러스간 면역학적 상관성이 낮아서 야외주에 대한 국내 사용 백신주의 방어효능이 충분치 않거나, 현장 여건이 백신의 방어효과를 충분히 발휘할 수 없는 상황이라고 판단되는 경우 백신미접종 유형에 준하는 방역조치를 취할 수 있음) 백신미접종 유형 : 백신미접종 유형이라 함은 국내 사용 중인 백신에 포함된 백신주의 혈청형과 야외 발생 구제역 바이러스의 혈청형이 일치하지 않는 경우를 의미한다. 이동제한 : 전염병의 확산 및 전파를 차단하기 위해서 오염되었거나 역학적으로 관련된 가축·시설·물건·차량·사람 등에 정해진 기간 동안 이동을 차단하는 것을 말한다. 역학조사 : 가축전염병 발생 시 역학적 특성을 파악하여 이 질병에 관한 유입 및 전파·확산 위험요인을 찾아내고 규명하는 과정을 말한다. 위험도평가 : 구제역 발생 관련 이동제한 중인 가축·분뇨 등의 이동 또는 축산 시설의 운영을 위해 축산업형태, 지형적 여건, 야생동물의 서식실태, 계절적요인, 역학적 특성 및 정밀검사 등을 감안하여 위험성을 평가하는 조치를 말한다.', '구제역 긴급행동지침(SOP)', '제1장 구제역 개요 (PDF p.19)', '2026-05-06'::date, 'draft', 10, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1 의심축 신고 및 의사환축 발생 시 조치사항 1. 구제역 의심축 발생 신고 1.1 가축소유자(관리인 포함)나 수의사 등 축산관련 종사자 등은 가축에서 입, 혀, 발굽, 젖꼭지 등에 물집(수포)을 형성하거나 고열, 식욕부진, 거품 섞인 침흘림, 궤양, 가피 등 구제역 의심증상이 있는 의심축을 발견하면 즉시 구제역 신고 전용전화(1588-4060, 1588-9060) 또는 다음 각 호의 기관에 신고하여야 한다. ▷ 시군(읍·면·동 포함) 가축방역업무 담당과 ▷ 시도 및 시도 가축방역기관(동물위생시험소 등) ▷ 농림축산검역본부(방역감시과) ▷ 농림축산식품부(구제역방역과)', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 1 (PDF p.69)', '2026-05-06'::date, 'draft', 11, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.2 가축소유자(관리인 포함)나 수의사 등 축산관련 종사자 등으로부터 의심축 신고를 받은 기관은 가축소유자 등에 대해 아래의 조치를 하고, 즉시 시도, 시도 가축방역기관 및 검역본부에 보고하여야 한다. - 농장 내에 머물도록 지시하고 항상 연락이 가능하도록 조치 - 농장의 가축, 분뇨, 장비, 물품 등의 이동제한 조치 - 농장의 가축수송차량, 집유차 및 기타 차량의 출입 제한 - 농장 내 모든 사람의 외출 금지', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 1.2 (PDF p.69)', '2026-05-06'::date, 'draft', 12, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.3 축산관련 종사자 등이 의심축을 신고한 경우 ’제4장 4. 의심축 발견 축산관련 종사자의 조치사항’에 따라 조치한다. ※ 의심축 신고상황 보고체계 : 읍·면·동→시군구, 시도 가축방역기관→시도, 농림 축산식품부, 검역본부', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 1.3 (PDF p.69)', '2026-05-06'::date, 'draft', 13, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.4 다만, 축산관련 종사자 등이 가축위생방역지원본부에 신고한 경우, 가축위생 방역지원본부는 해당 시군구, 시도 가축방역기관에게 신고내역을 즉시 알리고, 해당 시군구 및 시도 가축방역기관은 의심축 신고상황 보고체계에 따라 시도, 농림축산검역본부, 농림축산식품부에 즉시 보고해야 한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 1.4 (PDF p.69)', '2026-05-06'::date, 'draft', 14, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2. 의심축 발생 신고 접수 및 초기 조치사항 2.1. 의심축 신고(통보)를 받은 시도 가축방역기관은 ‘별지 제1호 서식 구제역 의심축 신고서’를 작성하여 시도, 농식품부, 검역본부에 보고하여 지시를 받아야 하며, 검역본부에서 운영하는 국가가축방역통합시스템(이하 ‘KAHIS’라 한다)에 의심축 신고서를 등록하여야 한다. - 의심축 발생농장에 대한 역학조사 후 역학정보를 검역본부 및 농식품부에 보고 (알림)한다. 검역본부는 의심축 발생농장에 대한 역학정보를 추가로 파악하여 농식품부에 보고하고 필요 시 역학조사반을 현장에 출동시켜야 한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 2 (PDF p.70)', '2026-05-06'::date, 'draft', 15, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.2. 시도 가축방역기관장은 시도, 농식품부, 검역본부에 의심축 신고상황 보고 후 해당 농장에 구제역 전담 가축방역관 2명 이상을 출동시킨다. 다만, 발생이 확산 되어 구제역 전담 가축방역관의 운영이 원활하지 않을 경우 그러하지 아니하다. - 시도 구제역 전담 가축방역관은 검역본부에서 실시하는 관련 교육을 매년 이수하여야 한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 2.2 (PDF p.70)', '2026-05-06'::date, 'draft', 16, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.3 시도 가축방역기관장은 구제역 전담 가축방역관이 의심장소까지 도착하는 데 장시간이 소요될 것으로 예상되는 경우에는 해당 시군구 관계관으로 하여금 신고농장에 먼저 도착토록 하여 이동제한 등 차단방역을 실시하도록 조치한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 2.3 (PDF p.70)', '2026-05-06'::date, 'draft', 17, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.4 시도 구제역 전담 가축방역관은 의심장소로 출발할 때에는 의심축 신고서 사본과 구제역 방역실시요령(농림축산식품부 고시) ‘별표 1. 검사시료채취 준비물’ 및 구제역긴급행동지침 ‘별표 7. 초기검진 시의 긴급방역용 용구’를 휴대하여야 한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 2.4 (PDF p.70)', '2026-05-06'::date, 'draft', 18, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3. 구제역 의심축 신고 농장 도착 후의 조치(시도 가축방역기관) 3.1 현장에 도착한 가축방역관 등은 타고 온 차량은 농장 밖에 주차하고, 위생 작업복·장화 착용 및 소독 등 개인 방역조치를 취하고 농장에 들어간다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 3 (PDF p.70)', '2026-05-06'::date, 'draft', 19, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.2 가축방역관 등은 의심축 신고농장 내 모든 동물에 대해 임상검사를 실시한다. - 1명은 의심축이 있는 축사, 나머지 1명은 의심축이 없는 축사의 동물에 대해 임상검사를 실시한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 3.2 (PDF p.70)', '2026-05-06'::date, 'draft', 20, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.3 임상검사 과정에서 수포 등 임상증상을 확인한 경우 수포액을 채취하여 간이 항원 진단키트로 검사하고, 정밀검사용 시료를 채취한다. 만약 간이 항원 진단키트 검사결과가 양성으로 판정되면 시군으로 하여금 감염개체(항원 양성 및 임상 증상 개체)에 대하여 즉시 살처분 조치한다. - 간이 항원 진단키트 검사는 ‘별표 9. 혈청형 판별 간이 항원 진단키트 사용 방법’에 따라 실시한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 3.3 (PDF p.70~71)', '2026-05-06'::date, 'draft', 21, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.4 시도 가축방역관은 간이 항원 진단키트를 현장에서 사용하면 그 결과와 관계 없이 검역본부에 보고한다. 3.5 농장에서 벗어날 때에는 세척 및 소독 등 방역조치를 하여야 한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 3.4 (PDF p.71)', '2026-05-06'::date, 'draft', 22, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4. 의심축 신고농장 임상검사결과 등에 따른 조치(시도 가축방역기관) 4.1 의사환축으로 판단되는 경우 - 임상검사 결과 또는 간이 항원 진단키트에서 양성일 경우나 구제역 의사환축으로 확인되는 경우 즉시 소속기관장에게 보고 - 시도 방역기관장은 ‘별지 제2호 서식 의사환축 발생신고서’에 따라 해당 동물 등에 대한 검진과 가축의 이동상황, 분뇨의 이동, 출입자현황 등 역학조사를 실시하고 시도(시군구)에 보고(통보)하고 이를 KAHIS에 등록한다. - 시도 가축방역기관 가축방역관은 간이 항원 진단키트 양성의 경우, 발생농장 역학조사를 실시하고 방역조치 대상을 선정하여 농식품부, 전국 시도 및 시군구, 검역본부에 즉시 알림 - 시도 가축방역관은 시료를 채취한 후 즉시 검역본부로 송부한다. 단, 시도 구제역 정밀진단기관인 경우 동등한 시료 2세트를 채취한 후 1세트는 자체적 으로 정밀검사를 실시하고 나머지 1세트는 즉시 검역본부로 송부한다. - 발생농장에 대한 가축·차량·사람(가축소유자·종사자·수의사·축산관련종사자 등)· 물품 등에 대하여 정밀검사가 나올 때까지 이동제한 등 차단방역을 실시한다. - 의사환축은 별도로 격리하고 농장주가 농장의 소독을 실시토록 조치한다. - 최종 검사결과가 나올 때까지 농장 내 또는 현장 통제초소에서 현장방역조치를 지시한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 4 (PDF p.71)', '2026-05-06'::date, 'draft', 23, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4.2 의사환축으로 판단이 어려운 경우 - 가축방역관은 의사환축으로 판단이 어려운 경우 소속 기관장에게 보고하고, 시료를 채취하여 검역본부에 구제역 검사를 포함한 병성감정을 의뢰한다. 다만, 구제역 정밀진단기관으로 지정된 시도 가축방역기관은 동등한 시료 2세트를 채취한 후 1세트로 구제역 검사를 포함한 병성감정을 실시하고, 구제역 양성인 경우 나머지 1세트를 즉시 검역본부로 송부한다. - 구제역 검사결과가 나올 때까지 해당 농장의 가축·차량·사람·물품 등의 이동 통제 등 방역조치를 유지하고, 구제역 검사결과 음성으로 판정 시 방역조치를 해제한다. * 농장의 일반 질병 또는 폐사축 신고 등 일상적인 예찰과정에서 의사환축 발견 시 가축방역관은 소속 기관장에게 보고 후 의심축 발생과 동일한 방역조치 추진', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 4.2 (PDF p.71~72)', '2026-05-06'::date, 'draft', 24, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5. 의심축 신고 또는 의사환축 발생 시 기관별 방역조치사항 5.1 시장·군수·구청장의 조치사항 5.1.1 해당농장에 대한 가축·사람·차량 등의 이동제한 조치를 한다. - 가축위생방역지원본부의 초동방역팀과 농협 공동방제단을 현장에 투입한다. - 해당 농장의 출입구를 1개소로 제한하여 현장통제초소를 설치하고, 통제소에는 소독조·소독장비를 설치한다. 발생농장이 축산밀집지역에 위치하는 경우 인접한 축사·도로현황 등을 고려하여 통제소를 설치한다. - 가축소유자로 하여금 농장 내 축사·운동장·차량·축산기자재 등에 대한 청소 (세척)·소독, 사람에 대해 소독하도록 조치한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5 (PDF p.72)', '2026-05-06'::date, 'draft', 25, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.1.2 구제역 발생에 대비하여 방역지역 설정 등 아래의 방역 조치사항을 준비한다. - 방역지역(관리, 보호, 예찰) 설정 준비 및 방역지역별 농장현황 조사 - 방역지역별 통제초소 및 축산차량 전담 거점소독시설 설치 준비 - 모든 시군구는 주요 장소에 통제초소, 소독장소를 설치(전국) - 살처분·사체 처리, 이동통제, 소독, 예찰 등 초동방역을 위한 인력·장비·약품· 매몰지 등의 조달 준비 - 긴급백신접종을 위한 인력 동원체계 준비 - 구제역방역대책본부(본부장 : 기관장) 및 상황실 설치 준비(전국) - 일시 이동중지(Standstill) 시행에 대비, 상황 전파체계 준비 및 점검(전국) ※ 간이항원진단키트 양성 시 즉시 시행 가능', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.1.2 (PDF p.72)', '2026-05-06'::date, 'draft', 26, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.2 가축위생방역지원본부장의 조치사항 5.2.1 시장･군수·구청장, 시･도 가축방역기관장 또는 농식품부장관의 요청(지시)이 있을 경우 ‘제4장 5. 초동방역팀 운용요령’에 따라 초동방역팀을 투입하여 의심축 발생농장에 대한 가축･사람･차량 등의 출입금지 및 진입로 소독 등 초동 방역조치를 한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.2 (PDF p.73)', '2026-05-06'::date, 'draft', 27, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.2.2 해당 시군구, 인접 시군 및 역학농장 등의 이상여부 확인을 위해 ‘제4장 2. 구제역 임상관찰 및 예찰요령’에 따른 전화예찰을 실시한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.2.2 (PDF p.73)', '2026-05-06'::date, 'draft', 28, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.3 시도 가축방역기관장의 조치사항 5.3.1 시도(시군구) 및 검역본부에 ‘별지 제1호 서식 구제역 의심축 신고서’, ‘별지 제2호 서식 의사환축 발생신고서’를 작성하여 송부하고, KAHIS에 등록한다. - 다만, 가축이나 분뇨의 이동 등과 관련된 시급한 방역조치 대상이 있는 경우에는 해당 시도(시군구)에 즉시 통보한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.3 (PDF p.73)', '2026-05-06'::date, 'draft', 29, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.3.2 구제역 의심축 신고농장 내 모든 우제류 가축에 대한 임상검사를 실시하고, 임상증상 발현 개체에 대해 시료를 채취하여 검역본부에 신속히 송부한다. (간이 항원 진단키트 검사결과 양성일 경우, 발생농장 역학조사를 실시하고 방역조치 대상을 선정하여 농식품부,전국 시도/시군구, 검역본부에 즉시 알림) - 다만, 시도 구제역 정밀진단기관은 동등한 시료 2세트를 채취한 후 1세트는 자체적으로 정밀검사를 실시하여 확진하고, 나머지 1세트는 추가적인 정밀진단 (바이러스 분리, 혈청형, 유전자분석 등)을 위해 시료 채취 후 즉시 검역본부로 송부한다. - 시도 정밀진단기관에서 자체적으로 실시한 정밀검사 결과에 대해서 재검사가 필요하다고 판단하는 경우 검역본부에 재검사를 의뢰할 수 있다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.3.2 (PDF p.73)', '2026-05-06'::date, 'draft', 30, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.3.3 현장 파견중인 가축방역관에게 가축 및 분뇨 등의 이동사항, 출입자, 출입 차량 등에 대한 역학조사를 실시하도록 조치한다. 5.3.4 의사환축 판정 시 가축방역관을 추가 파견하여 해당농장 반경 500m 내외의 우제류 농장에 대해 임상관찰을 실시한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.3.3 (PDF p.73)', '2026-05-06'::date, 'draft', 31, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.3.5 발생농장의 이동제한, 소독 및 매몰 등 방역 기술지원을 위하여 가축방역관을 현장에 파견시킨다. 5.3.6 구제역 방역대책 상황실(실장 : 기관장) 설치를 준비한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.3.5 (PDF p.73)', '2026-05-06'::date, 'draft', 32, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.4. 시도지사의 조치사항 5.4.1 의심축 또는 의사환축 발생 사실을 지체없이 농림축산식품부(구제역방역과) 및 검역본부에 유선으로 우선 보고하고, 시도 가축방역기관에서 KAHIS에 입력한 상황을 확인 등록한 후, 타 시도에 통보한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.4 (PDF p.74)', '2026-05-06'::date, 'draft', 33, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.4.2 시군구 및 시도 가축방역기관에 의사환축 발생에 따른 긴급 방역조치사항을 시달하고 추진상황을 점검한다. 5.4.3 구제역 발생에 대비하여 방역지역 설정 등 아래의 방역 조치사항을 준비한다. - 방역대별 통제초소 및 축산차량 전담 거점소독시설 설치 준비 - 살처분·사체 처리, 이동통제, 소독, 예찰 등 초동방역을 위한 인력·장비·약품· 매몰지 등의 조달 준비 - 발생지역 소재 군부대, 시·도경찰청의 방역통제 인력 지원체계 확인 - 긴급백신접종을 위한 인력 동원체계 준비 - 전국의 모든 시군구의 주요 도로에 통제초소 설치 준비 - 시군구별로 축산차량 전담 거점소독시설 설치 준비 - 시군구 및 시도 가축방역기관에 긴급 방역조치사항 시달 및 점검 - 구제역방역대책본부(본부장 : 기관장) 및 상황실 설치 준비(전국) - 일시 이동중지(Standstill) 시행 대비, 상황 전파체계 준비 및 점검 ※ 간이항원진단키트 양성 시 즉시 시행 가능 - 발생 시군구 등에 긴급방역비 지원을 위한 예비비 확보 준비', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.4.2 (PDF p.74)', '2026-05-06'::date, 'draft', 34, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.5 검역본부장의 조치사항 5.5.1 의심축 및 의사환축 발생 사실을 통보받은 즉시 농림축산식품부에 보고한다. - 보고시 방역지역(관리, 보호, 예찰) 내 개괄적 농장현황을 포함한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.5 (PDF p.74)', '2026-05-06'::date, 'draft', 35, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.5.2 시도 가축방역기관장이 조사한 1차 역학조사 내용을 전달받아 추가 역학조사 및 역학분석을 실시하고 방역조치 대상을 선정하여 시도, 농식품부에 보고(통보)', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.5.2 (PDF p.74)', '2026-05-06'::date, 'draft', 36, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.5.3 채취 시료에 대한 정밀검사를 신속히 실시하고, 그 검사결과를 KAHIS에 등록 및 농림축산식품부장관에게 보고하며, 해당 시도지사 및 그 밖의 다른 시도지사에게 통보한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.5.3 (PDF p.74)', '2026-05-06'::date, 'draft', 37, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.5.4 구제역 방역대책상황실(실장 : 본부장) 설치를 준비한다. 5.5.5 기동방역기구 파견대비 관계관의 출동을 준비(초동대응팀 포함)한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.5.4 (PDF p.75)', '2026-05-06'::date, 'draft', 38, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.5.6 긴급 백신접종방안을 준비한다. 5.6. 농림축산식품부장관의 조치사항 5.6.1 의사환축 발생에 따른 ‘주의’단계 위기경보를 발령, 상황전파 및 긴급방역 조치사항을 송부한다. - 국가안보실(국가위기관리센터), 대통령비서실(농해수비서관실), 행정안전부(가축 질병재난대응과) 등 포함', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.5.6 (PDF p.75)', '2026-05-06'::date, 'draft', 39, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.6.2 Standstill 시행에 대비, 상황 전파체계를 준비하고 점검한다. 5.6.3 백신 미접종 유형의 구제역 발생에 대비, 각종 방역조치사항을 준비한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.6.2 (PDF p.75)', '2026-05-06'::date, 'draft', 40, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.6.4 구제역방역대책본부(본부장 : 장관) 설치 및 기동방역기구 파견을 준비한다. 5.6.5 국방부·경찰청 등에 의사환축 발생사실을 통보하고, 인력 지원체계를 점검한다.', '구제역 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.6.4 (PDF p.75)', '2026-05-06'::date, 'draft', 41, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2 구제역 임상관찰 및 예찰 요령 1. 방역지역별 예찰 요령 1.1 발생농장 및 관리지역 농장에 대한 임상관찰(전화 예찰 등)은 시도 가축방역 기관에서 실시한다.', '구제역 긴급행동지침(SOP)', '제4장 2. 구제역 임상관찰 및 예찰 요령 2 (PDF p.76)', '2026-05-06'::date, 'draft', 42, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.2 역학관련 농장, 보호지역 농장에 대한 임상관찰(전화예찰 등)은 시군구(읍· 면·동)에서 실시 한다.(방역본부 및 축협 등 동원) 1.3 방역지역 내 농장은 본인이 사육하는 가축에 대해 1일 1회 이상 임상관찰을 실시하여야 한다.', '구제역 긴급행동지침(SOP)', '제4장 2. 구제역 임상관찰 및 예찰 요령 1.2 (PDF p.76)', '2026-05-06'::date, 'draft', 43, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.4 전국 우제류 농장에 대한 정기 예찰은 방역본부의 전화예찰요원이 실시한다. 2. 예찰주기 2.1 방역지역별 농장에 대해 구제역 발생사실을 공표한 날로부터 48시간 내에 임상관찰(전화예찰 등)을 완료한다.', '구제역 긴급행동지침(SOP)', '제4장 2. 구제역 임상관찰 및 예찰 요령 1.4 (PDF p.76)', '2026-05-06'::date, 'draft', 44, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.2 1차 예찰을 완료한 이후 이동제한 해제 시까지 주 1∼2회 이상 임상관찰 (전화예찰 등)을 실시한다. 3. 예찰요령 3.1. 임상관찰 요령', '구제역 긴급행동지침(SOP)', '제4장 2. 구제역 임상관찰 및 예찰 요령 2.2 (PDF p.76)', '2026-05-06'::date, 'draft', 45, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.1.1 임상관찰을 위해 농장을 방문하기 전에 농장주에게 방문사실을 미리 알린다. 3.1.2 방역지역 내에서 임상예찰을 실시하는 경우 방역지역의 외곽부터 실시한다.', '구제역 긴급행동지침(SOP)', '제4장 2. 구제역 임상관찰 및 예찰 요령 3.1.1 (PDF p.76)', '2026-05-06'::date, 'draft', 46, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.1.3 방역지역별 예찰자를 별도로 구분하여 실시하고, 각 농장 간 이동시 방역복· 덧신 등을 갖추어, 농장 간 전파방지에 철저를 기한다. 3.1.4 발생지 내의 임상관찰을 제외한 예찰은 농장 간 전파 위험 등의 우려를 감안하여 유선 예찰 등으로 갈음할 수 있다.', '구제역 긴급행동지침(SOP)', '제4장 2. 구제역 임상관찰 및 예찰 요령 3.1.3 (PDF p.76)', '2026-05-06'::date, 'draft', 47, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.1.5 임상예찰은 구제역 예찰점검표에 따라 구제역 증상을 세밀하게 확인한다. 3.2. 전화예찰 요령 3.2.1 전화예찰 담당자별 농장을 지정하여 지속적으로 실시한다.', '구제역 긴급행동지침(SOP)', '제4장 2. 구제역 임상관찰 및 예찰 요령 3.1.5 (PDF p.76)', '2026-05-06'::date, 'draft', 48, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.2.2 구제역 예찰점검표의 내용에 따라 가축소유자에게 물어본다. 4. 의심축 발견 또는 농장 신고시 대응요령 4.1 임상예찰에서 의심축을 발견하거나 전화예찰 과정에서 의심축으로 판단되는 경우는 농장주에게 농장에 대한 이동제한을 조치하고, 시군구 및 시도 가축 방역기관에 신고(통보)하고, 시도 가축방역기관장은 가축방역관이 신속하게 파견될 수 있도록 조치한다.', '구제역 긴급행동지침(SOP)', '제4장 2. 구제역 임상관찰 및 예찰 요령 3.2.2 (PDF p.76~77)', '2026-05-06'::date, 'draft', 49, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4.2 시장·군수·구청장은 방역본부의 초동방역팀을 투입토록 하고 해당 농장의 사육가축 및 사람·차량 이동금지 등 방역조치를 실시하며, 농협경제지주 공동방제단을 투입하여 농장 주변 오염원 제거를 위한 집중 소독을 실시한다.', '구제역 긴급행동지침(SOP)', '제4장 2. 구제역 임상관찰 및 예찰 요령 4.2 (PDF p.77)', '2026-05-06'::date, 'draft', 50, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5. 농장주의 예찰요령 5.1 가축의 소유자 및 관리자는 사육가축에 대해 1일 1회 이상 임상관찰을 실시한다. 5.2 임상 관찰요령은 구제역 예찰 점검표를 참조하여 해당사항이 있는지를 확인한다.', '구제역 긴급행동지침(SOP)', '제4장 2. 구제역 임상관찰 및 예찰 요령 5 (PDF p.77)', '2026-05-06'::date, 'draft', 51, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.3 사육 가축에서 의심증상이 발견되는 경우에는 신속하게 시군구 및 가축방역 기관에 신고한다.[1588-4060(시군구, 시도) 또는 1588-9060(검역본부)]', '구제역 긴급행동지침(SOP)', '제4장 2. 구제역 임상관찰 및 예찰 요령 5.3 (PDF p.77)', '2026-05-06'::date, 'draft', 52, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.4 농장주(또는 관리자)는 농장 내 사육가축 및 사람·차량의 이동을 금지하고 가축방역관의 지시에 따른다. 6. 구제역 예찰 점검표 6.1 소 순 서 임 상 증 상 기운이 없어 보입니까? (의기소침, 침울, 활력저하) 사료 급여량이 줄었습니까? (식욕부진) 체온이 상승하였습니까? (정상체온 38.5℃) 우유생산량이 감소하였습니까? 거품섞인 침흘림이 있습니까? 혀와 잇몸 등에 물집(수포)이 있습니까? 발굽사이와 유두 등에 물집(수포)이 있습니까? 피부가 벗겨져 드러나고 궤양(상처)이 있습니까? 보행 시 절뚝거립니까? (파행) 유두, 발굽 등에 가피(딱지)가 형성되었습니까? 어린 송아지가 죽거나 임신우의 유산이 있습니까? 여 부 ○ ×', '구제역 긴급행동지침(SOP)', '제4장 2. 구제역 임상관찰 및 예찰 요령 5.4 (PDF p.77)', '2026-05-06'::date, 'draft', 53, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '6.2 돼지 순 서 임 상 증 상 기운이 없어 보입니까? (의기소침, 침울, 활력저하) 사료 급여량이 줄었습니까? (식욕부진) 체온이 상승하였습니까? (정상체온 38℃) 발굽의 고통으로 서거나 걷지 못하고 절룩거리거나 무릎으로 기어다닙니까? 발굽의 물집(수포)이 파열되어 피부가 벗겨지거나 발톱이 탈락되었습니까? 발굽에 흰색띠가 있습니까? 입 주변에 물집이 있거나 콧잔등에 큰 물집이나 터진 흔적이 있습니까? 발굽, 유방, 콧등에 가피(딱지)가 형성되었습니까? 어린 돼지가 증상 없이 갑자기 죽은 경우가 있습니까? 주저 앉아 일어나지 않습니까? 여 부 ○ ×', '구제역 긴급행동지침(SOP)', '제4장 2. 구제역 임상관찰 및 예찰 요령 6.2 (PDF p.78)', '2026-05-06'::date, 'draft', 54, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '6.3 염소, 사슴 등 순 서 임 상 증 상 기운이 없어 보입니까? (의기소침, 침울, 활력저하) 사료 급여량이 줄었습니까? (식욕부진) 체온이 상승하였습니까? (정상체온 38℃) 절뚝거림이 있습니까? 지간부, 제종 및 발굽갓띠를 따라 물집(수포)이 생기거나 파열되어 벗겨집니까? 어린 가축이 증상없이 갑자기 죽은 경우가 있습니까? 주저 앉아 일어나지 않습니까? 젖 생산이 갑자기 줄거나 유두 수포 또는 유방염이 생겼습니까? 입술 안쪽 잇몸이나 혀에 표백된 부위(괴사 및 미란 형성, 0.5-1.0cm 크기)가 있습니까? 여 부 ○ ×', '구제역 긴급행동지침(SOP)', '제4장 2. 구제역 임상관찰 및 예찰 요령 6.3 (PDF p.78)', '2026-05-06'::date, 'draft', 55, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4 의심축 발견 축산관련 종사자의 조치 사항 1. 기본원칙 수의사 등 축산관련 종사자가 구제역 의심축을 발견하는 경우에는 가축소유자로 하여금 해당농장의 가축, 사람, 차량, 물품, 분뇨 등의 이동을 못하도록 하고, 시군구 및 시도 가축방역기관 등에 신고한 후 농장 내에서 대기하여야 한다. * 축산관련 종사자 : 임상수의사, 수집상, 중개상, 인공수정사, 가축분뇨·집유차량 기사, 동물약품· 사료·축산기자재 판매자, 낙농헬퍼, 백신접종요원, 농장관리자, 가축운반기사, 사료운반기사, 임신진단사, 컨설팅, 방역요원, 검정원 등 우제류 축산농장 및 관련작업장 등에 종사하는 모든 사람을 말한다.', '구제역 긴급행동지침(SOP)', '제4장 4. 의심축 발견 축산관련 종사자의 조치사항 4 (PDF p.83)', '2026-05-06'::date, 'draft', 56, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2. 수의사 등 축산관련 종사자의 의심축 발견 시 신고 및 대응요령 2.1 수의사의 의심축 발견 시 조치사항 2.1.1 환축을 발견한 경우 가축소유자에게 환축이 구제역 의심축임을 설명하고, 즉시 관할지 읍·면장, 시장·군수·구청장 또는 시도 가축방역기관장에 전화 등으로 신고한다.', '구제역 긴급행동지침(SOP)', '제4장 4. 의심축 발견 축산관련 종사자의 조치사항 2 (PDF p.83)', '2026-05-06'::date, 'draft', 57, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.1.2 임상수의사는 시도 가축방역관이 농장에 도착할 때까지 농장을 떠나지 말고 가축소유자에게 다음의 긴급방역조치를 취하도록 지도한다. - 확산 방지를 위하여 의심축을 격리시키고 모든 사육동물(개, 고양이, 닭 등 포함)을 묶거나 축사 문을 닫아 이동하지 못하도록 한다. - 농장의 출입구를 1개소로 하고 소독조를 설치하여 방역관계자 이외에는 출입을 금지한다. 동력분무기나 휴대용분무기가 있으면 설치한다. 또한, 각 축사의 출입구에 신발 소독조를 설치하고 이미 설치되어 있는 경우 새로운 소독약으로 교체한다. - 가축소유자와 관리자, 가족에게 구제역 정밀검사 결과가 나올 때까지 외출하지 못하도록 한다. 다만, 긴급을 요하는 경우(질병 등)에는 소독을 실시한 후 출입을 허용한다. - 농장에 차량 등이 출입하지 않도록 한다. 불가피하게 출입이 필요한 경우에는 충분하게 소독을 실시한 후 출입시킨다. - 농장 사육시설, 옥외, 농장 밖으로 원유, 사료, 퇴비 등을 반출하지 못하도록 한다. - 배수구를 폐쇄한다.', '구제역 긴급행동지침(SOP)', '제4장 4. 의심축 발견 축산관련 종사자의 조치사항 2.1.2 (PDF p.83~84)', '2026-05-06'::date, 'draft', 58, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.1.3 가축방역관이 도착하면 모든 현장상황을 설명하여 인계한 후 가능한 한 시료채취 등에 협조한다. 2.1.4 농장을 떠날 때에는 가축방역관의 입회 하에 신체·의복·신발·안경 및 진료기구· 가방 등 휴대한 물품에 대한 소독을 실시하고 타고 온 차량에 대하여 세차· 소독을 실시한다. 착용한 의복을 벗고 깨끗한 다른 의복 또는 일회용 방역복 으로 갈아입은 다음 코를 풀고 입을 헹군 후 진료를 중단하고 귀가하도록 한다.', '구제역 긴급행동지침(SOP)', '제4장 4. 의심축 발견 축산관련 종사자의 조치사항 2.1.3 (PDF p.84)', '2026-05-06'::date, 'draft', 59, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.1.5 귀가 후 다시 차량, 진료기구, 기타 휴대물품, 의복·신발 등을 완전히 소독 하고 목욕을 한 후 새로운 의복으로 갈아입는다. 2.1.6 정밀검사 결과 구제역이 아니라는 연락이 있기 전까지 외출을 삼가고 감수성 가축을 사육하는 자 등과 만나지 않는다.', '구제역 긴급행동지침(SOP)', '제4장 4. 의심축 발견 축산관련 종사자의 조치사항 2.1.5 (PDF p.84)', '2026-05-06'::date, 'draft', 60, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.1.7 구제역으로 판정될 경우 최종 접촉일로부터 7일이 경과할 때까지 감수성 가축을 사육하는 농장 및 관련시설의 출입을 금지한다. 2.2 그 외 축산관련 종사자의 의심축 발견 시 조치사항', '구제역 긴급행동지침(SOP)', '제4장 4. 의심축 발견 축산관련 종사자의 조치사항 2.1.7 (PDF p.84)', '2026-05-06'::date, 'draft', 61, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.2.1 가축소유자에게 농장에서 구제역 의심축을 발견하였음을 설명하고, 즉시 관할지 읍·면장, 시장·군수·구청장 또는 시도 가축방역기관장에 전화 등으로 신고한다.', '구제역 긴급행동지침(SOP)', '제4장 4. 의심축 발견 축산관련 종사자의 조치사항 2.2.1 (PDF p.84)', '2026-05-06'::date, 'draft', 62, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.2.2 축산관련 종사자는 시도 가축방역관이 도착할 때까지 농장을 떠나지 말고 가축소유자에게 다음의 긴급방역조치를 취하도록 지도한다. - 확산 방지를 위하여 의심축을 격리시키고 모든 사육동물(개, 고양이, 닭 등 포함)을 묶거나 축사 문을 닫아 이동하지 못하도록 한다. - 농장의 출입구를 1개소로 하고 소독조를 설치하여 방역관계자 이외에는 출입을 금지한다. 동력분무기나 휴대용분무기가 있으면 설치한다. 또한, 각 축사의 출입구에 신발 소독조를 설치하고 이미 설치되어 있는 경우 새로운 소독약으로 교체한다. - 가축소유자와 관리자, 가족에게 구제역 정밀검사 결과가 나올 때까지 외출하지 못하도록 한다. - 농장에 차량 등이 출입하지 않도록 한다. 다만 사료 등 불가피하게 반입이 필요한 경우에는 농장입구에서 대기토록 한다. - 농장 사육시설, 옥외, 농장 밖으로 원유, 사료, 퇴비 등을 반출하지 못하도록 한다. - 배수구를 폐쇄한다. - 가축방역관이 도착하면 모든 현장상황을 설명하고 시료 채취 등에 협조한다.', '구제역 긴급행동지침(SOP)', '제4장 4. 의심축 발견 축산관련 종사자의 조치사항 2.2.2 (PDF p.84~85)', '2026-05-06'::date, 'draft', 63, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.3 현장에 도착한 시도 가축방역관의 축산관련 종사자에 대한 조치사항 2.3.1 구제역으로 확진시를 대비하여 축산관련 종사자가 의심축 신고농장을 방 문한 날을 기준으로 과거 14일전까지 방문한 우제류 농장 현황을 조사한다.', '구제역 긴급행동지침(SOP)', '제4장 4. 의심축 발견 축산관련 종사자의 조치사항 2.3 (PDF p.85)', '2026-05-06'::date, 'draft', 64, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.3.2 정밀검사 결과가 나올 때까지 축산관련 종사자가 농장 내에 대기토록 조치한다. - 부득이 농장을 벗어나야 할 경우에는 가축방역관이 직접 신체, 의복, 안경, 진료기구, 진료가방 등 휴대한 기구·장비에 대하여 폐기 또는 소독을 실시한다. - 타고 온 차량에 대하여 내외부에 대한 세차·소독을 실시한다. - 착용한 의복을 벗고 깨끗한 다른 의복 또는 일회용 방역복으로 갈아입고 코를 풀고 입을 행군 후 다른 곳을 방문하지 않고 즉시 귀가토록 한다.', '구제역 긴급행동지침(SOP)', '제4장 4. 의심축 발견 축산관련 종사자의 조치사항 2.3.2 (PDF p.85)', '2026-05-06'::date, 'draft', 65, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.3.3 귀가 후 다시 차량, 진료기구, 기타 휴대용구, 의복 등을 완전히 소독하고 손, 발을 씻고 목욕한 후 다른 의복으로 갈아입도록 조치한다.', '구제역 긴급행동지침(SOP)', '제4장 4. 의심축 발견 축산관련 종사자의 조치사항 2.3.3 (PDF p.85)', '2026-05-06'::date, 'draft', 66, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.3.4 정밀검사 판정 시 까지 외출을 삼가고 감수성 가축 사육농장 방문 및 관계자와 접촉을 하지 않도록 조치한다. 2.4.5 구제역으로 판정될 경우 7일간 가축 사육농장의 방문을 금지(진료 포함)하고 감수성 가축과 접촉하지 않도록 조치한다.', '구제역 긴급행동지침(SOP)', '제4장 4. 의심축 발견 축산관련 종사자의 조치사항 2.3.4 (PDF p.85)', '2026-05-06'::date, 'draft', 67, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '9 이동제한 요령 1. 기본원칙 1.1 구제역 발생 시 발생농장을 중심으로 방역지역이 설정되며, 구제역 확산 차단을 위해 방역지역 내에서는 우제류 및 생산물, 사료, 분뇨 등 이동이 제한된다.', '구제역 긴급행동지침(SOP)', '제4장 9. 이동제한 요령 9 (PDF p.102)', '2026-05-06'::date, 'draft', 68, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.2 이동제한은 대상 및 방역지역별로 구분되어 있으며, 발생농장과 가까운 방역 지역일수록 반입금지, 격리·폐쇄 조치 등 강화된 조치가 적용된다.', '구제역 긴급행동지침(SOP)', '제4장 9. 이동제한 요령 1.2 (PDF p.102)', '2026-05-06'::date, 'draft', 69, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2. 기관별 역할 2.1 시군구 2.1.1 시군구는 방역지역 내 우제류농장 및 축산시설, 축산차량 등을 대상으로 「가축전염병 예방법」 제19조 및 같은 법 시행규칙 제22조제1항에 따른 격리·억류 또는 이동제한 명령서를 발부하고, 관련 공고를 실시한다. ※ 신속한 전달을 위해 SMS 문자메세지로 이동제한 명령서 발부 내용 송부', '구제역 긴급행동지침(SOP)', '제4장 9. 이동제한 요령 2 (PDF p.102)', '2026-05-06'::date, 'draft', 70, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.1.2 시군구는 방역지역 내 우제류농장 및 축산시설, 축산차량 등이 이동제한 명령을 준수하고 있는지 점검하고, 위반 시 즉시 시정 및 관련 법령에 따라 고발 등 조치한다.', '구제역 긴급행동지침(SOP)', '제4장 9. 이동제한 요령 2.1.2 (PDF p.102)', '2026-05-06'::date, 'draft', 71, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.2 시도 2.2.1 시도는 방역지역 내 우제류농장 및 축산시설, 축산차량 등을 대상으로 이동제한 내용을 지도·홍보하고, 시군구로 하여금 이동제한 이행상황을 점검하도록 조치한다.', '구제역 긴급행동지침(SOP)', '제4장 9. 이동제한 요령 2.2 (PDF p.102)', '2026-05-06'::date, 'draft', 72, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.3 농림축산검역본부 2.3.1 검역본부는 중앙기동점검반 등을 활용하여 방역지역 내 이동제한 이행실태를 점검하고, 위반사례 확인 시 즉시 시정하도록 조치하고 관할 지자체에 통보하여 벌칙이 부과될 수 있도록 조치한다.', '구제역 긴급행동지침(SOP)', '제4장 9. 이동제한 요령 2.3 (PDF p.102)', '2026-05-06'::date, 'draft', 73, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.3.2 검역본부는 KAHIS를 활용하여 방역지역 내 축산차량 이동상황을 모니터링 하고, 위반 의심 사례 확인 시 관할 지자체에 해당 내역을 통보한다.', '구제역 긴급행동지침(SOP)', '제4장 9. 이동제한 요령 2.3.2 (PDF p.102)', '2026-05-06'::date, 'draft', 74, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3. 발생농장, 관리 및 보호지역 내 이동제한 기간 3.1 발생농장, 관리 및 보호지역 내 이동제한 농장은 발생농장의 마지막 매몰이 끝난 날부터 21일이 지나고 임상검사, 항원·NSP항체 검사, 환경검사에서 이상이 없을 때까지 이동제한을 실시한다.', '구제역 긴급행동지침(SOP)', '제4장 9. 이동제한 요령 3 (PDF p.103)', '2026-05-06'::date, 'draft', 75, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.2 다만, 관리 및 보호지역의 구제역 비발생 농장에서 불가피한 사유가 발생*하는 경우, 아래의 조건을 충족하는 농장에 대해 임상검사(전두수, 이동 전 7일간), 항원·항체·환경검사**에서 이상이 없으면 같은 시·도 내 다른 농장으로의 이동을 허용할 수 있다. * 이동제한 기간 중 신생축 번식으로 농장의 사육 능력을 초과한 경우 등 ** (가축항원) 소·염소는 이동하는 가축 전두수, 돼지는 이동하는 군별 24두, (NSP항체) 축사별 24두(돼지는 모돈, 육성돈, 비육돈 균분 검사), (환경항원) 이동 전 축사 환경검사 - 「가축전염병 예방법」 제17조에 따른 소독설비·방역시설 구비 - 가축을 이동시키려는 시군구에서 들여오려는 농장의 관할 시군구와 사전에 협의한 후 이동계획을 시도에 제출하여 사전 승인을 받고 해당 농장에는 이동승인서*를 발급 * 이동승인서식은 가축전염병 예방법 시행규칙 별지 제8호의3서식을 준용 - 이동 전 가축을 이동시키려는 농장에 대한 예방접종(2회 이상) 실시 - 가축을 이동할 전용차량을 사전에 지정하고, 가축 운반 당일에는 타 농장 방문 금지 - 이동한 가축은 다른 농장으로의 재이동을 금지하고, 1주일간 격리하면서 매일 임상검사 실시', '구제역 긴급행동지침(SOP)', '제4장 9. 이동제한 요령 3.2 (PDF p.103)', '2026-05-06'::date, 'draft', 76, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4. 이동제한 조치방법 4.1 발생농장 및 발생농장과 역학적으로 관련이 있어 구제역 전파가 의심되는 농장에 대하여는 이동제한을 실시한다. 4.2 시장·군수·구청장은 발생농장을 중심으로 하여 반경 3km 이내 지역인 보호 지역을 설정하고, 보호지역 내에서 사육되는 모든 우제류 가축에 대하여 이동제한을 실시한다. 다만, 해당지역의 축산업 형태, 지형적 여건, 생활권, 계절적 요인 또는 역학적 특성 등을 감안하여 보호지역의 범위를 확대하거나 축소할 수 있다.', '구제역 긴급행동지침(SOP)', '제4장 9. 이동제한 요령 4 (PDF p.103)', '2026-05-06'::date, 'draft', 77, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4.2.1 발생농장 입구의 눈에 잘 띄는 장소에 구제역 발생사실과 출입금지를 기재한 출입금지 표지판을 설치하고 현장 통제초소 설치 운영 4.2.2 발생농장 및 관리·보호지역에서 사육되는 우제류 가축의 격리·억류 또는 이동제한 명령. 다만, 보호지역에서 이동제한 대상 축종은 백신접종 상황 등을 감안하여 조정할 수 있음', '구제역 긴급행동지침(SOP)', '제4장 9. 이동제한 요령 4.2.1 (PDF p.104)', '2026-05-06'::date, 'draft', 78, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4.2.3 발생농장의 관리자, 동거가족 및 발생농장 가축의 소유자 등에게 고용된 자 등에 대하여 살처분이 완료된 날부터 7일이 경과될 때까지 외출을 통제하고, 부득이한 경우에 한하여 가축방역관의 통제하에 세척·소독 등 방역조치를 실시한 후 외출 허용', '구제역 긴급행동지침(SOP)', '제4장 9. 이동제한 요령 4.2.3 (PDF p.104)', '2026-05-06'::date, 'draft', 79, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4.2.4 관리·보호지역 주요 도로에 이동통제 초소 및 소독시설을 설치·운영하고, 사람·가축 또는 차량에 대하여 출입 통제, 소독 등 차단방역 실시', '구제역 긴급행동지침(SOP)', '제4장 9. 이동제한 요령 4.2.4 (PDF p.104)', '2026-05-06'::date, 'draft', 80, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4.2.5 의심축을 신고한 수의사, 인공수정사, 기타 축산관련 종사자에 대해 구제역 확진판정을 받은 날로부터 7일간 가축사육농장 방문을 금지(진료 포함)하고 감수성 가축과 접촉하지 않도록 조치', '구제역 긴급행동지침(SOP)', '제4장 9. 이동제한 요령 4.2.5 (PDF p.104)', '2026-05-06'::date, 'draft', 81, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4.3 발생농장을 제외한 관리·보호지역 내 이동제한 중인 우제류가축은 가축방역관의 승인하에 지정도축장으로 출하할 수 있다.', '구제역 긴급행동지침(SOP)', '제4장 9. 이동제한 요령 4.3 (PDF p.104)', '2026-05-06'::date, 'draft', 82, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '11 발생농장의 청소·세척 및 소독 요령 1. 기본원칙 - 발생농장 등의 청소·세척 및 소독은 농장주가 직접 실시하거나, 가축방역위생 관리업체를 활용하여 실시하고, 시군구는 이를 지도·점검하되, 불가피한 경우에는 시군구에서 소독을 지원한다.', '구제역 긴급행동지침(SOP)', '제4장 11. 발생농장의 청소·세척 및 소독 요령 11 (PDF p.111)', '2026-05-06'::date, 'draft', 83, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2. 부분 매몰농장의 청소·세척 및 소독 요령 2.1 부분 매몰농장은 이동제한 해제 시까지 주 2회 이상 주기적으로 소독한다. 2.2 축사 내부는 비어 있는 우방(돈방)을 먼저 청소·세척·소독 후 바로 옆 우방 (돈방)에 있는 가축을 세척·소독 후 이송하는 방법으로 모든 우방(돈방) 및 가축에 대해 순차적으로 청소·세척·소독한다.', '구제역 긴급행동지침(SOP)', '제4장 11. 발생농장의 청소·세척 및 소독 요령 2 (PDF p.111)', '2026-05-06'::date, 'draft', 84, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.3 구제역 비발생 축사부터 우선 청소·세척·소독 후 마지막에 발생축사를 실시한다. 2.4 축사 외부·기계 장비에 대해 청소·세척 및 소독을 실시한다.', '구제역 긴급행동지침(SOP)', '제4장 11. 발생농장의 청소·세척 및 소독 요령 2.3 (PDF p.111)', '2026-05-06'::date, 'draft', 85, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3. 전두수 매몰농장의 청소·세척 및 소독 요령 3.1 전두수 매몰농장은 이동제한 해제 시까지 주 1회 이상 주기적으로 소독한다. 3.2 농장의 청소·세척 요령은 다음과 같다. - 축사 내·외부에 대하여 일제히 청소를 우선 실시한다. - 모든 축사, 울타리, 부착기구 등은 구제역 유효소독약으로 철저히 세척 후 이들 부위에 부착된 유기물질, 먼지 등 이물질을 브러쉬, 수세미 등을 사용하여 제거한다. - 정화조, 하수구 및 배수구에 대해서도 세척 및 소독한다. - 사료통, 음수통, 착유장치 등은 모두 비우고 세척한다.', '구제역 긴급행동지침(SOP)', '제4장 11. 발생농장의 청소·세척 및 소독 요령 3 (PDF p.111)', '2026-05-06'::date, 'draft', 86, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.3 농장의 소독요령은 다음과 같다. - 축사 소독은 천장, 벽면, 바닥 등의 순서로 실시하고 모든 축사에 대해 동일한 방법을 적용한다. - 축사가 흙으로 되어 있는 경우 소독 후 뒤집은 다음 충분히 젖게 소독수를 뿌려준다. - 축사 주위의 습지, 초지 및 오염이 가능한 환경에 대해서도 축사 내부와 동일하게 소독한다. - 잡초가 많은 경우 제초제를 살포하여 제거한 후 소독한다. - 발생농장의 사료창고, 농기구 보관함, 농장내 사택 등에 대해서는 훈증소독을 실시한다.', '구제역 긴급행동지침(SOP)', '제4장 11. 발생농장의 청소·세척 및 소독 요령 3.3 (PDF p.111~112)', '2026-05-06'::date, 'draft', 87, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.4 사체 매몰 시 처리되지 않고 남은 오염물건(사료, 깔짚 등)은 소독수로 소독한 후 포대나 비닐봉지에 담아서 매몰 또는 소각 처리한다.', '구제역 긴급행동지침(SOP)', '제4장 11. 발생농장의 청소·세척 및 소독 요령 3.4 (PDF p.112)', '2026-05-06'::date, 'draft', 88, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '16 이동제한 기간 중 원유·사료·분뇨 관리 요령 1. 원유처리 1.1 다음에 해당되는 원유는 아래의 방법에 따라 자가농장에서 재활용하거나 폐기한다. * 재활용방법 : 원유 100kg당 구연산 750g 혼합 →응고물(원유의 30% 생산) →자가 TMR(완전 혼합사료)에 혼합하여 급여하면 농후사료 대체효과 - 구제역 의사환축으로 판정된 개체에서 생산되는 원유 - 검사결과 구제역 항원 양성인 농장 또는 의심축 신고농장의 간이항원진단키트 검사 결과 양성인 농장내 집유되어 있는 원유', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 16 (PDF p.135)', '2026-05-06'::date, 'draft', 89, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.2 살처분 완료 후 미감염 동거축 또는 역학농장에서 생산되는 원유는 집유업체에 통보하여 집유 업체의 방역강화조치 전제조건하에 집유업체로 이송할 수 있다. - 집유업체는 집유노선을 변경하여 발생농장을 마지막에 집유하도록하고 집유 된 원유에 대하여는 고온단시간살균법(72~75℃에서 15~20초)으로 2회 이상 연속하여 처리하거나 초고온순간처리법(132℃ 이상에서 1초 이상) 또는 이와 동등 이상의 효력을 가지는 열처리 방법으로 처리한 후 사용하여야 한다. - 발생농장 원유를 집유하는 차량은 차량 내·외부 소독을 실시하고, 운전자는 발생농장 방문전후에 휴대용 소독기를 이용하여 소독을 실시한다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 1.2 (PDF p.135)', '2026-05-06'::date, 'draft', 90, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.3 집유 및 원유처리도  목장주는 집유시마다 사람 및 시설 소독 실시 목장 출입  목장 입구부터 원유 취급실까지 진입 경로에 대한 소독 철저  집유차량 기사는 목장 진입 전‧후에 차량 전표면 소독 ⇩  발생농장 전용 집유차량을 고정배차하여 운영  차량 기사는 집유전 방역복과 방역용 덧신 착용, 전신소독 목장 집유  집유완료 후 방역복과 방역용 덧신은 소각‧폐기  가급적 축사밖에서 집유호스를 이용하여 집유 실시  집유호스는 집유 전‧후에 소독을 실시, 바닥 접촉 차단  집유차량의 배기구멍은 0.2㎛ 필터 또는 소독약이 적셔진 천으로 차단 ⇩  집유차량은 차량 전체 소독 실시 원유 인계  집유차량 기사는 전신 소독 실시  차량의 뚜껑은 절대 개폐하지 않고, 거점소독을 실시한 후 집유장 또는 유가공장으로 납유 ⇩  책임수의사를 배치하여 원유검사 및 소독 감독 원유 이송  이송차량의 배기구멍은 0.2㎛필터 또는 소독약이 적셔진 천으로 차단  이송완료 후 탱크 및 라인내부 CIP 처리(온수 65℃ 이상 및 세척액으로 세척 및 살균처리) ⇩ 원유 가공  고온단시간살균법(72~75℃에서 15~20초)으로 연속 2회 또는 초고온 순간처리법(132℃ 이상에서 1초 이상)으로 살균처리  제품생산 후 철저한 품질검사 실시', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 1.3 (PDF p.136)', '2026-05-06'::date, 'draft', 91, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2. 사료의 공급 2.1 사료업체는 발생지 관할 시장·군수에게 사료 지정차량을 신청하고, 시장·군수· 구청장은 발생농장에 공급하는 사료 공급차량에 대해 지정서를 발급한다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 2 (PDF p.136)', '2026-05-06'::date, 'draft', 92, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.2 사료공급차량 운전자는 지정서를 반드시 휴대하여야 하며, 발생농장 출입 전·후 차량 내외부 및 운전자에 대한 소독을 실시하여야 한다. 2.3 사료는 농장 밖 일정장소에 하차시킨 후 농장주가 농장으로 이송하고, 전달 장소는 사료공급을 전후하여 소독을 실시한다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 2.2 (PDF p.136~137)', '2026-05-06'::date, 'draft', 93, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.4 벌크사료는 농장 밖에서 전달하며, 출입 전·후 차량의 내외부 소독 등을 실시 한다(소독사항에 대해 농장주가 확인하고 소독실시기록부에 기록) 다만, 농장 구조 등의 특성상 농장내로 들어가야 하는 때에는 차량 운전자는 가급적 차량에서 하차하지 않도록 하고, 하차할 경우에는 덧신, 방역복, 장갑, 모자 등 일회용 방역장비를 사용해야 하며, 농장관계자와의 신체적인 접촉(악수 등)을 금해야 한다.(운전자가 사용한 일회용 방역용품은 농장주 확인 아래 해당농장에서 폐기)', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 2.4 (PDF p.137)', '2026-05-06'::date, 'draft', 94, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3. 가축분뇨처리 3.1. 가축분뇨처리의 기본원칙 3.1.1 농장주는 농장에서 보유한 가축분뇨처리시설 및 저장조 등을 최대한 활용하여 자체 처리한 후 보관하고, 외부의 반출은 최대한 억제한다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 3 (PDF p.137)', '2026-05-06'::date, 'draft', 95, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.1.2 농장주는 자체 처리·보관능력이 부족하여 부득이하게 외부로 반출할 경우 에는 소독처리하고 분변 검사 등을 실시하여 시장·군수의 확인을 받은 후 외부로 반출할 수 있다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 3.1.2 (PDF p.137)', '2026-05-06'::date, 'draft', 96, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.1.3 시장·군수·구청장은 가축분뇨처리시설 및 저장조 등이 부족한 경우 해당 연도의 가축분뇨처리지원 사업비에서 우선 지원할 수 있다. 3.2. 발생농장의 가축분뇨 처리', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 3.1.3 (PDF p.137)', '2026-05-06'::date, 'draft', 97, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.2.1 농장주는 발생농장의 전체 가축분뇨는 소독을 하고 살처분 가축이 사육된 축사 내부의 분뇨를 전량 수거 후 청소 및 소독을 실시하여야 한다. - 비육돈에서 발생한 경우에는 돈방 전체 표면 및 슬러리 피트 등의 분뇨를 전량 제거한 후 청소 및 소독을 실시하여야 한다. - 모돈에서 발생한 경우에는 스톨 또는 분만틀 전체 표면 및 슬러리 피트 등의 분뇨를 제거하고 청소 및 소독을 실시하여야 한다. - 한육우에서 발생한 경우에는 해당 우방 전체 표면의 분뇨를 제거하고 청소 및 소독을 실시하여야 한다. - 젖소 등 기타 축종에서 발생한 경우에는 축사 전체 표면의 분뇨를 제거하고 청소 및 소독을 실시하여야 한다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 3.2.1 (PDF p.137)', '2026-05-06'::date, 'draft', 98, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.2.2 시장·군수·구청장은 발생농장에서 생산되는 가축분뇨·고형분(糞)·액상뇨(尿)· 제품(액비, 퇴비 : 포장상태, 비포장 상태)은 소독을 실시한 후 이동제한 해제시까지 농장에서 보관하도록 조치하여야 한다. - 발생 농장주는 농장내 처리시설 및 보관능력을 최대한 활용하여 이동제한 해제 시까지 보관하여야 한다. - 발생 농장주는 농장내 보관능력 등이 부족한 경우에는 해당 시군구에 보관능력 확보에 필요한 저장조 설치사업비 등을 긴급 지원을 요청하거나 농장 외부로 반출을 허용해 줄 것을 요청할 수 있다. - 이 경우 시장·군수·구청장은 해당 농장의 처리 및 보관능력을 확인 후 외부로의 반출이 불가피하다고 판단되는 경우, 농장주로 하여금 ｢4.3. 가축분뇨 등 소독 및 중화처리 요령｣에 준하여 소독을 실시토록 조치한 후, 관내 지정된 공동자원화시설·공공처리장 등에 반출을 허용할 수 있다. - 이 경우 농장주는 관계관(공무원 등)의 지도·감독을 받아야 하고, 시장·군수· 구청장 및 농장주는 반출처를 1년 이상 기록·관리하여야 하며, 운반 차량 및 운전사 등에 대하여 철저한 소독을 실시하도록 조치하여야 한다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 3.2.2 (PDF p.138)', '2026-05-06'::date, 'draft', 99, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.3. 방역지역(관리·보호지역)의 가축분뇨 처리 3.3.1 시장·군수·구청장은 방역지역 내 우제류 사육농장에서 생산되는 가축분뇨· 고형분(糞)·액상뇨(尿)·제품(액비, 퇴비 : 포장상태, 비포장 상태)은 소독을 실시한 후 가급적 이동제한 해제시까지 농장에서 보관하도록 조치하여야 한다. - 방역지역 내 농장주는 농장내 처리시설 및 보관능력을 최대한 활용하여 이동 제한 해제시까지 보관하여야 한다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 3.3 (PDF p.138)', '2026-05-06'::date, 'draft', 100, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.3.2 농장주는 농장 내 보관능력 등이 부족한 경우에는 해당 시군구에 농장 외부로 반출을 허용해 줄 것을 요청할 수 있다. - 이 경우 시장·군수·구청장은 해당 농장의 처리 및 보관능력을 확인 후 외부로의 반출이 불가피하다고 판단되는 경우, 농장주로 하여금 ｢4.3. 가축분뇨 등 소독 및 중화처리 요령｣에 준하여 소독을 실시토록 조치한 후, 관내 지정된 공동 자원화시설·공공처리장 등에 반출을 허용할 수 있다. - 외부로 반출되는 분뇨가 관내 지정된 공동자원화시설·공공처리장의 처리능력을 초과하는 등 불가피한 경우 농장내 분뇨 부숙 완료(부숙도 판정기 측정), 정밀 검사 결과 바이러스 미검출, 분뇨 운반차량에 대한 세척·소독 등 방역조치 후 시군구에서 지정한 방역지역 내 농경지에 퇴·액비를 살포할 수 있다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 3.3.2 (PDF p.138~139)', '2026-05-06'::date, 'draft', 101, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.4. 가축분뇨 등 소독 및 중화처리 요령 3.4.1 분뇨소독 : 농장주는 분뇨에 알카리제를 사용하여 pH 10 이상 되도록 소독 처리하여 2~3일간 둔 후, pH 10 이상 여부를 측정하고 다시 산성제를 이용하여 pH 6~8로 중화시킨 후 가축분뇨 처리요령에 따라 처리하여야 한다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 3.4 (PDF p.139)', '2026-05-06'::date, 'draft', 102, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.4.2 액상뇨(尿) : 농장주는 액상뇨의 경우 알카리제를 사용하여 pH 10 이상 되도록 소독 처리하여 2~3일간 둔 후, 산성제를 이용하여 pH 6~8로 중화 시킨 후 가축분뇨 처리요령에 따라 처리하여야 한다. 소독약 사용량 계산 예 ① 가성소다(NaOH : 순도 98% 분말가루 시중 유통)를 사용하여 액상분뇨 1톤(1,000ℓ)에 5kg을 혼합하여 처리 후 3일 이상 격리상태로 둔다. ② 생석회(CaO : 순도 85% 분말가루 시중 유통)를 사용하여 액상분뇨 1톤(1,000ℓ)에 11.0kg을 혼합하여 처리 후 7일 이상 격리상태로 둔다. * 소독약 투입량은 고형분뇨의 특성에 따라 증감하여야 한다 ③ pH 확인은 시중에 판매되는 pH paper를 이용하여 pH 조견표에 따라 확인 ④ pH 측정시 소독처리 된 액상분뇨를 1ℓ 정도 용기에 담아 pH paper를 2~3초간 넣었다 꺼낸 후 색깔로 판단한다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 3.4.2 (PDF p.139)', '2026-05-06'::date, 'draft', 103, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.4.3 고형분(糞) 소독 - 농장주는 고형분뇨에 알카리제를 사용하여 pH 10 이상이 되도록 소독처리한 후 3일 이상 격리하여 두어야 한다. - 다만, pH를 조절하지 않고 소독이 가능한 유효한 소독약제를 사용할 경우에는 pH는 조절할 필요가 없다. 소독약 사용량 계산 예 - 고형분뇨에 생석회(순도 90% 이상 분말가루 시중 유통)을 사용하여 1톤당 20kg가 되도록 섞어서 pH 10 이상 되도록 한 후 3일 이상 격리상태로 둔다. - 고형분뇨와 생석회 혼합방법은 분뇨 15cm마다 생석회를 3kg/m2 이상 되도록 균일하게 뿌려준다. * 소독약 투입량은 고형분뇨의 특성에 따라 증감하여야 한다. - 이때 pH 10 확인은 소독된 고형분뇨 10g을 채취하여 1ℓ정도 용기에 담아 물 100㎖를 부어 교반한 후 pH paper를 2~3초간 넣었다 꺼낸 후 색깔로 판단한다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 3.4.3 (PDF p.139~140)', '2026-05-06'::date, 'draft', 104, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.4.4 액상뇨 및 고형분 - 농장주는 소독 후 3일 이상된 액상 및 고형분뇨에 산성제재를 이용하여 pH 6~8로 이상 되도록 중화하여야 한다. - 다만 pH를 조절하지 않고 소독이 가능한 유효한 소독약제를 사용할 경우에는 pH는 조절할 필요가 없다 소독약 사용량 계산 예 - 소독 후 3일 이상 격리된 액상 및 고형분뇨는 구연산(Citric acid : 순도 94% 액상 시중 유통)을 액상 및 고형분뇨 1톤(1000ℓ)에 350g으로 중화시킨다. * 소독약 투입량은 고형분뇨의 특성에 따라 증감하여야 한다. - 농장주는 중화된 액상뇨 및 고형분은 액비화, 퇴비화, 정화처리 할 수 있다. 단, 처리 시 ｢가축분뇨의 관리 및 이용에 관한 법률｣에 따른 처리기준을 준수하여야 한다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 3.4.4 (PDF p.140)', '2026-05-06'::date, 'draft', 105, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.5. 구제역 발생 이전에 생산된 퇴비·액비의 소독 및 처리 - 액비의 경우 액상뇨의 처리와 동일하게 처리하고, 퇴비의 경우 생석회 톤당 20kg를 스키드로더 등을 이용하여 교반하여 2~3일간 보관하여야 한다. - 퇴비, 액비의 pH 확인 방법은 액상뇨 및 고형분의 방법과 같다. - 소독 후 2~3일간 격리된 퇴비 및 액비는 외부 반출이 가능하다. - 구제역 발생 이전에 포장이 완료된 퇴비에 대해서는 포장별 외부의 소독을 실시한 후 반출이 가능하다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 3.5 (PDF p.140)', '2026-05-06'::date, 'draft', 106, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.6. 소독약품(가성소다, 구연산 등) 취급시 주의사항 - 고글, 마스크, 고무장갑을 착용한 후 소독 작업을 실시하고, 소독제가 피부에 접촉된 경우, 즉시 다량의 물로 세척하여야 한다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 3.6 (PDF p.141)', '2026-05-06'::date, 'draft', 107, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4. 그 밖에 축산관련 사람·차량에 대한 방역조치 4.1. 정액공급, 동물약품, 임신진단 등 축산관련 차량·사람에 대하여는 이동제한 해제 시까지 발생농장 출입을 금지한다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 4 (PDF p.141)', '2026-05-06'::date, 'draft', 108, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4.2. 부득이 출입이 필요한 경우 가축방역관의 지도·감독 하에 출입하고 출입 전·후 세척·소독을 실시하고, 출입한 기록을 유지한다.', '구제역 긴급행동지침(SOP)', '제4장 16. 이동제한 기간 중 원유·사료·분뇨 관리 요령 4.2 (PDF p.141)', '2026-05-06'::date, 'draft', 109, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '소독제의 종류 및 적용방법 1. 소독제의 종류 및 적용 1.1 소독제의 적용범위 - 소독제의 종류별 적용범위는 소독제제별 적용대상을 참고하며, 구제역 소독 약품의 허가현황은 검역본부 홈페이지 → 가축방역 → 구제역 → 소독약품에서 허가된 약품을 목적에 맞게 선정한다.', '구제역 긴급행동지침(SOP)', '별표 3 소독제의 종류 및 적용방법 (PDF p.294)', '2026-05-06'::date, 'draft', 110, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.2 소독제의 사용 1.2.1 비누 및 세정제 - 비누 및 세정제는 세척하는데 필수적으로 사용된다. 이것은 소독 효과보다는 소독효과를 반감시키는 유기물질, 먼지, 기름 등을 제거함으로써 소독효과를 높인다. 더운 물, 브러쉬, 수세미 등을 사용하면 세척작용을 향상시킬 수 있다.', '구제역 긴급행동지침(SOP)', '별표 3 소독제의 종류 및 적용방법 1.2 (PDF p.294)', '2026-05-06'::date, 'draft', 111, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.2.2 염기제제(alkalines) - 가성소다(sodium hydroxide)나 탄산소다(sodium carbonate)가 일반적으로 사용된다. 비용이 저렴하여 대단위 소독에 적절하다. 세척과정에 나오는 지방 이나 유기물질에 대한 비누화작용을 가지고 있어 유기물질이 많은 축사, 가옥, 뜰, 하수구, 쓰레기 등의 소독을 실시하는 데 매우 유용하다. 가성소다의 경우 2%, 탄산소다의 경우 4%가 되게 한다. 가성소다는 부식성이 매우 강하고 페인트를 벗기기도 하므로 차량 소독용으로 사용시 주의를 요한다. - 생석회는 동물용의약품은 아니지만 사체 및 토양 소독제로 주로 이용되며 토양에서는 pH 11~12의 강한 알칼리성으로 구제역 바이러스를 사멸한다.', '구제역 긴급행동지침(SOP)', '별표 3 소독제의 종류 및 적용방법 1.2.2 (PDF p.294)', '2026-05-06'::date, 'draft', 112, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.2.3 산성제제(acids) - 염산용액은 2%로 하여 사용한다. 소독효과는 10분이면 가능하다. 콘크리트나 금속성 기구류에 대해 부식성이 있으며 다른 소독제를 적용하기 힘든 경우에만 사용하는게 좋다. 딱딱한 기구류 등에 폭넓게 적용이 되며 다른 강산에 비하여 독성이 적다. - 2% 초산(acetic acid) 용액은 사람 및 피복에 안전하게 적용 가능하다. 사용은 물 1리터당 빙초산(순도99%이상) 20㎖를 섞어서 사용한다. 금속에 대해서는 다소의 부식성이 있으며 고무제품에는 약하지만 점착성이 있다. - 2% 구연산(citric acid)용액은 사람 및 피복에 안전하게 적용할 수 있는 장점이 있다. 소독효과가 나타나는데는 30분 정도가 소요된다. - 이들 산성제제는 침투력이 약하므로 세정제와 같이 사용할 경우 바이러스 사멸효과를 증진시킬 수 있다.', '구제역 긴급행동지침(SOP)', '별표 3 소독제의 종류 및 적용방법 1.2.3 (PDF p.294~295)', '2026-05-06'::date, 'draft', 113, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.2.4 알데하이드제제(aldehydes) - 글루타알데하이드(glutaraldehyde)는 일반적으로 1~2%의 농도로 사용된다. 이것은 유기물질에 일부 오염되어 있어도 소독에 효과적이다. 금속성 물질에 대해서는 부식효과가 있고 생체에 독성이 있으며 대단위로 적용하기에는 비용이 많이 소요된다. - 포르말린(formalin)용액은 포르말린 8%로 희석하여 사용한다. - 포름알데하이드 훈증소독은 축사내부나 사료창고, 축산기구 보관창고, 농장사택 등 공간소독에 탁월한 소독효과를 나타낸다. 소독공간은 건조하고, 밀폐되어야 한다. - 포름알데하이드 가스는 15~24시간동안 소독을 요하며 독성이 강하고 소독후에는 완전히 환기시켜야 한다.', '구제역 긴급행동지침(SOP)', '별표 3 소독제의 종류 및 적용방법 1.2.4 (PDF p.295)', '2026-05-06'::date, 'draft', 114, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.2.5 산화제 - 산화작용에 의하여 바이러스 단백질을 파괴하는 것으로서 주로 염소계 또는 산소계 성분으로 구성된다. - 차아염소산은 중성 pH 이하에서 0.175%이상의 농도로 사용하며 20℃ 이상의 온도에서는 불안정하므로 소독약을 주2~3회 갈아주어야 한다. 유기물이 있으면 소독효과가 낮다 - 이산화염소제는 차아염소산보다 강력하지만 더 불안정하며 0.02% 농도로 사용한다. 품질관리 및 보관에 주의를 요한다. - 이염화이소시안산나트륨(Sodium dichloroisocyanurate)은 차아염소산에 비해 유기물이 있어도 비교적 효과가 있다. - 복합염 및 산류의 복합소독제도 구제역 소독에 광범위하게 사용되고 있다. /', '구제역 긴급행동지침(SOP)', '별표 3 소독제의 종류 및 적용방법 1.2.5 (PDF p.295)', '2026-05-06'::date, 'draft', 115, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.2.6 생석회 - 생석회는 사체 및 토양 소독제로 주로 이용되며 토양에서는 pH 11~12의 강한 알칼리성으로 구제역 바이러스가 살아남지 못하게 된다. 토양 소독시 살포량은 평당 1kg 정도 뿌려준다 - 생석회의 소독효과는 물과 반응시 200℃의 열이 발생하여 병원균을 사멸시켜 전염병 예방을 할 수 있으므로 건조한 도로나 축사바닥에 생석회 살포한 후 물을 뿌려주는 것이 효과적이다. 즉 생석회가 물과 반응하여 소석회로 될 때 열을 이용한 물리적 소독과 소석회가 물에 녹았을때 강알칼리성을 이용한 화학적 소독의 2중 효과가 있다. [생석회 취급시 주의사항] - 반드시 사용설명서를 숙지후 사용할 것 - 습기나 물과 접촉시 높은 열이 발생되므로 화상에 주의할 것 - 가축의 몸에 생석회가 직접 접촉하면 피부(유두 등)에 수포가 생기거나 발에 상처나 지간 피부염 등의 염증이 있을 경우에는 통증을 일으키므로 주의할 것 - 사용할 때 보안경 및 안전보호구를 필히 착용 후 취급할 것 - 보관 시 습기나 물이 있는 곳을 피하고 예리한 물건과 혼합 저장을 피할 것 - 보관중 던지거나 포장을 손상시키지 말고 개봉한 제품은 사용후 밀폐(비닐로 덮어 밀봉) 하고, 어린이 손에 닿지 않도록 보관할 것', '구제역 긴급행동지침(SOP)', '별표 3 소독제의 종류 및 적용방법 1.2.6 (PDF p.296)', '2026-05-06'::date, 'draft', 116, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2. 소독제 선택 및 사용시 주의사항 2.1 가능한 소독제는 소독 목적물에 유효한 소독제를 선택하여야 하고 소독 효과를 높이기 위해서는 반드시 같은 종류의 소독제제를 선정하여 사용하여야 한다.', '구제역 긴급행동지침(SOP)', '별표 3 소독제의 종류 및 적용방법 2 (PDF p.296)', '2026-05-06'::date, 'draft', 117, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.2 소독약품 사용시 아래의 안전수칙을 준수토록 한다. - 사용설명서를 충분히 읽어본 후 사용할 것 - 다른 소독제와 혼합하거나 병행하여 사용하지 말 것 - 희석배수를 반드시 지킬 것 - 사용시 마스크 등 보호장구를 착용할 것 - 소독약에 사람이 과다 노출시 즉시 물로 씻어 낼 것 - 차량 소독시 창문을 완전히 닫은 후 실시할 것 - 농산물 등을 적재한 차량은 비닐 등 사전 조치 후 소독할 것 - 오토바이 운전자에게는 우의를 사용할 것 - 소독약 살포에 따른 환경오염이 되지 않도록 조치할 것 [참고] 소독제제별 적용대상 소 독 제 제 주 요 적 용 대 상 가성소다, 탄산소다 사체, 축사 및 주위환경, 물탱크, 기구, 차량, 피복 ※ 사람·가축·알루미늄 계통에는 적용금지 염기(알칼리) 제제 생석회 사체, 동물이 없는 축사, 바닥 및 흙 사람·차량이 많은 도로에는 적합하지 않음 염산용액(Hydrochloric acid) 축사, 기구, 퇴비 초산용액(Acetic acid) 축사, 동물, 사람, 기구, 의복 구연산용액(Citric acid) 축사, 동물, 사람, 기구, 의복, 복합산용액 축사, 동물, 기구 등(소독제별로 다름) 글루타알데히드 축사, 기구(생체에는 사용금지) 포르말린 사료, 거름 등(생체에는 사용금지) 포름알데하이드 훈증 (formaldehyde gas) 건초·볏짚, 사료, 밀폐공간(축사, 창고, 사택 등), 전기기구 차아염소산 축사, 기구, 가옥, 의복, 음수 등 이산화염소 축사, 기구, 가옥, 의복, 음수 등 이염화 이소시안산나트륨 축사, 기구, 가옥, 의복, 음수 등 기타(복합염류) 축사, 기구, 가옥, 의복, 음수 등(소독제별로 다름) 산성제제 알데하이드계 기 타 ※ 주요적용대상은 소독제 성분 조성별로 다를 수 있으므로 제품별 설명서에 따라 선택해야 함. /', '구제역 긴급행동지침(SOP)', '별표 3 소독제의 종류 및 적용방법 2.2 (PDF p.296~297)', '2026-05-06'::date, 'draft', 118, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '축산농장 준수사항 1. 평시 축산농장 준수사항 1.1 축산농장은 구제역 차단방역을 위해 아래사항에 대하여 철저히 준수한다. 1.1.1 구제역 발생국가에 대한 여행을 자제하고, 해외여행 시 농림축산검역본부에 입·출국 신고 및 입국 시 공항만 소독·최소 5일 이상 농장 출입금지', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 (PDF p.298)', '2026-05-06'::date, 'draft', 119, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.1.2 정기 백신접종 및 가축 거래 시 접종확인서 휴대를 확인한다. 1.1.3 축사 내·외부, 장비 등에 대해 주 1회 이상 소독을 실시하고 소독실시 기록부를 기록 보관하여야 한다.', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 1.1.2 (PDF p.298)', '2026-05-06'::date, 'draft', 120, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.1.4 농장내 출입하는 모든 사람에 대하여 1회용 방역복, 장갑, 장화 착용 등 개인 방역을 철저히 하고 차량·장비 등에 대하여 철저히 소독을 실시한다. - 소독은 농장 출입 전·후 각 1회 이상 소독 실시하고, 사용한 1회용 방역복은 현장에서 소각하거나 폐기한다.', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 1.1.4 (PDF p.298)', '2026-05-06'::date, 'draft', 121, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.1.5 구제역 임상관찰 철저히 하고 의심축 발견 즉시 방역당국(1588-4060, 1588-9060)에 신고한다. 1.1.6 불필요한 축산모임은 자제하고, 모임이후 철저한 소독 등을 실시하고 농장에 출입한다.', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 1.1.5 (PDF p.298)', '2026-05-06'::date, 'draft', 122, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.1.8 가축전염병 예방법령 규정에 따른 소독시설 구비 등 준수사항을 이행한다. 1.1.9 구제역 예방수칙 교육을 정기적으로 이수한다. 1.1.10 국가 및 지방자치단체의 구제역 방역대책 추진에 적극 협조한다.', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 1.1.8 (PDF p.298)', '2026-05-06'::date, 'draft', 123, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.2 외국인 근로자 고용농장 준수사항 1.2.1 축산농장은 외국인 근로자를 채용할 경우 아래사항을 준수한다. - 외국인 근로자 채용전 신분확인을 철저히 한다. · 성명, 여권번호, 가족사항, 출신국가에서의 직업 등 확인 · 국내 타농장에서 근무한 경력 등을 확인하여 채용시 방역상 위해가 없는지 확인 - 외국인 근로자를 채용하는 경우 시장·군수에게 신고하여야한다. - 외국인근로자를 채용하는 경우에는 방역조치를 철저히 한다. · 마을회관 등 가축이 없는 곳에서 채용절차를 밟고, 국내 타농장에서 근무한 경력 등이 확인되는 경우 축산물 등 음식물 소각·폐기, 개인용구에 대한 세척·소독 실시 - 농장근무 시 방역에 철저를 기한다. · 농장 내·외부 청소 및 소독, 질병의심축 발견 시 신속한 신고 등 방역준수사항 주기적인 교육실시 · 농장 출입시 목욕 및 깨끗한 의복과 신발 착용 · 농장주변 정리 등 업무수행 후에는 소독 후 축사 출입 - 외국인 근로자 사후관리에 철저를 기한다. · 타농장 방문을 자제토록하고 외국인 근로자의 농장방문을 금지한다. · 휴일 등 외출 시에는 귀가 후 주요 행적을 기록하고 농장밖에서 소독 후 출입시킨다. · 외국인 근로자의 가족·친지 등은 농장 밖에서 만나도록 한다.', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 1.2 (PDF p.298~299)', '2026-05-06'::date, 'draft', 124, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '1.2.2 축산농장에 근무하는 외국인 근로자는 아래사항을 준수한다. - 자국에서 축산물을 반입하지 않는다 - 농장입구에서 차량 및 사람 소독을 철저히 하고, 축사 출입전에는 반드시 작업복과 장화를 갈아 신고 출입한다. - 사료를 적게 먹거나 평소와 달리 이상한 행동을 하는 가축을 발견하는 경우 신속하게 농장주에게 알린다. - 타농장 방문을 금지하며, 가족, 친구 등을 만날때에는 농장 밖에서 만난다. - 외출시에는 외출전용 의복과 신발을 착용하고, 귀가 즉시 손과 신발을 소독 하고, 깨끗이 목욕한다.', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 1.2.2 (PDF p.299)', '2026-05-06'::date, 'draft', 125, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2. 발생 시 준수사항 - 사료차량, 가축운반차량 등 축산관련 차량의 출입 시에는 운전자로부터 소독 필증을 확인하고 회수하여 보관한다. 2.1 구제역 발생지역 준수사항', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 2 (PDF p.299)', '2026-05-06'::date, 'draft', 126, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.1.1 일시 이동중지(Standstill) 명령이 발령되면 농장내에 가축, 사람, 차량, 물품 등의 출입을 금지시킨다(48시간 이내 - 필요시 연장)', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 2.1.1 (PDF p.299)', '2026-05-06'::date, 'draft', 127, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.1.2 방역기관의 허가없이 가축의 농장입식이나 농장밖 반출행위 금지 - 단, 지정도축장으로 출하하려는 경우 사전에 관할 시장·군수로부터 도축장 출하승인서를 받아야 함 /', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 2.1.2 (PDF p.299)', '2026-05-06'::date, 'draft', 128, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.1.3 사육중인 가축에서 구제역 의심증상을 보일 경우 가축방역기관이나 현장 주재 가축방역관에게 즉시 신고 2.1.4 농장 출입구를 1개소로 제한하고 차량·장비·사람의 이동을 엄격히 통제 - 출입구에 신발 등을 소독할 수 있는 소독조 설치 운영 - 농장 출입 차량 및 장비에 대한 철저한 세척 및 소독제 살포 - 일가친척, 인접주민의 농장방문 최대한 금지 - 사람이 많이 모이는 시장, 행사장 출입 금지 - 집유차량, 사료차량 등의 출입시 가능한 탑승자의 하차를 제지하고, 불가피한 경우 농장에서 별도의 장화 제공 및 농장 출발시 차량 및 사람에 대한 세척·소독 실시 - 축산인 모임을 금지하고, 특히 통제초소 운영 등 방역활동을 위해 함께 모이는 것을 금지한다.', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 2.1.3 (PDF p.300)', '2026-05-06'::date, 'draft', 129, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.1.5 발생지역내 가축과 접촉한 사람은 당해 지역 출발 이전에 손과 신발 세척 및 외부 옷에 소독제 살포 후 타지역을 방문하지 아니하고 귀가하여 목욕과 세탁을 실시 하고 타농장 방문을 자제한다', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 2.1.5 (PDF p.300)', '2026-05-06'::date, 'draft', 130, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.1.6 방역기관의 허가없이 가축의 분뇨를 야외에 살포하거나 농장 밖으로 반출 하는 행위 금지(다만, 축산분뇨 공통처리시설로 운반하는 경우는 이동허용)', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 2.1.6 (PDF p.300)', '2026-05-06'::date, 'draft', 131, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.1.7 구제역 발생농장과 역학적으로 관련되는 경우 가축의 이동을 금지하고, 지체없이 방역기관에 신고한다. 2.1.8 구제역 의심증상을 발견한 경우 읍·면·동/시군구/시도 및 가축방역기관/ 검역본부에 신고한다.', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 2.1.7 (PDF p.300)', '2026-05-06'::date, 'draft', 132, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.2 구제역 비발생지역 준수사항 2.2.1 일시 이동중지(Standstill) 명령이 발령되면 농장내에 가축, 사람, 차량, 물품 등의 출입을 금지시킨다(48시간 이내)', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 2.2 (PDF p.300)', '2026-05-06'::date, 'draft', 133, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.2.2 구제역 발생지역 방문을 금지하고 발생시기에는 축산인 모임을 금지하고, 특히 방역활동을 위해 함께 모이는 것을 자제한다. 2.2.3 농장에 출입하는 모든 출입자 및 차량과 물품(기구, 장비 포함)을 철저히 소독을 실시한다', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 2.2.2 (PDF p.300)', '2026-05-06'::date, 'draft', 134, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.2.4 가축에서 수포발생 등 구제역 의심증상을 보일 경우 즉시 가축방역기관/ 검역본부에 신고 2.2.5 발생지역·관리지역·보호지역의 농장을 방문하고 돌아온 사람은 2주 이상 농장방문을 금지하고 축산농장은 이러한 사람의 농장출입을 금지', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 2.2.4 (PDF p.300~301)', '2026-05-06'::date, 'draft', 135, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.2.6 쥐 등 야생동물과 파리 등 매개곤충을 구제하고 개나 고양이, 닭, 오리 등 매개 가능한 동물은 묶거나 가두어 기르고 축사 내·외부를 정기적으로 소독', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 2.2.6 (PDF p.301)', '2026-05-06'::date, 'draft', 136, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.2.7 가축의 투매나 홍수출하 자제 2.2.8 방역지역(관리·보호·예찰)에서 불법 반출한 소, 돼지, 양, 사슴 등 우제류 가축의 구입 금지 및 이러한 가축을 판매·운반해주는 업자는 가까운 경찰서나 가축 방역기관에 신고 - 이동제한 위반농장과 이동제한 지역 가축을 불법 유통시켜준 운반업자, 이를 도축해 준 도축장영업자는 1년 이하의 징역, 1,000만원이하의 벌금과 영업 정지 등의 처벌을 받음', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 2.2.7 (PDF p.301)', '2026-05-06'::date, 'draft', 137, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.2.9 구제역 발생농장과 역학적으로 관련되는 경우 가축의 이동을 금지하고, 지체없이 방역기관에 신고한다. 2.3 축산농가 방역수칙 2.3.1 농장에 출입하는 차량·사람은 출입 전·후에 철저한 세척·소독 실시, 사람은 농장 출입 전후 소독(특히 손, 발) 및 환복 - 농장에 출입하는 모든 사람·가축·차량(가축분뇨·동물약품·사료 등 축산관련 차량)에 대해 출입 전·후 소독 실시 - 축사를 출입할 때는 반드시 외부 신발을 벗고 축사 전용신발을 갈아 신은 후 소독 실시, 외부 신발과 내부 신발의 교차오염 방지 - 축사 입구에는 신발소독조를 설치하여야 하며 소독액은 2~3일에 한번 씩 교체하며 유기물 오염 시 즉시 교체 - 축산농가는 축사 내·외부, 장비, 농장출입구 등에 대해 주 1회 이상 소독 및 소독실시기록부 기록 보관', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 2.2.9 (PDF p.301)', '2026-05-06'::date, 'draft', 138, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.3.2 구제역 발생지역은 방역기관의 허가 없이 가축입식이나 농장 밖 반출행위 금지 2.3.3 구제역 백신을 올바른 접종방법으로 철처히 실시 2.3.4 일시 이동중지(Standstill) 명령이 발령되면 농장내에 가축, 사람, 차량, 물품 등의 출입을 금지하고 차량 및 농장소독 실시 /', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 2.3.2 (PDF p.301)', '2026-05-06'::date, 'draft', 139, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3. 위기단계별 축산농장 준수사항 위기단계 준수사항 ◦ 발생국가 여행 자제 ◦ 축산농장의 해외여행시 농림축산검역본부에 입출국 신고 및 입국시 공항만 소독·최소 5일 이상 농장 출입금지 ◦ 축산농장은 축사 내·외부, 장비 등에 대해 주 1회이상 소독 실시 평시 (주변국 발생시) - 농장에 사람·가축·차량 출입 전·후, 반드시 소독을 실시 - 수의사, 인공수정사 등 관련 종사자 출입시 1회용 방역복·장화·장갑 착용 및 소독 후 출입하도록 조치 ◦ 정기 백신접종 및 가축 거래 시 접종확인서 휴대 확인 ◦ 임상관찰 철저 및 의심축 발견 시 시군구 등에 신속히 신고 ◦ 가축전염병 예방법령 규정에 따른 소독시설 구비 등 준수사항 이행 ◦ 구제역 예방수칙 교육 정기적 이수 ◦ 국가 및 지방자치단체의 구제역 방역대책 추진에 적극 협조 ◦ 정부, 지자체, 관련단체의 긴급방역 조치에 적극 협조 주의 (의사환축 발생 및 백신접종 유형의 구제역 발생시) ◦ 농장주는 소독·예찰강화, 외부인·차량 통제 등 농장 차단방역 철저 - 축산관련 종사자(차량) 출입시 1회용 방역복 착용 및 소독 철저 ◦ 발생지역은 축산농장 모임 및 집회 금지, 축산농장 및 축산관련종사자의 발 생지역 출입자제 ◦ 정기 백신접종 및 가축 거래시 접종확인서 휴대 확인 ◦ 임상관찰 철저 및 의심축 발견 시 시군구 등에 신속히 신고 ◦ 가축전염병 예방법령 규정에 따른 소독시설 구비 등 준수사항 이행 ◦ 정부, 지자체, 관련단체의 긴급방역 조치에 적극 협조 ◦ 농장주는 소독·예찰강화, 외부인·차량 통제 등 농장 차단방역 철저 - 축산관련 종사자(차량) 출입시 1회용 방역복 착용 및 소독 철저 경계 (백신접종 유형의 구제역이 타 시도로 전파시) ◦ 발생 시도 축산농장 모임 금지 및 전국 축산농장 모임 자제 ◦ 정기 백신접종 및 가축 거래시 접종확인서 휴대 확인 ◦ 임상관찰 철저 및 의심축 발견 시 시군구 등에 신속히 신고 ◦ 가축전염병 예방법령 규정에 따른 소독시설 구비 등 준수사항 이행 ◦ 축산관련 종사자 등에 대한 방역조치 강화 - 발생 시군구 및 인접 시군구는 해당 시군구 출입전용 사료운반차량을 지정 하여 운영하고 소독 등 방역지도 강화 - 축산관련 종사자(차량)의 농장출입 전후, 각각 1회 소독 여부를 점검 - 발생 시도는 축산관련 종사자의 농장 방문을 억제(1일 1농장 허용) - 비발생 시도는 발생 시도에 소재한 농장을 방문하지 않도록 억제 위기단계 준수사항 ◦ 정부, 지자체, 관련단체의 긴급방역 조치에 적극 협조 심각 (백신접종 유형의 구제역이 여러 시도에서 발생, 전국환산 우려시) / ◦ 농장주는 소독·예찰 강화, 외부인·차량 통제 등 농장 차단 방역 철저 - 축산관련 종사자(차량) 출입시 1회용 방역복 착용 및 소독 철저 ◦ 전국 축산농장 모임 금지 (축산관련단체장 선거 연기 등) ◦ 정기 백신접종 및 가축 거래시 접종확인서 휴대 확인 ◦ 임상관찰 철저 및 의심축 발견 시 시군구 등에 신속히 신고 ◦ 가축전염병 예방법령 규정에 따른 소독시설 구비 등 준수사항 이행', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 3 (PDF p.302~303)', '2026-05-06'::date, 'draft', 140, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '◦ 축산관련 종사자는 부득이한 경우를 제외하고 농장 방문 금지(발생시도), 발생 시도 농장방문금지(비발생 시도) - 타 시도에 소재한 농장 및 축산관련작업장 등 방문 자제 ◦ 정부, 지자체, 관련단체의 긴급방역 조치에 적극 협조 심각 (백신 미접종유형 구제역이 발생시) ◦ 전국 일시 이동중지 시행 기간동안 우제류 농장 및 관련 작업장에 가축·사람· 차량·물품 등의 이동금지 조치 준수 ◦ 농장주는 소독·예찰강화, 외부인·차량 통제 등 농장 차단방역 철저 - 축산관련 종사자(차량) 출입시 1회용 방역복 착용 및 소독 철저 ◦ 전국 축산농장 모임 금지 (축산관련단체장 선거 연기 등) ◦ 긴급 백신접종 및 가축 거래시 접종확인서 휴대 확인 ◦ 축산관련 종사자는 부득이한 경우를 제외하고 농장 방문 금지(발생시도), 발생 시도 농장방문금지(비발생 시도) - 타 시도에 소재한 농장 및 축산관련작업장 등 방문 자제', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 (PDF p.303)', '2026-05-06'::date, 'draft', 141, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4. 황사 발생시 축산농장 관리수칙 4.1 운동장이나 방목장에 있는 가축은 축사안으로 대피시킨다. 4.2 축사의 창과 출입문 등을 닫고 외부 공기와 접촉을 가능한 적게 한다.', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 4 (PDF p.303)', '2026-05-06'::date, 'draft', 142, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4.3 노지에 방치하였거나 쌓아둔 건초, 볏짚 등은 비닐이나 천막 등으로 덮는다. 4.4 황사가 끝나는 즉시 축사 주변, 건물 내외부를 씻어낸 후 소독을 하고 방목장의 조사료는 잔여사료 폐기하고 가축이 접촉되는 기구류 세척 또는 소독을 실시한다.', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 4.3 (PDF p.303)', '2026-05-06'::date, 'draft', 143, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '4.5 가축이 황사에 노출되었을 때는 몸체를 물로 씻어주고 축체에 소독을 실시한다. 4.6 황사가 지나간 다음에는 구제역 임상증상 등에 대하여 개체별로 주의 깊게 관찰한다.', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 4.5 (PDF p.303)', '2026-05-06'::date, 'draft', 144, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5. 우천 시 축산농장 방역 요령 5.1 우천 시에는 소독제가 희석되므로 비에 젖지 않도록 농장입구 및 축사입구에 신발소독조를 설치한다. 5.1.1 수시로 신발소독조를 점검하여 필요시 소독약제를 추가로 투여한다.', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 5 (PDF p.304)', '2026-05-06'::date, 'draft', 145, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.1.2 소독약은 소독효과를 위해 소독약 설명서 내 희석배수 중 고농도로 희석한다. 5.2 세부 소독요령 5.2.1 비가 오기 전 - 소독약품은 빗물에 젖지 않도록 마개나 덮개 등을 닫아 보관한다. - 생석회는 물기에 닿으면 화학작용에 의해 고온이 발생되어 화재의 우려가 있으므로 물기에 닿지 않도록 보관하고, 주위에 인화성 물질을 두지 않는다.', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 5.1.2 (PDF p.304)', '2026-05-06'::date, 'draft', 146, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.2.2 비가 올 때 - 비가 많이 올 경우에는 소독효과가 없어지므로 축사외부 소독작업을 중단하고, 축사 내부를 중점적으로 소독한다. 5.2.3 비가 그친 후 - 신발소독조는 세척을 실시한 후 새로 소독약을 채운다. - 축사 내외·분뇨처리장 주변 등에 일제소독을 실시한다. - 하수구·배수구와 침수되었던 곳은 청소 후 소독을 실시한다. - 습기가 찬 분말소독약은 굳어지는 것을 방지하기 위하여 그늘진 곳에서 말린다.', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 5.2.2 (PDF p.304)', '2026-05-06'::date, 'draft', 147, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '5.3 주의사항 5.3.1 소독약은 제품별로 특성이 있으므로 다른 소독약(특히 산성제재와 염기성 제재)과 섞어서 사용하지 않는다.', '구제역 긴급행동지침(SOP)', '별표 4 축산농장 준수사항 5.3 (PDF p.304)', '2026-05-06'::date, 'draft', 148, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '축산관련 종사자의 준수사항 1. 축산관련 종사자라 함은 임상수의사, 수집상, 중개상, 인공수정사, 가축분뇨·집유차량 기사, 동물약품· 사료·축산기자재 판매자, 낙농헬퍼, 백신접종요원, 농장관리자, 가축 운반기사, 사료운반기사, 임신진단사, 컨설팅·방역요원, 검정원 등 우제류 축산농장 및 관련 작업장 등에 관련이 있는 모든 사람을 말한다.', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 (PDF p.305)', '2026-05-06'::date, 'draft', 149, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2. 공통사항 2.1 축산관련 종사자는 전국 일시 이동중지(Standstill) 명령이 발령되면 해당 발령 시간 동안 모든 우제류 축산농장 및 축산관련 작업장 방문을 금지하고, 사람· 차량·장비·기구 등에 대한 소독 등 차단방역을 실시한다.', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 2 (PDF p.305)', '2026-05-06'::date, 'draft', 150, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.2 구제역 발생국가에 대한 여행을 자제하고, 해외여행 시 농림축산검역본부에 출입국 신고 및 입국 시 공항만 소독·최소 5일이상 농장 출입금지', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 2.2 (PDF p.305)', '2026-05-06'::date, 'draft', 151, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.3 농장을 출입하는 경우 1회용 방역복, 장갑, 장화 착용 등 개인 방역조치후 소독을 실시한 후 출입하고 차량·장비 등에 대하여 철저히 소독을 실시한다. - 소독은 농장 출입 전·후 각 1회 이상 소독 실시하고, 사용한 1회용 방역복은 현장에서 소각하거나 폐기한다. - 축산차량에 휴대용소독기를 비치하고 차량 내부에 대하여 소독을 실시한다.', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 2.3 (PDF p.305)', '2026-05-06'::date, 'draft', 152, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.4 구제역 의심축 발견 시 시군구 등에 신속히 신고한다. 2.5 불필요한 모임은 자제하고, 모임이후 철저한 소독 등을 실시하고 농장에 출입한다.', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 2.4 (PDF p.305)', '2026-05-06'::date, 'draft', 153, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.6 구제역 예방수칙 교육을 정기적으로 이수한다. 2.7 국가 및 지방자치단체의 구제역 방역대책 추진에 적극 협조한다. 2.8 구제역 발생 시 축산차량은 축산시설을 방문할 때마다 거점소독시설에서 소독 후 소독필증을 발급받아 운행하여야 하며, 방문하는 축산시설에 소독필증을 제출하여야 한다.', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 2.6 (PDF p.305)', '2026-05-06'::date, 'draft', 154, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '2.9 가축운반기사는 농장 출하작업 시 하차하여 가축을 직접 선발하거나 상차하는 등 가축과 직접 접촉하는 행위를 하지 않는다. / 3. 구제역 방역지역별 준수사항', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 2.9 (PDF p.305~306)', '2026-05-06'::date, 'draft', 155, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.1 구제역 발생지역 3.1.1 중개업자와 수집상은 방역기관의 허가 없이 가축의 농장입식이나 농장 밖 반출을 하지 않는다. - 단, 관할 시장·군수로부터 지정 도축장으로 출하를 승인받은 경우에는 가능', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 3.1 (PDF p.306)', '2026-05-06'::date, 'draft', 156, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.1.2 본인이 일하거나 출입한 농장에서 사육중인 가축에서 구제역 의심증상을 보일 경우 시군구 및 시도가축방역기관 등에 즉시 신고한다. 3.1.3 불필요한 축산농장 출입을 자제하고, 부득이한 경우 축산농장 출입 시 별도의 장화나 덧신 및 방역복을 착용하고, 농장을 벗어나는 경우 사용한 일회용 덧신 및 방역복을 벗어 폐기하도록 한다.', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 3.1.2 (PDF p.306)', '2026-05-06'::date, 'draft', 157, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.1.4 인공수정사 등 발생지역내 가축과 접촉한 사람은 당해 농장을 떠나기 전에 손, 의복 및 신발을 세척 및 소독하고 사용한 장비를 철저하게 세척·소독을 실시하며, 귀가 후 목욕과 세탁을 실시한다. 또한 7일 이상 타 농장의 방문을 자제한다', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 3.1.4 (PDF p.306)', '2026-05-06'::date, 'draft', 158, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.1.5 농장관리인 및 가축분뇨처리업자 등은 방역기관의 허가없이 가축의 분뇨를 야외에 살포하거나 농장 밖으로 반출하는 행위가 금지(다만, 축산분뇨 공통처리시설로 운반하는 경우는 이동허용)됨을 숙지한다.', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 3.1.5 (PDF p.306)', '2026-05-06'::date, 'draft', 159, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.1.6 낙농헬퍼, 백신접종자, 농장관리자, 임신진단자 등은 1개 농장 이상에 대해 출입하여 관리하지 않는다. 3.1.7 구제역 발생농장이나 발생농장과 역학적으로 관련되는 농장의 출입한 경우 시군구 등에서 별도의 통보가 오기 전이라도 차량 및 사람에 대한 세척과 소독을 실시하고, 감수성가축 사육농장 출입을 하지 말고 지체없이 방역 기관에 신고한다.', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 3.1.6 (PDF p.306)', '2026-05-06'::date, 'draft', 160, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.2. 구제역 발생 인접지역(시군) 3.2.1 발생지역 이동제한이 해제될 때까지 인접 시군내 우제류 농장은 1농장 1분뇨 처리장을 지정하여 처리한다.', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 3.2 (PDF p.306)', '2026-05-06'::date, 'draft', 161, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.2.2 분뇨 운반차량은 1일 1농장만 출입토록 한다. 3.2.3 검역본부에서는 전산시스템(KAHIS)를 활용하여 분뇨차량 이동 현황을 확인 하고 1일 1농장을 초과하여 이동한 것이 의심될 경우 현장점검 등을 실시한다.', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 3.2.2 (PDF p.306)', '2026-05-06'::date, 'draft', 162, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.3. 구제역 비발생 지역 3.3.1 불필요한 구제역 발생지역 방문 및 업종 관련 모임을 금지한다. 3.3.2 농장에 출입시 차량과 물품(기구, 장비 포함)을 철저히 소독 한다', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 3.3 (PDF p.307)', '2026-05-06'::date, 'draft', 163, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.3.3 가축에서 수포발생 등 구제역 의심증상을 보일 경우 즉시 읍·면·동/시군구 /시도 및 가축방역기관/검역본부에 신고한다. 3.3.4 발생지역·관리지역·보호지역의 농장을 방문하고 돌아왔을 경우 2주 이상 농장방문을 금지한다.', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 3.3.3 (PDF p.307)', '2026-05-06'::date, 'draft', 164, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'FMD', NULL, '3.3.5 구제역 발생농장이나 발생농장과 역학적으로 관련되는 농장의 출입한 경우 시군구 등에서 별도의 통보가 오기 전이라도 차량 및 사람에 대한 세척과 소독을 실시하고, 감수성가축 사육농장 출입을 하지말고 지체없이 방역기관에 신고한다. /', '구제역 긴급행동지침(SOP)', '별표 5 축산관련 종사자의 준수사항 3.3.5 (PDF p.307)', '2026-05-06'::date, 'draft', 165, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '제 1 장 렴피스킨이란 1.정 의 럼피스킨(1.61), 14000” 9140 0186886)이란 소과 동물 중 소 및 물소 등에서 주로 발생하는 질병으로서 피부, 점막, 내부장기의 결절과 여월, 림프절 종대, 피부부종을 특징으로 하는 소의 급ㆍ만성의 바이러스성 질병이다. 젖소의 생산성 저하로 인한 경제적 피해를 초래 하기도 한다. 이 질병은 가축전염병 예방법상 제1종 가축전염병이며, 세계동물보건기구 (\048)에서 관리대상 질병으로 분류ㆍ지정하고 있으며 발생 시 \04ㅅ에 통지해야 하는 질병이다. |. 병인체 럼피스킨의 병인체는 폭스바이러스과 카프리폭스바이러스속에 속하는 럼피스킨 바이 러스(1.8310\)이며 이중가닥 104ㅅ(150103)로 같은 (>300400※×\1ㅠ48속 바이러스인 양두 -산 양두와 높은 유사성(06%)을 가진다. 1개 혈청형으로서 양두 및 산양두 항체와 교차반응 하기 때문에 유전적 진단법으로만 구분할 수 있으며 혈청학적방법으로 구분은 불가하다.', '럼피스킨 긴급행동지침(SOP)', '제1장 럼피스킨이란 (PDF p.6) [OCR·원문대조 필요] [2026 제2종 전환 전 내용]', '2024-07-19'::date, 'draft', 1, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '11. 전파방법 럼피스킨의 주요 전파 요인은 흡혈 곤충에 의한 기계적 전파이다. 전파 가능한 흡혈 곤충으로는 모기류, 흡혈 파리, 수컷 진드기 등이 있다. 흡혈 곤충에 의한 기계적 전파 이외에도 감염된 동물에 의해 오염된 사료나 물 섭취 및 오염된 주사기 재사용에 의한 전파도 가능하다. 이 외에도 감염동물의 침이나 피부 병변, 콜, 우유, 정액 등도 감염원이 될 수 있다. 생축의 이동으로 인한 장거리 전파가 가능하다. |. 잠복기간 럼피스킨의 잠복기간은 보통 4일에서 14일 정도로 짧으며 세계동물보건기구(000401는 최대 잠복기를 28일로 본다. \ . 임상증상 잠복기간 후에 침울, 식욕부진, 과도한 침 흘림 등이 나타난다. 또한 고열(410 이상)과 전신성의 발진(1~2000이 생긴다. 발진은 피부와 근육에도 생기며 단단하고 결절성이며 통중이 동반된다. 병변은 머리, 목, 가슴 및 대퇴부를 중심으로 전신에 나타난다. 결절은 병이 진행됨에 따라 괴사가 일어나기도 하며, 종종 폐사하기도 한다. 감별진단은 허피스바이러스성 피부병, 구진성 구내염, 가성우두, 사상충증, 백선증, 경피증, 모낭층증, 곤충 흠혈에 의한 두드러기 등 피부결절을 유받하는 질병을 대상으로 필요 하다. 주요 감별진단 질병에 대한 특징은 아래의 표를 참고한다. <럼피스킨과 감별이 필요한 질병 정보 (출처 : 840 2017)> 0) 허피스 바이러스성 피부병 2) 구진성 구내염 6) 가성우두 <피부 표면에 얄은 피부 결절, <구강 점막에서만 병변 관찰> ㅣ<유방과 유두에서만 병변 관찰> 단기간 경증의 증상을 보임> 0) 사상충증 6) 백선증ㆍ방선균증 6) 경피증 <복부 중앙에 피부병변 <피부 표면에 얄고 <탈모가 동반된 가능성 높음> 확연한 비궤양성의 병변 관찰> 두꼬 주름진 피부병변> 0) 모낭충증 곤충흡혈, 두드러기, 광과민성 피부병 <탈모가 동반되며, <피부 표면에 알은 피부 병변, 단기간 경증의 증상을 보임> 주로 기갑(1169), 목, 등, 옆구리에서 피부병변을 보이며 어낸 피부에서 진드기 관찰> |. 진 단 럼피스킨의 진단 방법으로는 크게 동물 체내에 럼피스킨 바이러스의 존재 유무를 검색 하는 항원 진단법과 럼피스킨 바이러스의 감염 결과 형성된 항체를 검출하기 위한 항체 진단법으로 나눌 수 있 항원 진단법으로는 피부결절, 가피, 혈액, 인후두 스압 등을 검사시료로 하며, 세포 배양을 이용한 럼피스킨 바이러스의 분리, 신속유전자진단법(7601-ㅁ01046 10221)을 이용한 럼피스킨 바이러스 특이 유전자 검출 방법 등이 주로 이용된다. 항체 진단법으로는 동물의 혈액을 채취하여 혈청 내 럼피스킨 바이러스의 항체 형성 여부를 검출하는 혈청중화시험, 항체검사용 0118ㅅ 검사법 등이 주로 이용된다. 현재 국내에서는 7631-1ㅁ0276 20 검사기법, 8Ｌ184ㅅ 검사법 및 혈청중화시험 등이 럼피스킨의 확정 진단에 활용되고 있다.', '럼피스킨 긴급행동지침(SOP)', '제1장 럼피스킨이란 11 (PDF p.6~8) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 2, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '1. 방역대책 국내에서 럼피스킨으로 의심되는 임상증상이 나타나는 의심축을 발견할 경우에는 읍-면-동, 시:군, 시-도, 시-도 가축방역기관 및 농림축산검역본부(이하 “검역본부”라 한다)에 신고 하여 최단 시간 내에 정밀진단이 이루어져야 하고 즉각적인 방역 대책이 실시되어 이로 인한 가축 사욕 농장 및 축산업의 피해를 최소화하여야 한다. ※ 용어정의 럼피스킨 : 렁피스킨(1.61), 14700 9140 01668356)이란 소과 동물 중 소 및 물소 등에서 주로 발생하는 질병으로서 피부, 점막, 내부장기의 결절과 여월, 림프절 종대, 피부부종을 특징으로 하는 소의 급ㆍ만성 바이러스성 질병이다. 세계동물보건기구(\0/내) : 동물 질병 방제에 대한 국제적 협력을 위하여 1924년 28개국의 참여로 1116 00106 10[670310100381 068 01200068(010)를 창설한 이래 2003년 5월에 1116 \07ㅁ00 ()768018800ㅁ0 1017 10171] 1ㅁ1621며로 이름을 변경하였다. 발생농장 : 럼피스킨 의심축, 의사환축, 환축이 발생된 가축의 사욕시설(축사)이 있는 농장 발생지 : 발생농장이 소재한 마을로서 동일한 생활권으로 리 단위 보다 작은 부락단위 개념으로 주변 방역여건 등을 감안하여 시장ㆍ군수가 시ㆍ도 가축방역기관장과 협의하여 설정한다. 발생지역 : 발생농장이 소재한 시군ㆍ구를 말한다. 인접지역 : 발생지역과 연접한 시-군ㆍ구를 말한다. 관리지역 : 럼피스킨에 오염되었거나 오염되었다고 의심되는 지역으로 발생농장을 중심 으로 하여 반경 5000 이내의 지역을 말한다. 다만, 시장ㆍ군수는 해당 지역의 축산업 형태, 지형적 여건, 생활권, 계절적 요인 또는 역학적 특성 등을 감안하여 관리지역의 범위를 특별시장:광역시장:특별자치도지사 또는 도지사(이하 “시ㆍ도지사”라 한다) 소속 지방 가축방역심의회위원, 시도 및 시ㆍ군 관계관 및 농림축산검역본부(이하 “검역본부”라 한다) 현지 파견담당관과 협의를 거쳐 이를 확대하거나 축소할 수 있다. 보호지역 : 럼피스킨의 추가 발생이 우려되는 지역으로서 백신접종 상황에서는 발생농장을 중심으로 하여 반경 5000부터 500 이내의 지역을 말하며, 백신 미접종 상황에서는 발생농장을 중심으로 하여 반경 5000부터 3107 이내의 지역을 말한다. 다만, 시장ㆍ군수는 해당 지역의 축산업 형태, 지형적 여건, 생활권, 계절적 요인 또는 역학적 특성 등을 감안하여 보호지역의 범위를 시-도지사 소속 지방 가축방역심의회위원, 시도 및 시-군 관계관 및 검역본부 현지 파견담당관과 협의를 거쳐 이를 확대하거나 축소할 수 있다. 예찰지역 : 렁피스킨의 확산이 우려되는 지역으로서 발생농장을 중심으로 반경 3107를 초과하여 1002 이내의 지역을 말한다. 다만, 시장ㆍ군수는 해당 지역의 축산업 형대, 지형적 여건, 생활권, 계절적 요인 또는 역학적 특성 등을 감안하여 관리지역의 범위를 시ㆍ도지사 소속 지방 가축방역심의회위원, 시도 및 시:군 관계관 및 검역본부 현지', '럼피스킨 긴급행동지침(SOP)', '제1장 럼피스킨이란 1 (PDF p.8~9) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 3, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '파견담당관과 협의를 거쳐 이를 확대하거나 축소할 수 있다. 권역 : 기본적으로 시도 또는 시ㆍ군:구로 구분된 행정구역으로, 필요시 검역본부장이 가축방역을 목적으로 가축의 사육밀도, 사료공급, 종축이동, 도축장 이용형태 등 역학사항을 고려하여 지역을 구획화한 것을 말한다. 럼피스킨이 발생한 권역을 “발생권역"이라 한다. 방역지역(방역대) : 관리지역, 보호지역, 예찰지역을 말한다. 신고 : 축주 또는 축산관련 종사자 등이 럼피스킨에 감염된 것으로 의심되어 가축방역 기관에 유선 등을 통하여 알리는 것을 말한다. 의사환축 검사 : 시도 가축방역기관의 가축방역관이 임상검사 등을 실시한 결과 럼피스킨에 걸렸다고 믿을 만한 상당한 이유가 있는 가축에 대해 실시하는 럼피스킨 정밀 검사를 말한다. 병성감정 검사 : 림피스킨 의심축 신고농장에 대해 시ㆍ도 가축방역기관 가축방역관이 임상검사 등을 실시한 결과, 렴피스킨 의사환축으로 판단이 어럼거나 럼피스킨 이외의 가축질병으로 의섬되는 경우 럼피스킨을 포함한 가축전염병 감염 여부를 확인하는 정밀검사를 말한다. 예방적살처분 검사 : 럼피스킨의 추가확산 또는 발생을 사전에 예방하기 위하여 발생 놓장을 중심으로 럼피스킨이 퍼지는 것이 우려되는 지역 안에 있는 감수성 가축을 살처분 할 때 럼피스킨 감염 여부를 확인하는 정밀검사를 말한다. 역학관련 검사 : 럼피스킨 발생농장 또는 럼피스킨 오염시설과 역학적으로 관련이 차량이나, 농장 또는 시설 내 감수성 동물 등에 대하여 럼피스킨 오염여부를 확인하는 정밀검사를 말한다. 예찰 검사 : 방역지역 내 농장 또는 시설 내 감수성 동물에 대하여 럼피스킨 감염 여부를 확인하는 정밀검사를 말한다. 유입경계상황 : 중국, 몽골, 러시아 극동지역, 대만, 일본, 북한 등 지리적으로 우리 나라와 인접한 국가(지역)에서 럼피스킨이 발생하거나 우리나라와 인적ㆍ물적 교류가 많은 나라에서 발생하는 상황 의심축 신고상황 : 축주 및 축산관련 종사자 등이 럼피스킨에 감염된 것으로 의심하여 가축방역기관에 유선 등을 통하여 신고된 상황을 말한다. 의사환축 발생상황 : 럼피스킨에 감염된 것으로 의심되는 동물(의사환축)이 발견되었을 때를 발한다. 의사환축에 대한 즉각적인 렴피스킨 정밀전탄이 이루어져야 한다. 발생확인상황 : 러피스킨에 감염된 동물의 확진이 이루어졌을 때를 말한다. 국가방역 이량을 총집결하여 럼피스킨의 확산을 방지하고 반드시 초기에 차단하도록 힘써야 한다. 발생확산상황 : 인근지역 및 전국으로 럼피스킨이 확산되고 있는 상태를 뜻한다. 국가와 전 국민이 합심하여 럼피스킨 조기근절에 힘써야 한다. 의심축 : 축주 또는 축산관련 종사자 등이 럼피스킨으로 의심되어 소 신고한 가축으로 시ㆍ도 가축방역기관 가축방역관이 확인하기 전의 가축을 말한다. 의사환축 : 시ㆍ도 가축방역기관 소속의 가축방역관이 임상검사 등을 실시한 결과 럼피스킨에 걸렸다고 믿을 만한 상당한 이유가 있다고 관탄한 가축을 밀한다 시도 럼피스킨 정밀진단기관 : 시-도 가축방역기관으로서 일정한 조건을 갖추고 럼피', '럼피스킨 긴급행동지침(SOP)', '제1장 럼피스킨이란 (PDF p.9~11) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 4, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '스킨 의심축, 의사환축 및 바이러스 전파 위험요인에 대한 시료 채취, 임상검사 및 실험실 진단을 실시할 수 있는 기관 환축 : 럼피스킨 의사환축에 대한 정밀검사를 실시하여 럼피스킨에 감염된 것으로 확인된 가축을 말한다. 잠복기 : 득정병원체가 동물에 침입한 후 그 질병의 최초 임상증상이 발현될 때까지 소요되는 기간을 말한다. 살처분 : 럼피스킨에 걸렸거나 걸렸다고 믿을만한 역학조사ㆍ정밀검사 결과나 임상증상이 근 ^ 있는 경우, 당해 가축이 있는 농장 또는 당해 가축이 있었던 장소를 중심으로 럼피스킨이 퍼지는 것이 우려되는 지역 안에 있는 감수성 가축을 죽이는 것을 말한다. 방제 : 유충의 서식장소가 되는 웅덩이를 제거하는 등의 물리적 방제, 미꾸라지송사리 등 푸식동물을 이용하는 생물학적 방제, 유기화학제재(살충제 등)를 사용하는 화학적 방제 등 침파리, 모기 등 매개곤충을 사멸시키기 위하여 실시하는 작업을 말한다. 소독 : 전염병 병원체를 사멸시키기 위해 실시하는 작업을 뜻하며, 소독은 동물, 가축 분뇨 또는 동물 유래의 생산물 등에 의해 직접 혹은 간접적으로 오염될 수 있는 동물, 사람, 시설, 수송차량 및 기타 대상물에 대해 실시한다. 가축 등에 대한 일시이동중지(6180061411) : 럼피스킨이 국내에서 발생하였거나 전국적으로 확산되어 심각한 피해가 발생할 것으로 판단되는 경우, 전국(또는 지역별)의 감수성 가축 사육 농장 및 관련 작업장 등에 대해 가축-사람:차량:물품 등의 출입을 일시 중지(48시간 이내 - 필요시 연장)하는 조치를 말한다. 긴급 백신(6076『96060\ \8ㅎㅇ10811010) : 럼피스킨이 발생한 경우 긴금하게 발생농장을 중심으로 일정 범위 내의 감수성 가축에 대해 실시하는 링-백신, 일정 지역 내의 감수성 가축에 대하여 실시하는 지역 백신, 인접 지역의 감수성 가축에 대해 광범위하게 실시하는 장벽 백신, 전국 단위 감수성 가축에 대해 실시하는 전국 백신 등을 말한다. 정기 백신(685816008110 \8ㅎ3601083100) : 백신접종 프로그램에 따라 상시적으로 실시 하는 백신을 말한다. 럼피스킨 백신접종 상황 : 백신접종 정책에 따라 소에 대한 백신접종 후 3주가 지나고 1년이 지나지 않은 상황으로 농식품부 장관이 판단하여 알런다.(지역별 적용 가능) 럼피스킨 백신 미접종 상황 : 백신접종 정책에 따라 소에 대한 백신접종 후 3주가 지나지 않았거나 1년 이상 지난 상황으로 농식품부 장관이 판단하여 알린다.(지역별 적용 가능) ㆍ 주 > 1 1 주 축산농장 : 한-육우, 젖소 등 감수성 가축을 사육하는 농장을 말한다. 축산관련 종사자 : 임상수의사, 수집상, 중개상, 가축분뇨 기사, 동물약품-사료:축산 기자재 판매자, 농장관리자, 가축운반기사, 사료운반기사, 컨설팅 등 축산농장 및 관련 작업장 등에 종사하는 모든 사람을 포함한다. 모든 축산관련 작업장 : 수 도축장, 사료공장, 사료하치장, 사료대리점, 분뇨처리장, 공동퇴비장', '럼피스킨 긴급행동지침(SOP)', '제1장 럼피스킨이란 (PDF p.11~12) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 5, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '가축분뇨공공 처리장, 공동자원화시설, 축산관련 운반업체, 축산관련 용역업체, 축산시설: 장비 설치:보수업체, 축산 컨설팅업체, 퇴비제조업체, 동물약품 및 축산기자재 판매업체 등을 포함한다. 이통제한 : 전영병의 확산 및 전파를 차단하기 위해서 오염되었거나 역학적으로 관련 되어진 가축-시설ㆍ물건ㆍ차량ㆍ사람 등에 대해 정해진 기간에 이동을 차단하는 것을 말한다. 역학조사 ; 가작전영빈 발생 시 역학적 특성을 파악하여 이 질병에 관한 유입 및 전파ㆍ 확산 위험요인을 찾아내고 규명하는 과정을 말한다. 거점소독시설 : 시설출입차량이 방역 관련 규정에 따라 이동 시 소독을 실시하고 소독 필중을 발급하는 시설로, 시군구 또는 시ㆍ도 가축방역기관이 설치ㆍ운영하는 시설 및 관련 지침에 따라 별도로 지정받은 민간시설을 말한다. 위험도평가 : 렁피스킨 발생과 관련하여 이동제한 중인 가축ㆍ분뇨 등의 이동 또는 축산 시설의 운영을 위해 축산업 형태, 지형적 여건, 모기 등 매개곤충의 서식 실태, 계절적 요인, 역학적 특성 및 정밀검사 등을 감안하여 위험성을 평가하는 조치를 말한다.', '럼피스킨 긴급행동지침(SOP)', '제1장 럼피스킨이란 (PDF p.12) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 6, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '제 4 장 백신접종 상황에서 럼피스킨 발생 시 1. 의심축 신고 및 의사환축 발생 시 조치사항 1. 럼피스킨 의심축 발생 신고 1.1 축주(관리인 포함)나 수의사 등 축산관련 종사자 등은 가축에서 지름 3~500 정도의 단단한 피부 결절 등이 형성되거나 고열, 과도한 침 흘림, 림프절 종대, 유량 감소 등 럼피스킨 의심증상이 있는 의심축을 발견하면 즉시 가축질병 신고 전용전화 (1588-4060, 1588-9060) 또는 다음 각 호의 기관에 신고하여야 한다. - 시ㆍ군(을 ㆍ면ㆍ동 포함) 가축방역업무 담당과 - 시 ㆍ도 및 시ㆍ도 가축방역기관(동물위생시험소 등) - 농림축산검역본부(방역감시과) - 농림축산식품부(구제역방역과)', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 (PDF p.35) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 7, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '1. 축주(관리인 포함)나 수의사 등 축산관련 종사자 등으로부터 의심축 신고를 받은 기관은 축주 등에 대해 아래의 조치를 하고, 즉시 시ㆍ도, 시ㆍ도 가축방역기관 및 검역본부에 보고하여야 한다. - 농장 내에 머물도록 지시하고 항상 연락이 가능하도록 조치 - 농장의 가축, 분뇨, 장비, 물품 등의 이동제한 조치 - 농장의 가축수송차량, 집유차 및 기타 차량의 출입 제한 - 농장 내 모든 사람의 외출 금지', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 1 (PDF p.35) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 8, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '1.3 축산 관련 종사자 등이 의심축을 신고한 경우 4장. 2 “의심축을 발견한 축산관련 종사자의 조치사항”에 따라 조치한다. ※ 의심축 신고상황 보고체계 : 음ㆍ면ㆍ동->시ㆍ군, 시ㆍ도 가축방역기관->시ㆍ도, 농림축산검역본부, 농림축산식품부', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 1.3 (PDF p.35) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 9, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '1.4 의심축 발생농장의 농장주 이름 등 개인정보는 외부(업무 담당자 등 관계자 이외)로 유출되지 않도록 관리하여야 한다. 2. 의심축 발생 신고 접수 및 초기 조치사항', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 1.4 (PDF p.35~36) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 10, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.1. 의심축 신고(통보)를 받은 시ㆍ도 가축방역기관은 별지 제1호 서식의 "럼피스킨 의섬축 신고서"를 작성하여 시도, 검역본부, 농식품부에 보고하여 지시를 받아야 하며, 검역본부에서 운영하는 국가가축방역통합시스템(이하 “/168”라 한다)에 의심축 신고서를 등록하여야 한다. - 의심축 발생농장에 대한 역학조사 후 역학정보를 검역본부 및 농식품부에 보고 (알림)하여야 한다. 검역본부는 의심축 발생농장에 대한 역학정보를 추가로 파악 하여 농식품부에 보고하고 필요시 역학조사반을 현장에 출동시켜야 한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 2.1 (PDF p.36) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 11, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.2. 시ㆍ도 가축방역기관장은 시ㆍ도, 검역본부, 농식품부에 의심축 신고상황 보고 후 해당 농장에 럼피스킨 담당 가축방역관 2명 이상을 출동시킨다. 다만, 발생이 확산 되어 럼피스킨 담당 가축방역관의 운영이 원활하지 않을 경우 그러하지 아니하다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 2.2 (PDF p.36) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 12, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.3 시ㆍ도 가축방역기관장은 럼피스킨 담당 가축방역관이 의심장소까지 도착하는데 장 시간이 소요될 것으로 예상되는 경우에는 해당 시ㆍ군 관계관으로 하여금 신고 농장에 먼저 도착토록 하여 이동제한 등 차단방역을 실시하도록 조치한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 2.3 (PDF p.36) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 13, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.4 시ㆍ도 럼피스킨 담당 가축방역관은 의심장소로 출발할 때에는 의심축 신고서 사본과 럼피스킨 긴급행동지침 및 별표1의 “초기 검진시의 긴급방역용 용구” 등을 휴대하여야 한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 2.4 (PDF p.36) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 14, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '3. 럼피스킨 의심축 신고 농장 도착 후의 조치(시도 가축방역기관) 3.1 현장에 도착한 가축방역관 등은 타고 온 차량을 농장 밖에 주차시키고, 위생 작업복 및 장화 등을 착용하고 소독 등 개인방역조치를 실시하고 농장에 들어간다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 3 (PDF p.36) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 15, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '3.2 가축방역관 등은 의심축 신고농장 내 모든 동물에 대해 임상검사를 실시한다. - 1명은 의섬축이 있는 축사, 나머지 1명은 의심축이 없는 축사의 동몰에 대해 임상검사를 실시한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 3.2 (PDF p.36) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 16, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '3.3 임상증상이 발현된 개체를 발견한 경우, 정밀검사용 시료를 채취한다. 3.4 농장에서 벗어날 경우에는 세척 및 소독 등 방역조치를 취하여야 한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 3.3 (PDF p.36) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 17, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '4. 의심축 신고농장 임상검사결과 등에 따른 조치(시ㆍ도 가축방역기관) 4.1 “의사환축으로 판단되는 경우” - 임상검사 결과 럼피스킨 희사활축으로 확인되는 경우 즉시 소속기관장에게 보고 - 시ㆍ도 가축방역기관장은 별지 제2호 서식의 "의사환축 발생신고서"에 따라 당해 동물 등에 대한 검진과 가축의 이동상황, 분뇨의 이동, 출입자현황 등 역학조사를 실시한 후 시도(시ㆍ:군)에 보고(통보)하고 이를 4ㅅ115에 등록한다. - 서-도 가축방역기관 가축방역관은 발생농장에 대한 역학조사를 실시하고 방역조치 대상을 선정하여 농식품부, 전국 시ㆍ도/시:군:구, 검역본부에 즉시 알려야 한다. - 시-도 가축방역관은 시료를 채취한 후 즉시 검역본부(해외전염병과)로 송부하여야 한다, 다만, 럼피스킨 정밀진단기관으로 지정받은 시ㆍ도 가축방역기관은 가축방역관으로 하여금 시료를 채취한 후 동등한 시료 세트 중 1세트는 자체 정밀검사를 실시하고 나머지 1세트는 검역본부(해외전염병과)로 송부하여야 한다. 검사기관은 정밀검사 결과를 /405에 등록 및 농석품부 장관, 검역본부장 및 시ㆍ도지사에게 보고(통보)하여야 한다 - 발생농장에 대한 가축-차량-사람(축주:종사자-수의사-축산관련종사자 등)ㆍ물품 등에 대하여 정밀검사가 나올 때까지 이동제한 등 차단방역을 실시한다. - 의사환축은 별도로 격러하고 농장주가 농장의 소독을 실시토록 조치한다. - 최종 검사결과가 나올 때까지 농장 내 또는 현장 통제초소에서 현장방역 조치를 지시한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 4 (PDF p.36~37) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 18, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '4.2 “의사환축으로 판단이 어려운 경우” - 가축방역관은 “의사환축으로 판단이 어려운 경우" 소속 기관장에게 보고하고, 시료를 채취하여 검역본부에 럼피스킨 검사를 포함한 병성감정을 의뢰한다. 다만, 럼피스킨 정밀진단기관으로 지정받은 시ㆍ도 가축방역기관은 가축방역관으로 하여금 시료를 채취한 후 동등한 시료 2세트 중 1세트는 자체 정밀검사를 실시하고, 검사결과 양성인 경우 나머지 1세트는 즉시 검역본부(해외전염병과)로 송부하여야 한다. - 럼피스킨 검사결과가 나올 때까지 해당 농장의 가축:차량-사람ㆍ물품 등에 대해 이동통제 등 방역조치를 유지하고, 럼피스킨 검사결과 음성으로 판정 시 방역조치를 해제한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 4.2 (PDF p.37) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 19, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '4.3 “의사환축이 아닌”것으로 판단되는 경우 - 가축방역관은 임상검사 등에 따라 “의사환축이 아닌”것으로 판단 될 경우 소속 기관장에게 보고하고 추후 지시를 받는다. - 소속 기관장으로부터 상황을 종료하라는 지시를 받은 가축방역관은 이를 축주(신고자) 에게 통지하고 농장에 대하여 취했던 이동통제 등 긴급방역조치를 해제한다 - 관할지역 시장:군수는 긴급방역조치를 해제하고 해당 시ㆍ도지사에게 보고하며, 시:도지사는 농림축산식품부장관 및 검역본부장에게 상황종료 사실을 보고(통보)한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 4.3 (PDF p.37) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 20, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5. 의심축 신고 또는 의사환축 발생 시 기관별 방역조치사항 5.1 시장ㆍ군수의 조치사항 5.1.1 해당 농장에 대한 가축ㆍ사람ㆍ차량 등의 이동제한 조치 - 가축위생방역지원본부의 초동방역팀과 농협 공동방제단을 현장에 투입한다. - 해당 농장의 출입구를 1개소로 제한하여 현장 통제초소를 설치하고, 통제초소에는 소독조ㆍ 소독장비를 설치한다. 발생농장이 축산밀집지역에 위치하는 경우 인접한 축사ㆍ도로 현황 등을 고려하여 통제초소를 설치한다. - 축주로 하여금 농장 내 축사ㆍ운동장ㆍ차량ㆍ축산기자재 등에 대한 청소(세척) ㆍ 소독, 사람에 대한 소독을 실시토록 조치한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5 (PDF p.37~38) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 21, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.1.2 럼피스킨 발생에 대비하여 방역지역 설정 등 아래의 방역 조치사항을 준비한다. - 방역지역(관리, 보호, 예찰) 설정 준비 및 방역지역별 농장현황 조사 - 방역지역별 통제초소 및 거점소독시설 설치 준비 - 살처분ㆍ사체 처리, 이동통제, 소독, 예찰, 매개체 구제 등 초동방역을 위한 인력ㆍ 장비 ㆍ약품ㆍ매몰지 등의 조달 준비 - 긴급백신접종을 위한 인력 동원체계 준비 - 럼피스킨 방역대책본부(본부장 : 기관장) 및 상황실 설치 준비(전국) - 일시이동중지(513008101) 시행에 대비, 상황 전파체계 준비 및 점검(전국)', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.1.2 (PDF p.38) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 22, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.2 가축위생방역지원본부장의 조치사항 5.2.1 시장ㆍ군수, 시ㆍ도 가축방역기관장 또는 농식품부장관의 요청(지시)이 있을 경우 제4장 4. “초동방역팀 운용 요령"에 따라 초동방역팀을 두입하여 의심축 발생농장에 대한 가축ㆍ사람:차량 등의 출입금지 및 진입로 소독 등 초동 방역조치를 한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.2 (PDF p.38) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 23, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.2.3 해당 시군, 인접 시-군 및 역학농장 등의 이상여부 확인을 위해 전화예찰을 실시한다. 5.3 시 ㆍ도 가축방역기관장의 조치사항 5.3.1 시ㆍ도(시ㆍ군) 및 검역본부에 별지 제1호 서식의 "럼피스킨 의심축 신고서", 별지 제2호 서식의 "의사환축 발생 신고서"를 작성하여 송부하고, &115에 등록한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.2.3 (PDF p.38) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 24, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.3.3 럼피스킨 의심축 신고농장 내 모든 감수성 가축에 대한 임상검사를 실시하고, 임상 증상 발현 개체에 대해 시료를 채취하여 검역본부에 신속히 송부한다. 럼피스킨 정밀진단기관으로 지정받은 시ㆍ도 가축방역기관은 가축방역관으로 하여금 시료를 채취한 후 동등한 시료 3세트 중 1세트는 자체 정밀검사를 실시하고 나머지 1세트는 즉시 검역본부(해외전염병과)로 송부하여야 한다. 검사기관은 정밀검사 결과를 6415에 등록하고 농식품부 장관, 검역본부장 및 시ㆍ도지사에게 보고하여야 한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.3.3 (PDF p.38) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 25, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.3.3 현장 파견중인 가축방역관에게 가축 및 분뇨 등의 이동사항, 출업자, 출입차량 등에 대한 역학조사를 실시하도록 조치한다. 5.3.4 의사환축 판정 시 가축방역관을 추가 파견하여 해당농장 반경 5002 내외의 소 사육 농장에 대해 임상관찰을 실시한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.3.3 (PDF p.38~39) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 26, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.3.5 발생농장의 이동제한, 소독, 매개체 구제 및 매몰 등 방역 기술지원을 위하여 가축 방역관을 현장에 상주시킨다. 5.3.6 럼피스킨 방역대책 상황실(실장 : 기관장) 설치를 준비한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.3.5 (PDF p.39) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 27, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.4. 시ㆍ도지사의 조치사항 5.4.1 의심축 또는 의사환축 발생 사실을 지체없이 농림축산식품부 및 검역본부에 유선 으로 우선 보고하고, 시ㆍ도 가축방역기관에서 \ㅅ1118에 입력한 상황을 확인한 후, 타 시ㆍ도에 통보한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.4 (PDF p.39) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 28, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.4.2 시 ㆍ군 및 시ㆍ도 가축방역기관에 “의사환축 발생”에 따른 긴급 방역조치를 시달하고 추진상황을 점검한다. 5.4.3 럼피스킨 발생에 대비하여 방역지역 설정 등 아래의 방역 조치를 준비한다. - 방역대별 통제초소 및 거점소독시설 설치 준비 - 살처분ㆍ사체 처리, 이동통제, 소독, 매개체 구제, 예찰 등 초동방역을 위한 인력ㆍ 장비 ㆍ약품ㆍ매몰지 등의 조달 준비 - 발생지역 소재 군부대, 지방경찰청의 방역통제 인력 지원체계 확인 - 긴급백신접종을 위한 인력 동원체계 준비 - 시ㆍ군별로 거점소독시설 설치 준비 - 시ㆍ군 및 시ㆍ도 가축방역기관에 긴급 방역조치 시달 및 점검 - 럼피스킨 방역대책본부(본부장 : 기관장) 및 상황실 설치 준비(전국) - 일시이동중지(56[3008101) 시행 대비, 상황 전파체계 준비 및 점검', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.4.2 (PDF p.39) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 29, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.5 검역본부장의 조치사항 5.5.1 의심축 및 의사환축 발생 사실을 통보받은 즉시 농림축산식품부에 보고한다. - 보고시 방역지역(관리, 보호, 예찰) 내 개괄적 농장 현황을 포함한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.5 (PDF p.39) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 30, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.5.2 시도 가축방역기관장이 조사한 1차 역학조사 내용을 전달받아 추가 역학조사 및 역학분석을 실시하고 방역조치 대상을 선정하여 농식품부와 시도에 보고(통보)', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.5.2 (PDF p.39) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 31, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.5.3 채취 시료에 대한 정밀검사를 신속히 실시하고, 그 검사결과를 ㅅ116에 등록하고 농식품부 장관에게 보고하며, 해당 시ㆍ도지사 및 그 밖의 다른 시ㆍ도지사 에게 통보한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.5.3 (PDF p.39) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 32, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.5.4 럼피스킨 방역대책 상황실(실장 : 기관장) 설치를 준비한다. 5.5.5 기동방역기구 파견에 대비하여 관계관의 출동을 준비(초동대응팀 포함)한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.5.4 (PDF p.39~40) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 33, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.5.6 긴급 백신접종 방안(접종 프로그램 포함) 및 백신 공급계획을 겪토한다. 5.6. 농림축산식품부 장관의 조치사항 5.6.1 의사환축 발생에 따른 “주의” 단계 위기경보를 발령하고, 관계기관에 상황전파 및 긴급 방역조치를 송부한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.5.6 (PDF p.40) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 34, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.6.2 8[30ㅁ08011 시행에 대비, 상황 전파체계를 준비하고 점검한다. 5.6.3 럼피스킨방역대책본부(본부장 : 장관) 및 상황실 설치를 준비한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.6.2 (PDF p.40) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 35, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.6.4 동식품부 기동방역기구 파견을 준비한다. 5.6.5 국방부ㆍ경찰청 등에 의사환축 발생사실을 통보하고, 인력 지원체계를 점검한다. 5.6.6 긴급 백신접종 실시에 대비한 백신 수급계획을 검토한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 1. 의심축 신고 및 의사환축 발생 시 조치사항 5.6.4 (PDF p.40) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 36, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2. 의심축을 발견한 축산관련 종사자의 조치사항 1. 기본원칙 수의사 등 축산 관련 종사자가 럼피스킨 의심축을 발견하는 경우에는 축주로 하여금 해당 농장의 가축, 사람, 차량, 물품, 분뇨 등의 이동을 금지하고, 시ㆍ군 및 시ㆍ도 가축 방역기관 등에 신고한 후 농장 내에서 대기하여야 한다. * 축산관련 종사자 : 임상수의사, 수집상, 중개상, 인공수정사, 가축분뇨ㆍ집유차량 기사, 동물약품-사료:축산기자재 판매자, 낙농헬퍼, 백신접종요원, 농장관리자, 가축운반기사, 10 사료운반기사, 임신진단사, 컨설팅, 방역요원, 검정원 등 소 사육농장 및 관련 작업장 등에 종사하는 모든 사람을 말한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 2. 의심축을 발견한 축산관련 종사자의 조치사항 2 (PDF p.41) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 37, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2. 수의사 등 축산관련 종사자의 의심축 발견 시 신고 및 대응요령 2.1 수의사의 의심축 발견 시 조치사항 2.1.1 환축을 발견한 경우 축주에게 환축이 럼피스킨 의심축임을 설명하고, 즉시 관할지 읍ㆍ면장, 시장ㆍ군수 또는 시ㆍ도 가축방역기관장에게 전화 등으로 신고한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 2. 의심축을 발견한 축산관련 종사자의 조치사항 2 (PDF p.41) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 38, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.1.2 임상수의사는 시ㆍ도 가축방역관이 농장에 도착할 때까지 농장을 떠나지 말고 축주 에게 다음의 긴급 방역조치를 하도록 지도한다. - 확산 방지를 위하여 의심축을 격리하고 모든 사욕동물(개, 고양이, 닭 등 포함)을 묶거나 축사 문을 닫아 이동하지 못하도록 한다. - 농장의 출입구를 1개소로 하고 소독조를 설치하여 방역관계자 이외에는 출입을 금지 한다. 동력분무기나 휴대용분무기가 있으면 설치한다. 또한, 각 축사의 출입구에 신발 소독조를 설치하고 이미 설치되어 있는 경우 새로운 소독약으로 교체한다. - 축주와 관리자, 가족에게 럼피스킨 정밀검사 결과가 나올 때까지 외출하지 못하도록 한다. 다만, 긴급을 요하는 경우(질병 등)에는 소독한 후 출입을 허용한다. - 농장에 차량 등이 출입하지 않도록 한다. 불가피하게 출입이 필요한 경우에는 충분 하게 소독한 후 출업시킨다. - 농장 사육시설, 옥외, 농장 밖으로 원유, 사료, 퇴비 등을 반출하지 못하도록 한다. - 배수구를 폐쇄한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 2. 의심축을 발견한 축산관련 종사자의 조치사항 2.1.2 (PDF p.41) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 39, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.1.3 가축방역관이 도착하면 모든 현장상황을 설명하여 인계한 후 가능한 한 시료채취 등에 협조한다. 필요시 시ㆍ도지사 또는 가축방역기관장으로부터 역학조사반원으로 위촉되어 해당 농장의 역학조사, 시료 채취 업무 등을 수행할 수 있다.', '럼피스킨 긴급행동지침(SOP)', '제4장 2. 의심축을 발견한 축산관련 종사자의 조치사항 2.1.3 (PDF p.42) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 40, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.1.4 농장을 떠날 때에는 가축방역관의 입회 하에 신체:의복-신발ㆍ안경 및 진료기구: 가방 등 휴대한 물품에 대한 소독을 설시하고 타고 은 차량에 대하여 세차-소독을 실시한다. 착용한 의복을 벗고 깨끗한 다른 의복 또는 일회용 방역복으로 갈아 입은 다음 코를 풀고 입을 행군 후 진료를 중단하고 귀가하도록 한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 2. 의심축을 발견한 축산관련 종사자의 조치사항 2.1.4 (PDF p.42) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 41, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.15 귀가 후 다시 차량, 진료기구, 기타 휴대물품, 의복-신발 등을 완전히 소독하고 목욕을 한 후 새로운 의복으로 갈아입는다. 2.1.6 정밀검사 결과 럼피스킨이 아니라는 연락이 있기 전까지 외출을 삼가고 감수성 가축을 사육하는 자 등과 만나지 않는다.', '럼피스킨 긴급행동지침(SOP)', '제4장 2. 의심축을 발견한 축산관련 종사자의 조치사항 2.15 (PDF p.42) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 42, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.1.7 럼피스킨으로 판정될 경우 관련 차량은 세척ㆍ소독, 사람은 샤워ㆍ환복 후 환경검사 음성인 경우 이동을 허용한다. 2.2 그 외 축산 관련 종사자의 의심축 발견 시 조치사항', '럼피스킨 긴급행동지침(SOP)', '제4장 2. 의심축을 발견한 축산관련 종사자의 조치사항 2.1.7 (PDF p.42) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 43, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.2.1 축주에게 동장에서 럼피스킨 의심축을 발견하였음을 설명하고, 즉시 관할지 읍ㆍ면장, 시장ㆍ군수 또는 시ㆍ도 가축방역기관장에게 전화 등으로 신고한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 2. 의심축을 발견한 축산관련 종사자의 조치사항 2.2.1 (PDF p.42) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 44, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.2.3 축산관련 종사자는 시ㆍ도 가축방역관이 도착할 때까지 농장을 떠나지 말고 축주 에게 다음의 긴급방역조치를 취하도록 지도한다. - 확산 방지를 위하여 의심축을 격리시키고 모든 사육동물(개, 고양이, 닭 등 포함)을 묶거나 축사 문을 닫아 이동하지 못하도록 한다. - 동장의 출입구를 1개소로 하고 소독조를 설치하여 방역관계자 이외에는 출입을 금지 한다. 동력분무기나 휴대용분무기가 있으면 설치한다. 또한, 각 축사의 출입구에 신발 소독조를 설치하고 이미 설치되어 있는 경우 새로운 소독약으로 교체한다. - 축주와 관리자, 가족에게 럼피스킨 정밀검사 결과가 나올 때까지 외출하지 못하도록 한다. - 농장에 차량 등이 출입하지 않도록 한다. 다만 사료 등 불가피하게 반입이 필요한 경우에는 농장 입구에서 대기토록 한다. - 농장 사육시설, 옥외, 농장 밖으로 원유, 사료, 퇴비 등을 반출하지 못하도록 한다. - 배수구를 폐쇄한다. - 가축방역관이 도착하면 모든 현장 상황을 설명하고 시료 채취 등에 협조한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 2. 의심축을 발견한 축산관련 종사자의 조치사항 2.2.3 (PDF p.42) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 45, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.3 현장에 도착한 시ㆍ도 가축방역관의 축산관련 종사자에 대한 조치사항 2.3.1 럼피스킨 확진시를 대비하여 축산관련 종사자가 의심축 신고농장을 방문한 날을 기준으로 과거 28일 전까지 방문한 감수성 가축 사욕 농장 현황을 조사한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 2. 의심축을 발견한 축산관련 종사자의 조치사항 2.3 (PDF p.43) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 46, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.3.2 정밀검사 결과가 나올 때까지 축산 관련 종사자가 농장 내에 대기토록 조치한다. - 부득이 농장을 벗어나야 할 경우에는 가축방역관이 직접 신체, 의복, 안경, 진료기구, 진료 가방 등 휴대한 기구ㆍ장비를 폐기 또는 소독한다. - 타고 온 차량에 대하여 내ㆍ외부에 대한 세차ㆍ소독을 실시한다. - 착용한 의복을 벗고 깨끗한 다른 의복 또는 일회용 방역복으로 갈아입고, 코를 풀고 입을 행군 후 다른 곳을 방문하지 않고 즉시 귀가토록 한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 2. 의심축을 발견한 축산관련 종사자의 조치사항 2.3.2 (PDF p.43) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 47, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.3.3 귀가 후 다시 차량, 진료기구, 기타 휴대용구, 의복 등을 완전히 소독하고 손, 발을 쏘 목욕한 후 다른 의복으로 갈아입도록 조치한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 2. 의심축을 발견한 축산관련 종사자의 조치사항 2.3.3 (PDF p.43) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 48, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.3.4 정밀검사 판정 시까지 외출을 삼가고 감수성 가축 사육농장 방문 및 관계자와 접촉하지 않도록 조치한다. 2.3.5 럼피스킨으로 판정될 경우 관련 차량은 세척ㆍ소독, 사람은 샤워ㆍ환복 후 환경 검사 음성인 경우 이동을 허용한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 2. 의심축을 발견한 축산관련 종사자의 조치사항 2.3.4 (PDF p.43) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 49, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '8. 발생농장 등의 청소-세척 및 소독요령 1. 기본원칙 1.1 발생농장의 최초 청소ㆍ세척 및 소독은 시ㆍ군에서 농장주와 공동으로 실시한다. 1.2 발생농장의 농장주는 재입식 시까지 주 2회이상 세척ㆍ소독을 실시한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 8 (PDF p.97) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 50, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '1.3 시ㆍ군 관계관은 매주 1회 이상 발생동장의 세척 및 소독 실시여부를 점검한다. 2. 기구 및 장비 - 농장 청소 : 농장의 규모에 따라 분뇨 운반기구 등 준비 - 세척 기구 : 고압세척기나 물호스, 브러쉬, 수세미 - 소독제, 생석회 - 소독약 및 질병 매개체 구제제 살포기구, 소독용구, 소독조, 소독통(드럼통), 바가지 등 - 피복, 장화, 모자, 장갑, 마스크, 보호안경(고글) - 삽, 곡갱이, 방역표지판 등', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 1.3 (PDF p.97) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 51, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '3. 발생농장(발생지) 청소ㆍ세척 및 소독 요령 3.1 청소ㆍ세척 및 소독프로그램 - 발생농장의 청소ㆍ세척 및 소독 등은 아래의 순서에 따라 실시한다. - 사전점검 -> 예비소독 -> 축사내 분뇨제거 -> 환경정리 ->1차 청소 ㆍ세척 및 소독 -> 1~2차 검사 -> 농장주의 재세척 및 소독(주 2회이상) -> 최종검사', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 3 (PDF p.97) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 52, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '3.2 시ㆍ군 가축방역관의 사전 점검 및 지도 - 시ㆍ군 가축방역관은 발생농장(발생지)를 사전 방문하여 발생농장 농장주에게 발생 농장 청소ㆍ세척 및 소독요령을 안내하고, 매일 1회 이상 소독 등을 실시하도록 지도ㆍ점검한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 3.2 (PDF p.97) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 53, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '3.3 예비소독 및 질병 매개체 구제 - 발생농장은 청소ㆍ세척 및 소독 실시 전에 축사내부 및 분뇨 등에 대하여 분무소독을 실시하고, 축사외부의 차량이나 사람, 동물이 접근하기 쉬운 도로 및 가옥주우 등에 대해서는 소독을 하며, 모기 등 질병 매개체에 대한 방제를 실시한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 3.3 (PDF p.97) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 54, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '3.4 축사내 분뇨제거 및 환경정리 - 축사내 분뇨를 수거하여 분뇨처리요령에 따라 처리한다. - 종장내 기구ㆍ장비ㆍ몰줌에 대하여 청소ㆍ세척ㆍ소독이 용이하도록 환경정리를 실시한다. - 세척ㆍ소독작업이 이루어지기 전에 하수도나 배수관을 막아 세척수가 발생지 이외의 지역으로 유출되지 않도록 조치한다. 필요하다면 굴착기로 구덩이를 파서 세척하는 동안 세척수의 외부누출을 방지하고 소독 완료 후 흙을 덮는 것도 좋다. - 축사 내로 연결되는 전선을 외부와 차단하여 분무소독에 의한 합선 등 화재를 방지 하는 조치를 취한다. - 축사 내 전기 콘센트, 스위치 등은 비닐로 봉하고, 세척ㆍ소독 실시 후 소독수건 으로 문질러 소독을 실시한다(전기 콘센트 등에 몰이 들어갔을 경우에는 콤프레셔를 이용하여 물기를 제거하거나 자연 건조시킴).', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 3.4 (PDF p.98) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 55, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '3.5 1차 청소ㆍ세척ㆍ소독 3.5.1 청소 - 축사내 천장 -> 벽면 -> 바닥의 순서로 세정제 겸용 소독제를 분무한 후 청소를 실시한다. - 축사내 물품ㆍ장비 등을 모두 청소하며, 구석진 곳 등 제거하기 어려운 잔존물 등은 토치 등을 이용하여 소각한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 3.5 (PDF p.98) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 56, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '3.5.2 세척 및 소독 - 소독액으로 천장 -> 벽면 -> 바닥의 순서로 세척ㆍ소독을 실시한다. - 축사 내 기구에 손상을 주지 않는 소독제를 선택하고, 유기물이 끼어 있으므로 소독약 동도를 높여 희석한다. 소독액으로 세척ㆍ소독을 동시에 실시하여 작업의 효율성을 제고한다. - 축사에 붙어 있는 분변, 사료, 깔, 먼지, 기타 오염된 물건 등은 소독수로 소독을 실시한 후 포대나 비닐몽지에 담아서 매몰 또는 소각을 하여 제거한다. - 모든 축사, 울타리, 부착기구 등은 소독약으로 간단히 세척 후 이들 부위에 부착된 유기물질, 먼지 등 이물질을 브러쉬, 수세미 등을 사용하여 철저히 제거한 후 재소독 한다. 구석진 모서리, 기자재 접합부위 등 세척ㆍ소독이 용이하지 않은 부위의 이물질을 철저히 제거하도록 한다. - 사료통, 음수통, 착유장치(젖소), 우유탱크 등은 모두 비우고 철저히 세척ㆍ소독한다. - 세척ㆍ소독과정에서 사람, 기계, 기구류에 의해 재오염되지 않도록 체계적으로 이루어져야 한다. 축사가 흙으로 되어 있는 경우 충분히 젖게 소독수를 뿌린다. - 발생농장의 축사, 사료창고, 농기구 보관함 등이 밀폐 가능한 시설인 경우 훈증 소독을 실시한다, - 축사 주위의 습지, 초지 및 오염이 가능한 환경에 대하여 축사 내부와 동일하게 소독 및 질병 매개체 방제를 실시한다. 잡초가 많은 경우에는 제거한 후 실시한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 3.5.2 (PDF p.98~99) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 57, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '3.6 1차 청소ㆍ세척ㆍ소독 실시 상황 점검 3.6.1 시ㆍ군 가축방역관은 청소ㆍ세척 및 소독 여부의 확인을 위해 별지 제4호 서식의 가축 재입식 농장 소독 등 실태 점검표에 따라 점검하고, 미흡한 부분에 대해 시정 조치하며 적합할 때까지 재점검한다. - 농장 내 모든 장비ㆍ물품ㆍ분뇨 등의 청소ㆍ세척 및 소독 여부 - 축사에 부착된 기자재나 벽면에 유기물질이나 기타 찌꺼기가 남아 있는지 - 모든 세척ㆍ소독 및 질병 매개체 방제 등이 효과적으로 이루어졌는지 - 소독 등이 완료된 축사 출입구를 폐쇄하고 농장입구에 경고표지판 부착 여부', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 3.6 (PDF p.99) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 58, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '3.7 2차 청소ㆍ세척ㆍ소독 실시 상황 점검 - 시ㆍ군에서는 1차 검사가 완료된 후, 관리지역에 대한 이동제한 해제일로부터 30일이 경과한 후, 시군에서 관련자료(별지 제4호 가축재입식농장 소독 등 실태 점검표, 현장 사진 등)를 첨부하여 시도 가축방역기관 및 검역본부에 2차 점검을 신청한다. 시도 가축방역기관과 검역본부는 합동으로 점검표에 따라 청소ㆍ세척ㆍ소독 여부를 점검 하고, 시도 가축방역기관은 환경검사를 실시하여 그 검사결과를 시군과 검역본부에 통보한다, 2차 점검 결과 미흡한 사항이 있을 시 시정 조치하고 적합할 때까지 재점검을 실시한다. - 농장주는 최종검사 전까지 1주 간격으로 2회 이상 재세척 및 소독을 실시하여야 한다. 실시방법은 1차 청소ㆍ세척-소독과 동일한 방법으로 실시한다. - 검역본부는 3차 점검 결과 및 관련 자료의 검토, 현장 확인 등을 거쳐 시군에 최종 결과를 통보한다. - 점검 결과 부적합할 경우, 부적합 사항에 대해 보완 조치하고 검역본부에 재승인을 요청한다. - 시 ㆍ군에서는 검역본부에서 승인이 통보되면 축산법에 따른 허가기준 요건 준수 여부 (수독시설 설치 등) 점검 후 최종 입식을 허용한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 3.7 (PDF p.99) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 59, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '4. 발생농장 내 사용약품ㆍ창고 등과 거주자에 대한 소독 실시요령 4.1 농장내 사용약품 - 농장 내 사용 후 남아있는 사용약품에 대하여는 매몰 등으로 폐기하거나, 창고 등에 모아 밀폐후 훈중소독 또는 소독수건 등으로 답아 소독을 실시한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 4 (PDF p.100) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 60, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '4.2 농장 내 창고ㆍ사택ㆍ사무실 - 농장 내 사료창고ㆍ축산도구 창고ㆍ사택에 대하여는 밀폐시키고, 훈증소독을 실시한다. - 농장 내 사무실(휴게실)이 있는 경우에는 일제 청소와 소독을 실시하고, 출입구에는 발판 소독조를 설치ㆍ운영하여야 한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 4.2 (PDF p.100) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 61, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '4.3 농장내 거주자(작업자)의 의복 등 - 종장 내 거주자 및 작업자의 신발(장화 등)ㆍ작업복ㆍ장갑ㆍ모자 등은 소독수에 담구어 소독하고, 세탁하여야 한다(가등하면 매몰 또는 소각을 권장).', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 4.3 (PDF p.100) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 62, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '4.4 차량ㆍ장비ㆍ도구 등 소독 실시 요령 4.4.1 차량ㆍ장비ㆍ도구 등 - 분뇨처리에 사용된 차량ㆍ장비ㆍ도구 등은 작업완료 즉시 내ㆍ외부에 묻어있는 분뇨 찌꺼기를 철저히 제거하고 소독한 다음 1일 1회 이상 세척ㆍ소독과 충분히 건조시키는 과정을 3일간 실시하고 반출을 허용한다. - 분뇨처리에 사용된 차량ㆍ장비ㆍ도구 등은 7일간 다른 감수성 가축 사욕농장 및 관련 시설에의 이동을 금지한다. 다만, 다른 발생농장에 투입되는 경우에는 가축 방역관의 감독 하에 세척ㆍ소독을 실시하고 작업에 투입할 수 있다. - 차량 등의 장비의 경우, 작업자(운전자)가 접촉되는 부위(운전대ㆍ발판ㆍ좌석 등)에 대하여도 소독수건 등을 이용하여 철저하게 소독하여야 한다. - 축주 등이 사용하는 차량에 대하여도 접촉 부위를 철저하게 소독한다. - 삽ㆍ갱이ㆍ리어카 등 동장 내 사용도구에 대하여 중분히 세척하고 수회 소독을 실시하여야 한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 4.4 (PDF p.100) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 63, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '4.4.2 소독장비의 소독 - 축사내ㆍ의 및 주변 소독에 사용한 고압분무기 등 소독장비에 대하여도 소독액을 이용하여 운반기구ㆍ고무호스ㆍ손잡이 등을 소독한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 4.4.2 (PDF p.100) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 64, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '4.4.3 농장 주변지역 소독 등 실시요령 - 농장 진입로, 농장내 주요 통행로, 축사주변, 분뇨처리장 등 오염 가능지역에 대하여 수독액이 흠백 젖도록 수회 반복하여 소독하고, 모기 등 질병 매개체에 대한 방제를 실시한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 4.4.3 (PDF p.100) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 65, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5. 발생농장 가축이 출하된 도축장의 소독 5.1 발생농장에서 출하된 가축을 도축한 도축장에 대해 아래와 같이 소독하여야 한다. - 계류장, 유도로 및 가축의 운반에 이용된 모든 차량은 유효한 소독액으로 소독 하고, 세척한 다음 다시 소독액으로 최종 소독을 실시한다. - 도살실ㆍ작업실, 식육 또는 장비의 보관 및 취급을 위해 사용된 모든 장소 또는 용기는 식품취급시설에서 사용할 수 있도록 승인된 세척제를 사용하여 고압세척을 실시한다. 다만, 도축장과 붙어있는 가공설(발골작업등) 및 예냉실ㆍ냉동실과 같은 시설은 이들 시설로부터 럼피스킨 오염 위험이 있는지를 평가한 후 소독실시 여부를 결정한다. - 탈의실, 옷장 등은 세척제를 사용하여 세척ㆍ소독을 실시하고, 가능하다면, 도축 설비는 고온스팀 등의 방법으로 소독한다. - 원피, 뿔 및 굽은 차가운 소다수에 15분 동안 침지하고, 원피는 그런 후에 냉수로 세척하고 철저하게 염지한다. - 도축장은 호스로 물을 뿌려야 하고, 출입문 및 창문을 열어 환기를 실시한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 5 (PDF p.101) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 66, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.3 시 ㆍ도지사는 당해 도축장의 세척ㆍ소독이 종료된 후 수독대상의 건조상태 등을 점검한 후 소독이 효과적으로 완료되었다고 판단되는 경우에 도축장 영업장에게 영업을 재개하도록 명령을 하여야 한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 5.3 (PDF p.101) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 67, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5.2 영업재개 후 도축장에서는 도축장 출입차량 소독요령에 따라 철저히 소독을 실시 하여야 한다. 6. 분뇨 소독 등 처리 요령 - 분뇨는 알카리제를 사용하여 08 11 이상이 되도록 소독처리한 후 3~3일간 둔 후, 산성제를 이용하여 01 6~8로 중화 후 가축분뇨 처리요령에 따라 처리한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 5.2 (PDF p.101) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 68, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '6.1 액상분뇨 소독 분뇨는 알카리제를 사용하여 08 11 이상이 되도록 소독처리하여 3~3일간 둔 후, 산성제를 이용하여 0 6~8로 중화 후 가축분뇨 처리요령에 따라 처리한다. - 액상분뇨의 101 조절 방법(예시)', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 6.1 (PDF p.101) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 69, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '0 가성소다080008 : 순도 98% 분말가루 시중 유통)를 사용하여 액상분뇨 1톤 (01.000 6 )에 1068을 혼합하여 처리 후 5일 이상 격리상태로 둔다. (2) 생석회(280 : 순도 85% 분말가루 시중 유통)를 사용하여 액상분뇨 1톤(1000. )에 206@을 혼합하여 처리 후 5일 이상 격리상태로 둔다. * 소독약 투입량은 고형분뇨의 특성에 따라 증감하여야 한다. (3) 281 11 확인은 시중에 판매되는 간1-08206를 이용하여 1 조견표에 따라 확인한다. @) 08 측정시 소독처리 된 액상분뇨를 17 정도 용기에 담아 61-ㅁ080를 2~3초간 넣었다 꺼낸 후 색깔로 판단한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 0 (PDF p.101~102) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 70, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '6.2 고형분뇨 소독 - 고형분뇨에 알카리제를 사용하여 271 11 이상이 되도록 소독처리한 후 1주일 이상 격리하여 둔다. - 고형분뇨의 9 1 조절 방법(예시) 0) 고형분뇨에 생석회(순도 90% 이상 분말가루 시중 유통)를 사용하여 1톤당 4068가 되도록 섞어서 71 11 이상이 되도록 한 후 5일 이상 격리상태로 둔다. (2 고형분뇨와 생석회 혼합방법은 분뇨 1502마다 생석회를 668/ㅁ이상 되도록 균일하게 뿌려준다. ㆍ소독약 투입량은 고형분뇨의 특성에 따라 증감하여야 한다. (3) 이때 751 11 확인은 소독된 고형분뇨 10@을 채취하여 1/ 정도 용기에 담아 물 100006를 부어 교반한 후 간+-ㅁ030를 2~3초간 넣었다 꺼낸 후 색깔로 판단한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 6.2 (PDF p.102) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 71, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '6.3 액상 및 고형분뇨의 매 조절 후 중화 및 처리방법 - 208 11이상으로 처리 후 2~3일간 경과 후 아래에 따라 산성제제를 이용하여 0 6~8#로 이상이 되도록 중화한다. - 소독 후 2~3일간 격리된 액상 및 고형분뇨는 구연산(6100 800 : 순도 94% 액상 시중 유통) 106@을 액상 및 고형분뇨 1톤(1000. )에 중화시킨다. ㆍ소독약 투입량은 고형분뇨의 특성에 따라 증감하여야 한다. - 중화된 액상 및 고형분뇨는 액비화, 퇴비화, 정화 및 위탁처리를 할 수 있다. 단, 처리 시 「가축분뇨의 관리 및 이용에 관한 법률」』에 따른 처리기준을 준수한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 6.3 (PDF p.102) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 72, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '6.4 럼피스킨 발생 이전에 생산된 퇴비ㆍ액비의 소독 및 처리 - 액비의 경우 액상분뇨의 처리와 동일하게 처리하고, 퇴비의 경우 생석회 톤당 4016를 스키드-로더 등을 이용하여 교반하여 5일 이상 보관한다. - 퇴비, 액비의 08 확인 방법은 액상 및 고형분뇨의 방법과 같다. - 교반 후 5일 이상 격리된 퇴비 및 액비는 외부 반출이 가능하다. - 럼피스킨 발생 이전에 포장이 완료된 퇴비에 대해서는 포장별 외부 소독 후 반출이 가능하다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 6.4 (PDF p.103) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 73, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '7. 적용대상에 따른 소독방법 7.1 발판 및 차량소독 - 소독조는 신발이나 차바퀴가 충분히 잠길 수 있도록 하며 주당 2~3회 교환해 준다. 7.2 토양 및 바닥소독 - 가축이 없는 축사바닥의 소독은 주로 생석회나 가성소다를 이용한다. - 생석회는 동물용의약줌이 아닌 화공약품이며 산도(08) 11-12의 강염기로서 평당 약 11을 뿌려준다. - 물을 바닥에 먼저 뿌린 후 생석회를 뿌려주거나, 물로 5% 생석회액을 만들어 살포한다. - 유제액을 만들 때는 물을 먼저 넣고 생석회를 조금씩 넣어야 하며, 보관시에는 물기가 당으면 화재가 날 우려가 있으므로 수분이 접촉하지 않도록 하고, 수위에 인화성 물질은 모두 치워야 한다. - 생석회는 물과 접촉하면 200 정도의 열을 내면서 강 알칼리와 열에 의한 소독 효과를 나타낸다. 사람과 차량이 많이 다니는 도로에는 적합하지 않으며, 절대로 사람에게 직접 망지 않도록 주의하여야 한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 8. 발생농장 등의 청소·세척 및 소독 요령 7 (PDF p.103) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 74, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '9. 소독제의 종류 및 적용 방법 1. 소독제의 종류 및 적용 1.1 소독제의 적용범위 - 소독제는 740 및 \04ㅅ1 등 국제기구에서 권장하는 소독제 및 그 유효성분이 함유되어 있는 소독제를 선택한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 9. 소독제의 종류 및 적용 방법 9 (PDF p.106) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 75, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '1.2 『40 추천 유효성분 및 소독제 1.2.1 산화제 : 차아염소산 나트륨(600147 170004104[6), 차아염소산 칼슴(08101420 11700010171108)', '럼피스킨 긴급행동지침(SOP)', '제4장 9. 소독제의 종류 및 적용 방법 1.2 (PDF p.106) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 76, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '1.2.2 알칼리제 : 가성소다(6001471 11401703106), 탄산소다(60014 0311)000ㅁ816) 1.2.3 산성제 : 구연산(01010 8010)', '럼피스킨 긴급행동지침(SOP)', '제4장 9. 소독제의 종류 및 적용 방법 1.2.2 (PDF p.106) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 77, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '1.2.4 알데하이드제제(310677068) ： 글루타알데하이드(잃버31310안706), 포르말린(10177043110), 포름알데하이드 가스({077031001706 888)', '럼피스킨 긴급행동지침(SOP)', '제4장 9. 소독제의 종류 및 적용 방법 1.2.4 (PDF p.106) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 78, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '1.2.5. \000008 : 삼종염(\/6000086941[266 0007000400), 염화나트름(80000 0410006), 사과산(00116 300)', '럼피스킨 긴급행동지침(SOP)', '제4장 9. 소독제의 종류 및 적용 방법 1.2.5 (PDF p.106) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 79, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '1.3 \0사1 추천 유효성분 1.3.1 2% 페놀(15분), 2-3% 차아염소산염, 요오드화합물제제(1:33 희석), 0.5% 4급 암모듬복합제', '럼피스킨 긴급행동지침(SOP)', '제4장 9. 소독제의 종류 및 적용 방법 1.3 (PDF p.106) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 80, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2. 소독제 선택 및 사용시 주의사항 2.1 가능한 소독제는 소독 목적물에 유효한 소독제를 선택하여야 하고, 소독 효과를 높이기 위해서는 반드시 같은 종류의 소독제제를 선정하여 사용하여야 한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 9. 소독제의 종류 및 적용 방법 2 (PDF p.106) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 81, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2.2 소독약품 사용시 아래의 안전수칙을 준수토록 한다. - 사용설명서를 충분히 읽어본 후 사용할 것 - 다른 소독제와 혼합하거나 병행하여 사용하지 말 것 - 희석배수를 반드시 지킬 것 - 사용시 마스크 등 보호장구를 착용할 것 - 소독약에 사람이 과다 노출될 경우, 즉시 물로 셋어 닐 것 - 차량 소독시 창문을 완전히 닫은 후 실시할 것 - 농산물 등을 적재한 차량은 비닐 등 사전 조치 후 소독할 것 - 오토바이 운전자에게는 우의를 사용할 것 - 소독약 살포에 따른 환경오염이 되지 않도록 조치할 것 [참고] 대상별 적용 방법 구 분 적용 방법 생축 안락사 사체 매몰 또는 소각 비누나 세정제로 세척 후 산화제(8001420 157100041014166, (31040 11\000074101166, 14000) 또는 축사/기구 알칼리제제(8001410 1140703106(페301), 80014104 08311000816 : 2011701008(찌32003), \381408 8008((페320003.10[120) 또는 구연산 또는 알데하이드제제 ((그278106[006, 1001108110, 11011781001706 888) 산화제(8001420 157100041014166, (31040 11\000074101166, 14000) 또는 주변환경 니로 이 알칼리제제(8001410 08170008[6 : 8701101008(찌32003) 또는 구연산 비누나 세정제로 세척 후 산화제(8001410 119/0004101166, (23101470 1157000010066, 10000) 또는 사람 알칼리제제(ㅎ00141 1170103406(43(0)11), ㅎ0014104 0811200816 : 2011701008(찌32003), \381408 8008((페320003.10[120) 또는 구연산 또는 알데하이드제제 ((그278106[006, 1001108110, 11011781001706 888) 전기시설 011701310001ㅠ06 885 물 매개체 서식 환경 제거 사료 매몰 또는 소각 하수, 분변 매몰 또는 살충제 비누나 세정제로 세척 후 산화제(8001410 119/0004101166, (23101470 1157000010066, 10000) 또는 알칼리제제(응0014104 1170103406(43()141), 응0014104 031200816 : 20117070048(찌20703), \8390108 8008((찌342003.10[120) 또는 구연산 주택, 차량, 기계 비누나 세정제로 세척 후 산화제(8001420 157100041014166, (31040 11\000074101166, 14000) 또는 이브 의폭 알칼리제제(ㅎ00141 1170103406(43(0)11), ㅎ0014104 0811200816 : 20119701008(쩌320703), \891408 5008((페320003.10ㅁ12()) 또는 구연산 비누나 세정제로 세척 후', '럼피스킨 긴급행동지침(SOP)', '제4장 9. 소독제의 종류 및 적용 방법 2.2 (PDF p.106~107) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 82, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '비행기 산화제(8001420 157100041014166, (31040 11\000074101166, 14000) 또는 알칼리제제(ㅎ00141 1170103406(43(0)11), ㅎ0014104 0811200816 : 20119701008(쩌320703), \891408 5008((페320003.10ㅁ12()) 또는 구연산 * 400, 14841 01 [『[000014658 10 미568366 『ㅁ18010311011 10/ 228100109-041', '럼피스킨 긴급행동지침(SOP)', '제4장 9. 소독제의 종류 및 적용 방법 (PDF p.107) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 83, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '10. 럼피스킨 매개곤충 방제요령 1. 모저 사욕농가에서의 럼피스킨(1.40007 59104ㅁ 120196896, Ｌ912) 발생 예방 및 최소화, 또는 축산관계 시설, 차량 등을 통한 럼피스킨 바이러스 전파 방지를 위해 축산관계자가 유의해야 할 렴피스킨 매개 흡혈 해충 방제에 관한 세부 요령을 제공 ※ 본 요령은 향후 새로운 정보, 과학적 자료 등이 추가로 확보되는 경우 이를 반영하여 변경될 수 있음.', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 10 (PDF p.108) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 84, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2. 방제 대상 ㅇ 럼피스킨병을 전파할 수 있는 모기, 파리, 진드기 등 흡혈 해충 @) 흡혈 해충 서식지 및 ㅁ1 흡혈 해충의 유 요추 및 알 분포지', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 2 (PDF p.108) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 85, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '3. 방제 대상별 방제 요령 < 기본 원칙 > 본 원칙 0 파리, 모기 등 흡혈 해충의 구제는 발생원 대책과 성충 대책을 유기적으로 결합하는 것이 효과적이다. ㅇ 소 사육농가 등 축산관계자는 흡혈 해충이 소에서 럼피스킨 발생 및 전파의 주요 원인임을 인식하고, 농장-축산관계시설 내부와 주변 지역의 해충 제거 또는 서식 밀도 저감, 축산차량 또는 생축 이동과정에서 해충이 부착되어 원거리로 이동하지 않도록 흡혈 해충 방제를 위해 필요한 조치를 한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 3 (PDF p.108) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 86, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '0 흘혈 해충이 소 사욱농가 등 축산시설 냐-외부로의 유입 또는 서식을 차단하는 데 있어 가장 기본은 축산시설을 청소, 세척, 소독 등을 통해 최대한 청결하게 유지 하는 것이다. - 농가는 축사 내:외를 수시로 청소, 세척 또는 소독한다. - 축사 내에 남은 사료나 분뇨는 정기적 또는 수시(럼피스킨 발생 시)로 제거한다. - 사료 급여기 밑바닥, 분뇨구 구석 등을 철저히 청소한다. - 발생원 제거를 위해 우사 주변의 풀을 까주고 분뇨처리장에 석회를 뿌리는 것도 효과적이다. ㅇ 축사 내외부에 끈끈이 트랩(080), 성충유인 트랩, 해충유살램프 등을 설치하면 흡혈 해충 방제에 더욱 효과적이다. ㅇ 유기축산물 인증농장은 살충제를 사용할 수 없으며(일반소독제는 사용 가능), 무항 생제 인증농장은 축사 내외부 방제용 제품(축제 비접촉)만 사용이 가능하다, ㅇ 축사 내부의 경우 원직적으로 빈 축사는 4주 간격으로 1회 방제한다. 불가피하게 소가 있는 축사를 방제하는 경우는 저속유압분무기로 방제약제를 소에 직접 당지 않도록 주의하여 벽면이나 바닥 등 모기나 파리가 않을 수 있는 곳에 살포한다. ㅇ 모기나 파리 유충이 서식할 수 있는 물웅덩이 등에 주기적으로 유충 구제제를 살포한다. ㅇ 축사 외부에 대한 방제 효과를 극대화하기 위해서는 다수의 방제 차량을 이용하여 축사 및 축사 주변을 동시에 방제하는 것이 효과적이다.', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 0 (PDF p.108~109) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 87, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '0 해충 방제는 해충의 습성을 알고 사용하면 효과적이다. ※ 짐집파리는 맑은 낮에는 날아다니면서 활동하지만 저녁 이후나 비가 오는 날은 날아다니지 않고 천정이나 벽에 붙어 있어 활동하지 않는 시간에 살충제를 뿌리면 소량으로 큰 효과를 개 때 을 스 이으 얻을 수 있음 @ (젖소농장 방제 시 주의사항) 젖소 적용대상 살충제 9종 이외에는 사용을 금지하 고, 축사와 축사주변에는 살충제 살포를 지양하고, 끈끈이 트랩(\ㅠ820), 성충유인 트랩, 해중유살램프 설치 등을 통해 방제를 실시한다. 가. 발생 농장 1) 공통사항 ㅇ 축사 내외부(마당, 분뇨처리장 포함)에 흡혈 해충 방제약제를 주기적으로 살포한다. ※ 농림축산식품부 “럼피스킨 긴급행동지침(600)“ 중 “8. 발생농장 등의 청소세척 및 소독요령“에 따른 조치를 한 후 흡혈 해충 서식 우려가 있는 경우 연막 또는 연무 방식 우선의 방제를 실시 하는 것이 효과적임. ㅇ 방제 가능한 최대 범위로 농장 주변(인근 수풀, 물웅덩이, 도랑 등)에 대한 방제한다. ㅇ 방제기관(지자체, 방역본부, 농협공동방제단 등), 방제전문업체는 농가 주변 지역에 대한 방제를 실시하는 경우 농장 반경 최소 1.6107 이내에 대해 연무 소독을 병행 하여 실시한다, ※ 침집파리의 경우 대부분 1.6007 이내 가죽이 있는 곳에 머물 ㅇ 살처분 작업 과정 중에는 수시로 사체 표면에 방제 약제를 살포하여 흡혈 해충이 감염축에 접촉하는 것을 차단하거나, 감염축에 접촉된 흡혈 해충이 주변으로 확산 되지 않도록 한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 0 (PDF p.109) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 88, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '0 살처분 실시 후 흡혈 해충이 산란 또는 부화하거나 양분흡수의 원천이 될 수 있는 축사 내외의 분뇨, 깔질, 방치된 건초나 사료 등 잔존물이나 주변의 식물전재물은 최대한 신속히 제거한다. ㅇ 매몰 처리 또는 대형액비저장조, 간이 『00『 등 저장조를 활용한 사체 처리 시 처리장소 주변에 고인 물 등이 흡혈 해충 서식에 적합한 환경이 되지 않도록 관리하고, 서식 우려가 있는 경우 매몰지의 생석회 도포, 저장조 및 『00 표면의 잔류성 방제약제 분무 등으로 방제 조치한다. ㅇ 사람의 접근이 어려운 흡혈 해충 서식지나 발생 농장 내 수 살처분 진행 시 드론을 이용한 항공방제를 실시하는 것도 좋은 방제방안일 수 있다. ㅇ 축산관계자가 방제에 관한 전문적 지식이 부족하거나 전문적 방제가 필요한 경우', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 0 (PDF p.109~110) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 89, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '10 1212 ㄱㄱ 12 2 ㄱㄱ 등은 전문 방제업자를 통한 방제를 고려한다. 2) 축사 시설. 장비 및 도구 ㅇ ''럼피스킨 긴급행동지침에 따라 적절히 세척-소독한 후 건조한 상태에서 방제약품을 충분히 살포한다. 나. 방역대 내 및 발생 시:군 비발생 농장 1) 일반 사항', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 10 (PDF p.110) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 90, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '0 흡혈 해충 활동 시기에 축사 및 축사 주변(마당, 분뇨처리장 등)에 예방적 차원에서 방제약품을 매일 살포한다. ㅇ 축사 안팝의 벽, 기둥 등에 잔류성 약제를 분무(가축, 사료, 물에 살포액이 당지 않도록 유의)하고, 흡혈 해충의 서식 밀도 저감을 위해 끈끈이 부착, 포집유도장비 설치 등 물리적 방제를 병행한다. ㅇ 농가 인근의 흡혈 해충 서식지(물웅덩이, 퇴비처리장 등)에 대한 연무 소독을 병행한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 0 (PDF p.110) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 91, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '0 깔싶은 최대한 건조한 상태로 유지하여 해충의 산란을 차단한다. 0 사료 보관 장소 및 주변을 청결하게 판리한다. 2) 퇴비장 및 분뇨처리장 ㅇ 온도가 45“0 이상이 되면 알, 구더기, 번데기가 죽으므로 분뇨처리장에 쌓아두는 분변에는 비닐을 덮어 내부온도를 높여주고 비닐 표면에 방제약을 도포한다. - 분뇨를 계속 쌓고 있어 비닐로 덮어둘 수 없는 경우에는 퇴비 표면에 생석회를 충분히 도포하여 해충의 접근을 차단한다. ㅇ 분뇨처리장에서 유충이 발생할 때는 톱밥, 왕겨 등으로 덮거나(약 10~20070) 또는 생석회 등을 살포(668/10)한다. ㅇ 분뇨처리장에 살충제를 살포할 때는 퇴비의 겉 표면으로부터 5~1007 밑에 구더기가 살고 있으므로 그곳까지 살충제가 스며들 수 있도록 충분히 살포한다. 다. 기타 지역 비발생 농장 ㅇ 농장 및 주변(마당, 분뇨처리장 등)에 방제약제를 예방적 차원에서 주 1회 이상 살포한다. ㅇ 축사 안과 밖의 벽, 기둥 등에 잔류성 약제를 분무(가축, 사료, 물에 살포액이 당지 않도록 유의)하고, 흡혈 해충의 서식 밀도 저감을 위한 끈끈이 부작, 포집유도장비 설치 등 물리적 방제를 병행한다. ㅇ 농가 인근의 흡혈 해충 서식지(물웅덩이, 퇴비처리장 등)에 대한 연무 소독을 병행한다. ㅇ 시군 지자체별로 광범위한 연무 소득실시 등 일제 방제한다. 라. 축산관계시설(도축장, 사료공장, 분뇨처리장, 거점소독시설 등)', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 0 (PDF p.110~111) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 92, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '0 흡혈 해충 출현 시기에는 시설 내:외부를 주기적으로 방제한다. 특히, 럼피스킨병 발생에 따른 방역대 소재 축산관계시설은 매일 1회 이상 방제한다. - 시설 안팝의 벽, 기둥 등에 잔류성 약제를 분무한다. (단, 소가 접촉하지 않는 장소에 한함) 산관계시설에는 흡혈 해충을 포집할 수 있는 장비를 설치하는 것이 바람직하다. ㅇ 축산관계시설은 전문 해충방제 업체를 통한 방제를 고려한다. ㅇ 거점소독시설은 시설 내 흡혈 해충에 없도록 수시로 방제한다 - 거점소독시설 이용 차량 운전자는 차량 내:외부에 흡혈 해충이 없도록 차량을 청결하게 유지하고, 흡혈 해충이 존재하는 경우 즉시 방제한다. - 특히, 거점소독시설 직원은 거점소독시설 이용 차량의 내외부에 흡혈 해충이 있는지를 확인한 후 있으면 즉시 방제 조치한다. 마. 축산 차량 및 생축 이동 ㅇ 대상 차량은 0 가축, 사료, 분뇨 등 운반 차량, @ 수의사, 인공수정사, 인증심사 원, 컨설턴트 등 축산시설 밀접접촉자가 운행하는 축산시설 방문 차량이다. 다만, 이외에도 럼피스킨병 전파와 관련되는 차량은 포함한다. ㅇ 럼피스킨병이 발생하는 시기에 축산 차량은 가능한 한 이동 전에 차량의 내:외부에 흡혈 해충이 있는지를 확인하고 존재 시 이에 대한 방제를 시행한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 0 (PDF p.111) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 93, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '0 수 이동 시 생체에 흡혈 해충이 부착하여 이동하지 않도록 흡혈 해충을 물리적으로 제거한다. 4. 흡혈 해충별 방제 특성 가. 파리 ㅇ 배설 후 24시간이 지난 분변을 좋아하므로 1일 1회 이상 분변을 제거하는 것이 중요하다.', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 0 (PDF p.111~112) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 94, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '0 거름, 별과 목초 같은 변패된 식물 사료, 특히 이러한 것들이 오줌과 섞인 습한 곳에 알을 낳아 번식한다. 0 성충은 흡혈하는 데 3~4분이 걸리고 흡혈 자리를 옮기거나 다른 동물로 이동하는 습성이 있다. 이 사이에 기둥, 울타리, 사료포대 등 흡혈 해충이 모여 있는 곳을 산류성 살충제로 살포하면 방제 효과를 높일 수 있다: ㅇ 소 높이 정도로 사료포대에 끈끈이를 발라서 트랩을 설치한다. ㅇ 침집파리 포집기를 설치하여 농가에 유입된 파리의 서식 밀도를 낮춘다. ㅇ 깔싶과 주변의 축축한 목초 등에 유충 방제용 약제를 살포한다. 나. 모기 ㅇ 모기 서식 장소는 다양하여 확인하기 어려우므로 물리적 방제보다는 주로 화학적 방제를 사용한다. ㅇ 농촌지역의 축사는 모기의 주요 발생지로서 유문등(모기를 수집하는 발광장치)을 이용한 물리적 방제가 효과적이다. ㅇ 모기의 흡혈 전후 모기가 쉬는 장소로 알려진 축사 안따의 벽면에 잔류용 살충제를 분무하는 것이 방제에 효과적이다. ※ 주변 안전을 고려하여 죽사 관리자와 협의하여 가죽에게 약제가 당지 않게 살포 ㅇ 유충 방제는 축사 주변의 논, 웅덩이 등으로 제한하여 방제의 효율성을 높인다. 다. 진드기 ㅇ 가축 방목 장소를 우선 방제한다. ㅇ 연 2회 이상 정기적으로 축사의 내외부에 구충제를 제품별 용법:용량에 맞게 투여한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 0 (PDF p.112) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 95, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '5. 살충제 관리 및 사용 요령 ㅇ 살충제는 제조회사에서 제공하는 제품별 사용설명서(표시 기재사항) 등에 맞게 사용한다. @ 살충제는 휘발성분이 많으므로 통풍이 잘되는 장소에 보관한다. ㅇ 살충제는 광분해 되어 살충 효력이 떨어지므로 냉암소에 보관한다. 0) 파리, 모기 등 등은 한 종류의 살 사추 충제를 연속적 으로 사용ㅎ }면 그 살충제에 대한 저항력이 증가하여 효과가 떨어지므로 살충제를 성분별(유기인계, 카바이트계, 피레스로이드계 등)로 번갈아 가며 사용한다. ㅇ 분무용이나 연막-연무용 살충제는 사용할 때는 비 오는 날이나 구름 깐 날 낮에 사용하며, 그렇지 않은 날은 저녁 무렵, 파리가 활동하지 않을 때 뿌리는 것이 효과적이다. ※ 살중제가 사료나 물에 당지 않도록 사료통이나 물통을 사료포대나 비닐로 덮은 후 뿌림. ㅇ 먹이용 살충제를 사용할 때는 파리가 좋아하는 인공유나 사료와 섞어서 사용하면 효과적이며, 이때는 파리약을 가축의 입이 당지 않는 곳에 놓아야 한다. ㅇ 축사에 바르는 지속성 살충제(도포용)는 골고루 충분히 바르며, 가축의 입이 당지 않고, 비가 들어오지 않으며, 청소할 때 겨 나가지 않도록 축사내의 벽, 천장, 기동 등에 바른다. ㅇ 살충제를 사용하면 성충이나 구더기는 구제되지만, 알은 죽지 않으므로 10일 정도의 간격으로 반복 사용한다. ㅇ 유충 구제제는 파리의 발생을 근본적으로 차단할 수 있으나 성충 방제보다는 느리며 살포 후 2주 정도면 효과를 볼 수 있다.', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 5 (PDF p.112~113) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 96, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '6. 방제 시행 및 협력체계 ㅇ 방제 효과를 높이기 위해 ''전국 일제 소독의 날''에 축사 내:외부를 일제 소독한다. ㅇ 가축방역부서, 보건부서 등이 협력하여 농장 인접 지역의 흡혈 해충에 대한 방제를 한다. ㅇ 농가에서 흡혈 해충의 방제가 효율적으로 이루어질 수 있도록 지방자치단체, 생산자 단체 등은 방제약품 안내, 방제약제 지원, 방제요령 홍보 등을 적극적으로 수행한다. ※ 필요 시 각 지자체별로 전문방제업체에 위탁하여 방제를 실시 < 참고 >', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 6 (PDF p.113) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 97, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '1. 방제 대상 흡혈 해충의 생태적 특성 2. 살충제 안전 사용 요령 < 참고 1 > 방제 대상 매개곤충의 생태적 특성 1. 일반사항 @ 파리는 보통 3월부터 보이기 시작하여 6~7월에 개체수가 가장 많으며 8월에 일시 감소하였다가 다시 증가, 11월까지 생활 ㅇ (확산) 대부분 숙주가 서식하는 곳에 머물지만, 지역 내 및 장거리 이동 가능 - (침집파리) 대부분 1.6100 이내의 가축이 있는 곳에 머무르는 경향이나 자력으로 13102까지 이동이 가능. 장거리 이동은 바람에 의한 것으로 미국(플로리다)의 경우 최대 225197 확산 사례가 있음 * 침집파리 성충 수명은 대개 2주 정도(생활사: 암컷 72일, 수컷 94일) - (모기류) 서식지(숲, 웅덩이 등)로부터 숙주를 탐색이동하는 생태 특성상 하루 이동 거리가 10여27 이상 가능. 말라리아 모기(470276/69 92/속 모기는 최대 2900 고도에서 강풍을 이겨내며 수백 이동 가능 * 모기류 암컷 성충 수명은 자연상태에서 1~2주 - (등에모기류) 활동반경은 서식지에서 수백 미터 정도이나, 기류를 타고 수백10ㅁㅁ0 이동 가능한 것으로 알려지고, 지상 170~2002ㅁ 상공에서도 포획된 바 있음 * 성중 수명은 정확하지는 않으나 실험실 환경에서 90일 정도로 확인 ㅇ (월동) 온대성 곤충으로 국내에서 겨울을 나며, 일부 따뜻한 날 또는 실내에서는 겨울철에도 활동 가능함 - (침집파리)온대지역에서 월동이나 휴면에 대해 연구된 바 없으나, 겨울철에도 활 동 가능하지만 저온(0“ㅇ 이하)에서 개체수가 급격히 감소 *발육영점온도는 11~12“0로 해당 온도 이하에서는 산란, 발육, 흡혈하지 않음 - (모기류) 일반적으로 156 이하에서는 흡혈 활동을 하지 않으며, 성충상태로 하 수도, 창고 등 음침한 곳에서 겨울을 남 - (등에모기류) 일반적으로 애벌레 상태로 겨울을 나지만 국내에서는 일부 종이 연중 채집되고, 이탈리아의 경우에는 겨울철에도 실내는 물론 실외에 설치한 트랩에서 포획된 바도 있음', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 1 (PDF p.113~114) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 98, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '2. 침파리(일명 ''무는 파리(8146 115) ) |, < 그림 1 > 짐파리 모습(좌: 배측, 우: 등측 ㅇ 가장 보편적인 파리 종류로 마굿간 파리로 알려짐', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 2 (PDF p.115) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 99, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '0 우리나라는 8~9월에 다수 번식하며, 분포지역이 점차 확대되고 있는 실정으로 지구 온난화에 따른 침파리의 개체수가 증가하는 것으로 추정함 ㅁ 생활사 및 습성 ㅇ 성충은 거름, 싶과 목초 같은 변패된 식물 사료, 특히 이러한 것들이 오줌으로 혼합되어 있는 습한 곳에 알을 낳아 번식 ㅇ 충란은 1~4일에 부화되나, 추운 날씨에서는 더 늦게 부화 ㅇ 유충은 식물성 물질을 먹는데, 따뜻한 날씨에는 14~34일간 자라서 성숙 ㅇ 여름과 가을철에 가장 번성하며, 자연적인 조건하에서는 약 1개월간 생존 ㅇ2 강한 햇빛을 즐기며, 신속하게 날아다니는 파리이지만 먼 거리를 날으려 하지 않음 ㅇ 암수 다 같이 사람, 말, 소 다른 포유동물 및 조류와 파중류까지도 공격 ㅇ 한번 흡혈하는 데에는 약 3~4분이 걸리는데, 흡혈 자리를 옮기거나, 계속 먹이를 섭취하기 위해 다른 동물로 이동', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 0 (PDF p.115) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 100, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '3. 먹파리 ㅁ 형태적 특징 과오 2072 그림 3 먹파리(성충)의 형태. (&)흡혈을 시도 중인 성충; (8)수컷과 암컷의 겹눈; (0)날개와 시맥; (0)머리와 부속지; (#)구기(00001 00065)의 단면 및 대악과 소악의 형태 ㅇ 몸의 길이는 보통 1~5 100이고, 대부분 검은색을 띠지만 일부 황색 또는 오렌지 색을 띠는 종도 있음. ㅇ 암컷의 주둥이는 매우 짧지만 큰턱과 작은턱이 넓은 칼날 모양으로 피부를 손상시켜 스며나오는 피를 흡혈 ㅁ 생활사 및 습성 ㅇ 성충은 모두 식물성 즘을 먹이로 하지만 암컷은 산란을 위해 흡혈 ㅇ 암컷은 일반적으로 개울이나 강물 속에 잠긴 돌과 수초 등에 100~500개의 알을 낳으며, 산란하는데 소요되는 시간(3~4분 정도)동안 수시로 수면을 들락날락함. ㅇ 유충은 흐르는 맑은 물속에서 서식하고, 배 끝쪽의 흡반(640(67)으로 돌 또는 수초 등에 붙어 머리를 물이 흐르는 방향으로 향하며 미세한 유기물질을 섭추 ㅇ 유충의 서식장소는 산간 계류에서부터 서서히 흐르는 강에 이르기까지 종에 따라 다양 ㅇ 물속에서 우화한 성충은 물 밖으로 나와 발생장소 근처에서 바로 짝짓기를 하고 이후 식물습 먹이를 찾으며 암컷은 곧이어 흡혈대상을 찾음. ㅇ 흡혈은 낮에 이뤄지고 주로 아침과 저녁에 활동하며, 주 흡혈원으로 포유류, 조류 이지만 극히 일부 무리는 사람을 대상으로 흡혈 ㅇ 알에서 성충까지의 발육기간은 열대지방에서 3~4주이고 온대지방에서는 6~8주 소요되며, 겨울이 추운 지방에서는 1년에 1세대 발생하고 알, 유충 및 번데기로 월동', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 3 (PDF p.115~116) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 101, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '4. 모기류(등애모기) ㅁ 형태적 특징 ~2 애매 이치 ^ 00 98 & 6 그림 3-2. 등에모기 그림 3-1. 등에모기(성충)의 외부형태(&)와 성충무리(2) 머리 @) 성충의 몸 길이는 약 1~2 퍼꺼로 사람을 흡 흡혈 하는 곤충 중에 가장 직 작음.', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 4 (PDF p.116~117) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 102, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '6 몸은 흑색 또는 암갈색을 떠고, 다리가 짧으며 날개는 특이한 시맥상과 얼룩무늬가 특징(그림3-1) ㅇ 더듬이는 긴 실모양으로 13~14마디이고, 입은 흡혈하기에 적당하지만 짧으며, 촉 수는 5마디 ㅁ 생활사 및 습성', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 6 (PDF p.117) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 103, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '0 산란 장소는 논이나 물 고인 웅덩이(늦, 호수, 저수지, 미나리밭 등) ㅇ 휴식 장소는 습기가 높고 그늘진 장소(우사주변 수풀, 호박밭, 우사내벽, 개울 영 풀숲, 고구마 밭 등)', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 0 (PDF p.117) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 104, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '0 약 30~250개의 알을 물가의 토양이나 수초에 산란하는 습성 0 흡혈원으로는 사람을 비롯한 포유류나 조류이고, 낮과 밤 모두 흡혈 활동 가능', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 0 (PDF p.117) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 105, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '0 이동은 산란과 흡혈원에 따라 수백 미터 비행 가능 0 알 또는 유충으로 월동(10월부터 4월까지) < 참고 2 > 살충제 안전사용 요령 동물용 살충제는 다음과 같은 사용상 주의사항에 따라 사용하여야 동물, 사람, 축산식품 및 환경 안전을 확보할 수 있다.', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 0 (PDF p.117) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 106, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '1. 제품의 사용설명서에 따라 사용한다. 2. 제품의 용법:용량을 준수한다. 3. 축사의 내외부 살포 시에는 사료, 물, 급이:급수 기구 등이 오염되지 않도록 조치한다.', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 1 (PDF p.117) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 107, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '4. 축제 접촉 적용 제품의 경우 대상 동물, 용법''용량, 휴약기간 등을 확인하고 반드시 준수한다. 5. 제품 취급자는 취급 시 마스크, 보호장갑, 보호안경 및 보호복 등 보호장구를 착용하고 취급 후에는 몸을 깨끗이 쓴다.', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 4 (PDF p.117) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 108, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', 'LSD', NULL, '6. 사용 내역을 기록한다. 7. 사용 시 의문사항이 있는 경우 수의사 등 전문가의 자문을 받는', '럼피스킨 긴급행동지침(SOP)', '제4장 10. 럼피스킨 매개곤충 방제요령 6 (PDF p.117) [OCR·원문대조 필요]', '2024-07-19'::date, 'draft', 109, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', NULL, NULL, '① 다음 각 호의 어느 하나에 해당하는 가축(이하 “신고대상 가축”이라 한다)의 소유자등, 신고대상 가축에 대하여 사육계약을 체결한 축산계열화사업자, 신고대상 가축을 진단하거나 검안(檢案)한 수의사, 신고대상 가축을 조사하거나 연구한 대학ㆍ연구소 등의 연구책임자 또는 신고대상 가축의 소유자등의 농장을 방문한 동물약품 또는 사료 판매자는 신고대상 가축을 발견하였을 때에는 농림축산식품부령으로 정하는 바에 따라 지체 없이 국립가축방역기관장, 신고대상 가축의 소재지를 관할하는 시장ㆍ군수ㆍ구청장 또는 시ㆍ도 가축방역기관의 장(이하 “시ㆍ도 가축방역기관장”이라 한다)에게 신고하여야 한다. 다만, 수의사 또는 제12조제6항에 따른 가축병성감정 실시기관(이하 “수의사등”이라 한다)에 그 신고대상 가축의 진단이나 검안을 의뢰한 가축의 소유자등과 그 의뢰사실을 알았거나 알 수 있었을 동물약품 또는 사료 판매자는 그러하지 아니하다. 1. 병명이 분명하지 아니한 질병으로 죽은 가축 2. 가축의 전염성 질병에 걸렸거나 걸렸다고 믿을 만한 역학조사ㆍ정밀검사ㆍ간이진단키트검사 결과나 임상증상이 있는 가축', '가축전염병 예방법', '제11조 제1항', '2020-02-04'::date, 'draft', 1, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', NULL, NULL, '② 신고대상 가축의 진단이나 검안을 의뢰받은 수의사등은 검사 결과를 지체 없이 당사자에게 통보하여야 하고 검사 결과 가축전염병으로 확인된 경우에는 수의사등과 그 신고대상 가축의 소유자등은 지체 없이 국립가축방역기관장, 신고대상 가축의 소재지를 관할하는 시장ㆍ군수ㆍ구청장 또는 시ㆍ도 가축방역기관장에게 신고하여야 한다.', '가축전염병 예방법', '제11조 제2항', '2015-06-22'::date, 'draft', 2, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', NULL, NULL, '③ 철도, 선박, 자동차, 항공기 등 교통수단으로 가축을 운송하는 자(이하 “가축운송업자”라 한다)는 운송 중의 가축이 신고대상 가축에 해당하면 지체 없이 그 가축의 출발지 또는 도착지를 관할하는 시장ㆍ군수ㆍ구청장에게 신고하여야 한다.', '가축전염병 예방법', '제11조 제3항', '2015-06-22'::date, 'draft', 3, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', NULL, NULL, '④ 제1항부터 제3항까지의 신고를 받은 행정기관의 장은 지체 없이 시ㆍ도지사 또는 특별자치시장에게 보고하거나 통보하여야 하며, 시ㆍ도지사 또는 특별자치시장은 그 내용을 국립가축방역기관장, 시장ㆍ군수ㆍ구청장 또는 시ㆍ도 가축방역기관장에게 통보하여야 한다.', '가축전염병 예방법', '제11조 제4항', '2015-06-22'::date, 'draft', 4, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', NULL, NULL, '⑤ 제1항제2호에 따라 신고를 받은 행정기관의 장은 「감염병의 예방 및 관리에 관한 법률」 제14조제1항 각 호에 해당하는 인수공통감염병인 경우에는 즉시 질병관리청장에게 통보하여야 한다.', '가축전염병 예방법', '제11조 제5항', '2020-08-11'::date, 'draft', 5, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', NULL, NULL, '⑥ 제1항부터 제5항까지의 규정에 따라 신고ㆍ보고 또는 통보를 받은 행정기관의 장은 신고자의 요청이 있는 때에는 신고자의 신원을 외부에 공개하여서는 아니 된다.', '가축전염병 예방법', '제11조 제6항', '2010-01-25'::date, 'draft', 6, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', NULL, NULL, '①법 제11조제1항 및 제3항에 따른 신고는 구두ㆍ서면 또는 전자문서로 하되, 다음 각 호의 사항이 포함되어야 한다. 1. 신고대상 가축의 소유자등의 성명(축산계열화사업자의 경우에는 회사ㆍ법인명으로 한다) 및 신고대상 가축의 사육장소 또는 발견장소 2. 신고대상 가축의 종류 및 두수 3. 질병명(수의사의 진단을 받지 아니한 때에는 신고자가 추정하는 병명 또는 발견당시의 상태) 4. 죽은 연월일(죽은 연월일이 분명하지 아니한 때에는 발견 연월일) 5. 신고자의 성명 및 주소 6. 그 밖에 가축이 죽거나 병든 원인 등 신고에 관하여 필요한 사항', '가축전염병 예방법 시행규칙', '제13조 제1항', '2020-05-28'::date, 'draft', 7, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', NULL, NULL, '②법 제11조제1항 각 호의 가축이 다음 각 호의 어느 하나에 해당되는 경우에는 같은 항에 따른 신고를 하지 아니할 수 있다. 1. 대학, 수의관련 연구기관 또는 가축병성감정실시기관이 사육중인 가축을 대상으로 학술연구활동을 수행하는 과정에서 당해 가축이 법 제11조제1항 각호의 가축에 해당하게 된 경우 2. 「약사법」에 의하여 의약품제조업 허가를 받은 자가 사육중인 가축을 대상으로 의약품 제조 및 시험활동을 수행하는 과정에서 당해 가축이 법 제11조제1항 각호의 가축에 해당하게 된 경우 3. 수출입 가축이 검역중 죽은 경우', '가축전염병 예방법 시행규칙', '제13조 제2항', '2017-01-02'::date, 'draft', 8, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', NULL, NULL, '③시장ㆍ군수ㆍ구청장은 법 제11조제1항 및 제3항에 따라 죽거나 병든 가축의 신고를 받은 때에는 가축방역관 또는 「수의사법」 제21조에 따른 공수의(이하 “공수의”라 한다)로 하여금 이를 검안 또는 진단하게 하거나 같은 법 제17조에 따라 동물병원을 개설하고 있는 수의사(이하 “동물병원개설자”라 한다)에게 검안 또는 진단을 의뢰하여야 한다.', '가축전염병 예방법 시행규칙', '제13조 제3항', '2018-05-01'::date, 'draft', 9, NULL, NULL, NULL);
INSERT INTO biosecurity_rule (kind, disease, stage, text, source_doc, clause, revised_at, status, display_order, yes_required_parts, part_code, photo_part) VALUES ('clause', NULL, NULL, '④제3항에 따라 죽거나 병든 가축의 검안 또는 진단을 의뢰받은 가축방역관ㆍ공수의 또는 동물병원개설자는 지체 없이 해당 가축을 검안 또는 진단하고 시장ㆍ군수ㆍ구청장에게 「수의사법」 제12조에 따른 검안서 또는 진단서(가축방역관의 경우에는 검안 또는 진단한 내용을 기재한 서류)를 교부하여야 한다.', '가축전염병 예방법 시행규칙', '제13조 제4항', '2018-05-01'::date, 'draft', 10, NULL, NULL, NULL);
